#include <iostream>
#include <vector>
#include <string>

using namespace std;

int n, m;
vector<string> grid;
string target = "YOKOHAMA";
int target_len = 8;
int directions[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

bool isValid(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < m;
}

int dfs(int x, int y, int index) {
    if (index == target_len - 1) return 1;

    int count = 0;
    for (int i = 0; i < 4; ++i) {
        int nx = x + directions[i][0];
        int ny = y + directions[i][1];
        if (isValid(nx, ny) && grid[nx][ny] == target[index + 1]) {
            count += dfs(nx, ny, index + 1);
        }
    }
    return count;
}

int countYokohamaTraces() {
    int count = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'Y') {
                count += dfs(i, j, 0);
            }
        }
    }
    return count;
}

int main() {
    cin >> n >> m;
    grid.resize(n);
    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
    }

    int result = countYokohamaTraces();
    cout << result << endl;

    return 0;
}

