#define reps(i,a,n) for(int i=(a);i<(n);i++)
#define rep(i,n) reps(i,0,n)
#define all(x) x.begin(),x.end()
#define pcnt(x) __builtin_popcountll(x)
#define fin(x) return cout<<x<<'\n',static_cast<void>(0)
ll myceil(ll a,ll b){return (a+b-1)/b;}
template<typename T,size_t n,size_t id=0>
auto vec(const int (&d)[n],const T &init=T()){
  if constexpr (id<n)return vector(d[id],vec<T,n,id+1>(d,init));
  else return init;
}
void SOLVE();
int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  cout<<fixed<<setprecision(16);
  #ifdef LOCAL
  clock_t start=clock();
  #endif
  int testcase=1;
  //cin>>testcase;
  for(int i=0;i<testcase;i++){
    SOLVE();
  }
  #ifdef LOCAL
  cerr<<"time:";
  cerr<<(clock()-start)/1000;
  cerr<<"ms\n";
  #endif
}
void SOLVE(){
  string s;
  cin>>s;
  int n=s.size();
  vector<vector<int>>dp(n+1,vector<int>(n+1,1e9));
  for(int l=n;l>=0;l--)for(int r=l;r<=n;r++){
    dp[l][r]=r-l;
    if(r-l<=1)continue;
    reps(i,1,r-l)if((r-l)%i==0&&(r-l)/i<10){
      bool ok=true;
      reps(j,1,(r-l)/i){
        ok&=s.substr(l,i)==s.substr(l+i*j,i);
      }
      if(ok)chmin<int>(dp[l][r],dp[l][l+i]+2+to_string((r-l)/i).size());
    }
    reps(m,l+1,r)chmin(dp[l][r],dp[l][m]+dp[m][r]);
  }
  auto dfs=[&](auto self,int l,int r)->string {
    if(l==r)return "";
    if(l+1==r)return string()+s[l];
    reps(m,l+1,r)if(dp[l][r]==dp[l][m]+dp[m][r])return self(self,l,m)+self(self,m,r);
    reps(i,1,r-l)if((r-l)%i==0&&(r-l)/i<10){
      bool ok=true;
      reps(j,1,(r-l)/i){
        ok&=s.substr(l,i)==s.substr(l+i*j,i);
      }
      if(ok&&dp[l][r]==dp[l][l+i]+2+to_string((r-l)/i).size()){
        return to_string((r-l)/i)+"("+self(self,l,l+i)+")";
      }
    }
    assert(false);
  };
  cout<<dfs(dfs,0,n)<<endl;
}

#include<bits/stdc++.h>
using namespace std;
using ll = long long;
using vll = vector<ll>;
using vvll = vector<vll>;
#define rep(i,n) for(ll i=0;i<ll(n);i++)
#define all(A) A.begin(),A.end()

vll dx = { 1,0,-1,0 };
vll dy = { 0,1,0,-1 };

const ll mod=998244353;
int main() {

    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    ll N,M;
    cin>>N>>M;
    vector<vector<pair<ll,ll>>> D(N);
    rep(i,M){
        ll A,B,C;
        cin>>A>>B>>C;
        A--;B--;C--;
        D[B].push_back({A,C});
    }
    vll DP(1<<N,0);
    DP[0]=1;
    rep(bit,1<<N){
        if(DP[bit]==0)continue;
        rep(n,N){
            if(bit&(1<<n))continue;
            ll nbit=bit+(1<<n);
            bool OK=1;
            for(auto [a,c]:D[n]){
                ll d=bit&(1<<a);
                ll e=bit&(1<<c);
                if((d>0&&e>0)||(d+e==0)){
                    OK=0;
                    break;
                }
            }
            if(OK){
                DP[nbit]+=DP[bit];
                if(DP[nbit]>=mod)DP[nbit]-=mod;
            }
        }
    }
    cout<<DP[(1<<N)-1]<<endl;
}

