using namespace std;

bool rows[500001], cols[500001];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    #ifdef BACKER
        freopen("input.txt", "r", stdin);
        // freopen("output.txt", "w", stdout);
    #endif

    int n, q;
    cin >> n >> q;
    for (int i = 1; i <= n; i++) rows[i] = cols[i] = i % 2;
    int cntc = n, cntr = n;
    while (q--) {
        string type;
        int i, tmp = 0;
        cin >> type >> i;
        if (type[0] == 'R') {
            rows[i] = !rows[i];
            if (i - 1 >= 1) {
                if (rows[i] == rows[i - 1]) tmp--;
                else tmp++;
            }
            if (i + 1 <= n) {
                if (rows[i] == rows[i + 1]) tmp--;
                else tmp++;
            }
            cntr += tmp;
        }
        else {
            cols[i] = !cols[i];
            if (i - 1 >= 1) {
                if (cols[i] == cols[i - 1]) tmp--;
                else tmp++;
            }
            if (i + 1 <= n) {
                if (cols[i] == cols[i + 1]) tmp--;
                else tmp++;
            }
            cntc += tmp;
        }
        cout << 1ll * cntr * cntc << "\n";
    }
    return 0;
}

