int main(){

    while(true){
        // 入力
        int n, m, p, q;
        cin >> n >> m >> p >> q;
        if(n == 0 && m == 0 && p == 0 && q == 0) break;

        vector<int> X(m);
        for(int i = 0; i < m; i++){
            cin >> X[i];
        }

        int fir = p;
        int proute[m] = {0};
        proute[0] = p;
        int last = q;
        int qroute[m] ={0};
        qroute[0] = q;

        for(int i = 0; i < m; i++){
            if(X[i] == fir){
                fir = X[i]+1;
            }else if(X[i]+1 == fir){
                fir = X[i];
            }

            proute[i+1] = fir;

            if(X[m-1-i] == last){
                last = X[m-1-i] + 1;
            }else if(X[m-1-i] + 1 == last){
                last = X[m-1-i];
            }

            qroute[i+1] = last;
        }

        // for(int i = 0; i <= m; i++){
        //     cout << qroute[i] << endl;
        // }

