            bool flag = true;
            for(int i = 0; i <= m; i++){
                if(abs(proute[i] - qroute[m-i]) == 1){
                    cout << min(proute[i],qroute[m-i]) << " " << i << endl;
                    flag = false;
                    break;
                }
            }

            if(flag) cout << "NG" << endl;
        }


    }
    return 0;
}

