#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using vll = vector<ll>;
using vvll = vector<vll>;
#define all(A) A.begin(),A.end()
#define rep(i, n) for (int i = 0; i < (int) (n); i++)
template<class T>
void chmax(T &p,T q){if(p<q)p=q;};
ll solve(ll N) {
    vll X(N), Y(N);
    rep(i, N)cin >> Y[i] >> X[i];
    vector<pair<ll, ll>> DP(3,{ -1,-1 });
    DP[0] = { X[0],Y[0] };
    DP[1] = { N-1,Y[0] };
    DP[2] = { N-1,N-1};
    for (ll i = 1; i < N; i++) {
        vector<pair<ll,ll>> NDP(min(N+1,2*i+3),{-1,-1});
        rep(j, min(N + 1,2*i+1)) {
            if (DP[j].first<0)continue;
            auto [x,y]=DP[j];
            if (x>X[i]||(x==X[i]&&y>=Y[i]))chmax(NDP[j], { X[i],Y[i]});
            if(j+1>N)continue;
            if(x>=X[i])chmax(NDP[j+1],{X[i],y});
            if(x> X[i])chmax(NDP[j+1],{X[i],N-1});
            if(y>=Y[i])chmax(NDP[j+1],{x,Y[i]});
            if(x>0)chmax(NDP[j+1],{x-1,Y[i]});
            if(j+2>N)continue;
            chmax(NDP[j+2],{x,y});
            if(x>0)chmax(NDP[j+2],{x-1,N-1});
        }
        swap(DP,NDP);
    }
    rep(i, N + 1)if (DP[i].second >= 0)return i;
    return 0;
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    ll H;
    while (cin >> H) {
        if (H == 0)return 0;
        cout<<solve(H)<<endl;
    }
}

