        int dis_a=0, dis_b=0
        , dis;

        int count=0, count_ans=0;
        if(n == 0) break;
        int flag=-1;
        for(int i=0; i<n; i++){
            cin >> a[i]; 
        }
        for(int i=0; i<n; i++){
            cin >> b[i];
        }

        for(int i=0; i<n; i++){
            count++;
            dis_a += a[i];
            dis_b += b[i];
            dis = dis_a - dis_b;
            if(dis == 0) continue;
            else if(dis > 0){
                flag = 1;
                break;
            }
            else if(dis < 0){
                flag = 0;
                break;
            }
        }

            for(int i=count; i<n; i++){
                dis_a += a[i];
                dis_b += b[i];
                dis = dis_a - dis_b;
                if(dis > 0){
                    if(flag == 1) continue;
                    else if(flag == 0){
                        count_ans += 1;
                        flag = 1;
                    }
                }
                else if(dis < 0){
                    if(flag == 1){
                        count_ans += 1;
                        flag = 0;
                    }
                    else if(flag == 0) continue;
                }
                else continue;
            }
            if(flag == -1) cout << "0" << endl;
            else cout << count_ans << endl;
    }
