#include <bits/stdc++.h>
using namespace std;

using i64 = long long;

int main() {
    cin.tie(nullptr)->sync_with_stdio(false);

    int n;

    auto solve = [&]() {
        vector<int> s(n), a(n), b(n);
        for (int i = 0; i < n; i++) {
            cin >> s[i];
        }

        vector pos(2, vector<int>());
        for (int i = 0; i < n; i++) {
            pos[abs(s[i]) % 2].push_back(i);
        }

        if (pos[1].size() % 2 == 1) {
            cout << "No\n";
            return;
        } else if (!pos[0].empty()) {
            int e = pos[0].back();
            pos[0].pop_back();
            pos[1].push_back(e);
            for (int i : pos[0]) {
                a[i] = b[i] = s[i] / 2;
            }
            int z = 0;
            for (int i : pos[1]) {
                z += s[i];
            }
            assert(z % 2 == 0);
            z /= 2;
            int sz = pos[1].size();
            for (int i = 0; i < sz; i++) {
                if (i == 0) {
                    for (int k = 0; k < sz; k += 2) {
                        a[pos[1][i]] += s[pos[1][k]];
                    }
                    a[pos[1][i]] -= z;
                } else {
                    a[pos[1][i]] = s[pos[1][i - 1]] - a[pos[1][i - 1]];
                }
            }
            for (int i = 0; i < sz; i++) {
                b[pos[1][i]] = a[pos[1][(i + 1) % sz]];
            }
        } else {
            int sz = pos[1].size();
            const int V = 150, S = V * sz / 2;
            vector dp(sz + 1, vector(sz + 1, vector<int>(2 * S + 1)));
            dp[0][0][S] = true;
            for (int i = 0; i < sz; i++) {
                int v = s[pos[1][i]];
                for (int j = 0; j <= i; j++) {
                    for (int k = 0; k <= 2 * S; k++) {
                        if (dp[i][j][k]) {
                            if (0 <= k + v && k + v <= 2 * S) {
                                dp[i + 1][j + 1][k + v] = true;
                            }
                            if (0 <= k - v && k - v <= 2 * S) {
                                dp[i + 1][j][k - v] = true;
                            }
                        }
                    }
                }
            }
            if (!dp[sz][sz / 2][S]) {
                cout << "No\n";
                return;
            }
            vector part(2, vector<int>());
            for (int i = sz - 1, j = sz / 2, k = S; i >= 0; i--) {
                int v = s[pos[1][i]];
                if (0 <= k - v && k - v <= 2 * S && j > 0 && dp[i][j - 1][k - v]) {
                    j--;
                    k -= v;
                    part[0].push_back(pos[1][i]);
                } else if (0 <= k + v && k + v <= 2 * S && dp[i][j][k + v]) {
                    k += v;
                    part[1].push_back(pos[1][i]);
                } else {
                    assert(false);
                }
            }
            assert(part[0].size() == part[1].size() && part[0].size() == sz / 2);
            for (int i = 0; i < sz; i++) {
                pos[1][i] = part[i % 2][i / 2];
            }
            for (int i = 1; i < sz; i++) {
                a[pos[1][i]] = s[pos[1][i - 1]] - a[pos[1][i - 1]];
            }
            for (int i = 0; i < sz; i++) {
                b[pos[1][i]] = a[pos[1][(i + 1) % sz]];
            }
        }

        cout << "Yes\n";
        for (int i = 0; i < n; i++) {
            cout << a[i] << " \n"[i + 1 == n];
        }
        for (int i = 0; i < n; i++) {
            cout << b[i] << " \n"[i + 1 == n];
        }
        #ifdef LOCAL
        for (int i = 0; i < n; i++) {
            assert(a[i] + b[i] == s[i]);
        }
        assert(multiset<int>(a.begin(), a.end()) == multiset<int>(b.begin(), b.end()));
        #endif
    };

    while (cin >> n && n != 0) {
        solve();
    }

    return 0;
}

// AOJ #3600 Sum of Product of Binomial Coefficients
// 2025.3.3

#include <iostream>
using namespace std;
using ll = long long;
const ll MOD = 998244353;

#define gc() getchar_unlocked()
#define pc(c) putchar_unlocked(c)

int Cin() {  // 整数の入力
    int n = 0, c = gc();
    do n = 10*n + (c & 0xf), c = gc(); while (c >= '0');
    return n;
}

void Cout(int n) { // 整数の表示（出力）
    char b[30];
    if (!n) pc('0');
    else {
        if (n < 0) pc('-'), n = -n;
        int i = 0; while (n) b[i++] = n % 10 + '0', n /= 10;
        while (i--) pc(b[i]);
    }
    pc('\n');
}

ll modexp(ll a, ll b) {
    ll r = 1;
    a %= MOD;
    while(b) {
        if(b & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1;
    }
    return r;
}

int main(){
    int T = Cin();
    while(T--){
        ll N = Cin();
        int K = Cin();
        ll ans = 0;
        if(N == 0) ans = K;
        else {
            int i = 1;
            while (i <= K) ans = (ans + modexp(++i, N)) % MOD;
        }
        Cout(ans);
    }
    return 0;
}

