// AOJ #3613
// Break a Prison 2025.1.28

#include <bits/stdc++.h>
using namespace std;

// 移動方向を表すベクトル (上, 右, 下, 左)
const int dr[4] = {-1, 0, 1, 0};
const int dc[4] = {0, 1, 0, -1};
bool visited[501][501][5]; 

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);

    int n, m;
    cin >> n >> m;

    vector<string> grid(n);
    int sr, sc; // start
    int er, ec; // exit
    for(int i = 0; i < n; i++){
        cin >> grid[i];
        for(int j = 0; j < m; j++){
            if(grid[i][j] == 'S') sr = i, sc = j;
            else if(grid[i][j] == 'E') er = i, ec = j;
        }
    }

    // BFS 用キュー: (行, 列, 進行方向, 移動回数)
    queue<tuple<int,int,int,int>> que;

    // スタート地点をキューに入れる (方向は4で初期化, 移動回数0)
    visited[sr][sc][4] = true;
    que.push({sr, sc, 4, 0});

    // BFS 開始
    while(!que.empty()){
        auto [r, c, d, dist] = que.front();
        que.pop();

        // もし出口に到達したら dist を出力して終了
        if(r == er && c == ec){
            cout << dist << endl;
            return 0;
        }

        // 次の方向として 0～3 を試す (上, 右, 下, 左)
        for(int nd = 0; nd < 4; nd++){
            // もし d != 4 なら右折 (nd == (d+1)%4) を禁止
            if(d != 4 && nd == (d + 1) % 4){
                continue; // 右折となるのでスキップ
            }
            int nr = r + dr[nd];
            int nc = c + dc[nd];

            // 範囲内 & 監視対象('#') でない & 未訪問 なら移動可能
            if(nr >= 0 && nr < n && nc >= 0 && nc < m){
                if(grid[nr][nc] != '#' && !visited[nr][nc][nd]){
                    visited[nr][nc][nd] = true;
                    que.push({nr, nc, nd, dist + 1});
                }
            }
        }
    }

    // BFS ですべて探索しても出口に辿り着けない場合は -1 を出力
    cout << -1 << endl;
    return 0;
}

// AOJ #3614
// Camp room assignment 2025.2.1

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll MOD = 998244353;

#define gc() getchar_unlocked()
#define pc(c) putchar_unlocked(c)

int Cin() {   // 非負整数の入力
    int n = 0; int c = gc();
    do n = 10 * n + (c & 0xf); while ((c = gc()) >= '0');
    return n;
}

void Cout(int n) { // 非負整数の表示（出力）
    char b[30];
    if (!n) pc('0');
    else {
        //      if (n < 0) pc('-'), n = -n;
        int i = 0; while (n) b[i++] = n % 10 + '0', n /= 10;
        while (i--) pc(b[i]);
    }
    pc('\n');
}

ll modexp(ll base, ll exp, ll mod=MOD) {
    ll res = 1;
    base %= mod;
    while(exp > 0) {
        if(exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

void precomputeFactorials(int n_max, vector<ll>& fact, vector<ll>& invfact) {
    fact.resize(n_max+1);
    invfact.resize(n_max+1);
    fact[0] = 1;
    for (int i = 1; i <= n_max; i++)
        fact[i] = fact[i-1] * i % MOD;
    invfact[n_max] = modexp(fact[n_max], MOD-2, MOD);
    for (int i = n_max; i > 0; i--)
        invfact[i-1] = invfact[i] * i % MOD;
}

ll binom(int n, int k, const vector<ll>& fact, const vector<ll>& invfact) {
    if(k < 0 || k > n) return 0;
    return fact[n] * ((invfact[k] * invfact[n-k]) % MOD) % MOD;
}

// Main function
int main(){
    int m = Cin();
    int M = 2 * m;
    vector<ll> fact, invfact;
    precomputeFactorials(M, fact, invfact);

    ll x = ((ll)m - 1) % MOD;
    if(x < 0) x += MOD;

    int maxPow = m + 1;
    vector<ll> powX(maxPow+1, 0);
    powX[0] = 1;
    for (int i = 1; i <= maxPow; i++)
        powX[i] = (powX[i-1] * x) % MOD;

    ll mm2 = ((ll)m * m) % MOD;
    vector<ll> powM2(m+1, 0);
    powM2[0] = 1;
    for (int i = 1; i <= m; i++)
        powM2[i] = (powM2[i-1] * mm2) % MOD;

    ll onePlusX = (1 + x) % MOD;
    ll c = (onePlusX * onePlusX) % MOD;

    vector<ll> A(m+1, 0);
    A[1] = 1;
    for (int n = 1; n < m; n++){
        ll term1 = binom(2*n, n, fact, invfact);
        ll term2 = binom(2*n, n-1, fact, invfact);
        ll add1 = (term1 * powX[n]) % MOD;
        ll add2 = (term2 * powX[n+1]) % MOD;
        ll nextA = ( c * A[n] ) % MOD;
        nextA = ( nextA + add1 ) % MOD;
        nextA = ( nextA + MOD - add2 ) % MOD;
        A[n+1] = nextA;
    }
    for (int n = 1; n <= m; n++){
        ll ans = ( powM2[n] + MOD - ( (ll)m * A[n] ) % MOD ) % MOD;
        Cout(ans);
    }
    return 0;
}

// AOJ #3616 Gacha 101
// 2025.3.8

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll M = 998244353;

#define gc() getchar_unlocked()
#define pc(c) putchar_unlocked(c)

int Cin() {  // 整数の入力
    int n = 0, c = gc();
    do n = 10*n + (c & 0xf), c = gc(); while (c >= '0');
    return n;
}

void Cout(int n) { // 整数の表示（出力）
    char b[30];
    if (!n) pc('0');
    else {
        int i = 0; while (n) b[i++] = n % 10 + '0', n /= 10;
        while (i--) pc(b[i]);
    }
    pc('\n');
}

ll modexp(ll b, ll e) {
    ll r = 1;
    b %= M;
    while(e){
        if(e & 1) r = (r * b) % M;
        b = (b * b) % M;
        e >>= 1;
    }
    return r;
}

int main() {
    int N = Cin();
    vector<ll> a(N);
    ll S = 0;
    for (int i=0; i<N; i++) a[i] = Cin(), S += a[i];

    vector<ll> p(N+1,0);
    for (int i=1; i<=N; i++){
        p[i] = p[i-1] + a[i-1];
    }

    vector<ll> L(N+1, 0);
    L[0] = 1;
    for (int i=1; i<=N; i++){
        ll inv = modexp(p[i], M-2);
        L[i] = (L[i-1] * (a[i-1] % M)) % M;
        L[i] = (L[i] * inv) % M;
    }

    vector<ll> suf(N+2, 0);
    suf[N] = a[N-1];
    for (int i = N-1; i>=1; i--){
        suf[i] = suf[i+1] + a[i-1];
    }
    vector<ll> R(N+2, 0);
    R[N+1] = 1;
    R[N] = (a[N-1] % M) * modexp(suf[N] % M, M-2) % M;
    for (int i=N-1; i>=1; i--){
        ll inv = modexp(suf[i] % M, M-2);
        R[i] = ( (a[i-1] % M) * inv ) % M;
        R[i] = (R[i] * R[i+1]) % M;
    }

    ll no = 0;
    ll invS = modexp(S % M, M-2);
    for (int f = 1; f <= N; f++){
        ll t = (a[f-1] % M) * invS % M;
        t = t * L[f-1] % M;
        if(f < N) t = t * R[f+1] % M;
        no = (no + t) % M;
    }
    ll ans = (1 - no) % M;
    if(ans < 0) ans += M;
    Cout(ans);
    return 0;
}

// AOJ #3619
// LCP Queries 2026.2.8

#include <bits/stdc++.h>
using namespace std;
using ull = unsigned long long;
using ll = long long;

static const ull BASE = 131ULL;

vector<ull> powerArr;

void precomputePowers(int n) {
    powerArr.resize(n+1);
    powerArr[0] = 1;
    for (int i = 1; i <= n; i++){
        powerArr[i] = powerArr[i-1] * BASE;
    }
}

struct TrieNode {
    int nxt[26];
    int parent;
    char letter;
    int count;
    int depth;
    int childCount;
    TrieNode(){
        memset(nxt, -1, sizeof(nxt));
        parent = -1;
        letter = 0;
        count = 0;
        depth = 0;
        childCount = 0;
    }
};

vector<TrieNode> trie;

void insertTrie(const string &s) {
    int cur = 0;
    trie[cur].count++;
    for (char c : s) {
        int idx = c - 'a';
        if(trie[cur].nxt[idx] == -1){
            trie[cur].nxt[idx] = trie.size();
            TrieNode newNode;
            newNode.parent = cur;
            newNode.letter = c;
            newNode.depth = trie[cur].depth + 1;
            trie.push_back(newNode);
            trie[cur].childCount++;
        }
        cur = trie[cur].nxt[idx];
        trie[cur].count++;
    }
}

vector<int> chainId;
vector<int> chainIndex;

struct ChainSegment {
    vector<int> nodes;
    vector<char> letters;
    vector<ll> ps;
    vector<ull> hashArr;
};

vector<ChainSegment> chains;

void assignChainSegment(int head) {
    int segId = chains.size();
    ChainSegment seg;
    int cur = head;
    int idx = 0;
    while (true) {
        chainId[cur] = segId;
        chainIndex[cur] = idx;
        seg.nodes.push_back(cur);

        if(trie[cur].childCount == 1) {
            int nextNode = -1;
            for (int c = 0; c < 26; c++){
                int child = trie[cur].nxt[c];
                if(child != -1){
                    if(nextNode == -1) nextNode = child;
                    else { nextNode = -2; break; }
                }
            }
            if(nextNode >= 0){
                cur = nextNode;
                idx++;
                continue;
            }
        }
        break;
    }
    int segSize = seg.nodes.size();
    if(segSize > 1) {
        seg.letters.resize(segSize - 1);
        for (int i = 1; i < segSize; i++){
            seg.letters[i-1] = trie[ seg.nodes[i] ].letter;
        }
    }
    seg.ps.resize(segSize);
    seg.ps[0] = 0;
    for (int i = 1; i < segSize; i++){
        seg.ps[i] = seg.ps[i-1] + trie[ seg.nodes[i] ].count;
    }
    seg.hashArr.resize(seg.letters.size() + 1);
    seg.hashArr[0] = 0;
    for (int i = 0; i < seg.letters.size(); i++){
        seg.hashArr[i+1] = seg.hashArr[i] * BASE + (ull)(seg.letters[i] - 'a' + 1);
    }
    chains.push_back(move(seg));
}

void dfsAssignChains(int v) {
    for (int c = 0; c < 26; c++){
        int child = trie[v].nxt[c];
        if(child == -1) continue;
        if(chainId[child] == -1) {
            if(v == 0 || trie[v].childCount != 1) {
                assignChainSegment(child);
            }
        }
        dfsAssignChains(child);
    }
}

void buildChainSegments() {
    int nNodes = trie.size();
    chainId.assign(nNodes, -1);
    chainIndex.assign(nNodes, -1);
    assignChainSegment(0);
    dfsAssignChains(0);
}

struct Tstring {
    string s;
    vector<ull> hashArr;
};

vector<Tstring> tStrings;

void computeHashForT(Tstring &ts) {
    int len = ts.s.size();
    ts.hashArr.resize(len+1);
    ts.hashArr[0] = 0;
    for (int i = 0; i < len; i++) {
        ts.hashArr[i+1] = ts.hashArr[i] * BASE + (ull)(ts.s[i]-'a'+1);
    }
}


inline ull getSubstringHash_T(const vector<ull> &tHash, int pos, int len) {
    return tHash[pos + len] - tHash[pos] * powerArr[len];
}

inline ull getSubstringHash_chain(const vector<ull> &chainHash, int pos, int len) {
    return chainHash[pos + len] - chainHash[pos] * powerArr[len];
}


int binarySearchMatch(const vector<ull> &tHash, int tPos, int limit, const vector<ull> &chainHash, int chainPos) {
    int low = 0, high = limit + 1;
    while(high - low > 1){
        int mid = (low + high) / 2;
        ull hashT = getSubstringHash_T(tHash, tPos, mid);
        ull hashChain = getSubstringHash_chain(chainHash, chainPos, mid);
        if(hashT == hashChain) low = mid;
        else high = mid;
    }
    return low;
}

ll simulateQuery(const vector<int> &tIndices) {
    ll ans = 0;
    int curNode = 0;
    for (int idx : tIndices) {
        if(curNode == -1) break;
        Tstring &ts = tStrings[idx];
        int tlen = ts.s.size();
        int pos = 0;
        while(pos < tlen && curNode != -1) {
            int cid = chainId[curNode];
            int cindex = chainIndex[curNode];
            ChainSegment &seg = chains[cid];
            int available = (int) seg.letters.size() - cindex;
            int remaining = tlen - pos;

            if(available > 0){
                int jumpLimit = min(available, remaining);
                int Lmatch = binarySearchMatch(ts.hashArr, pos, jumpLimit, seg.hashArr, cindex);
                if(Lmatch > 0){
                    ans += seg.ps[cindex + Lmatch] - seg.ps[cindex];
                    curNode = seg.nodes[cindex + Lmatch];
                    pos += Lmatch;
                    continue;
                }
            }
            char c = ts.s[pos];
            int letterIndex = c - 'a';
            if(trie[curNode].nxt[letterIndex] == -1) {
                curNode = -1;
                break;
            } else {
                curNode = trie[curNode].nxt[letterIndex];
                ans += trie[curNode].count;
                pos++;
            }
        }
        if(curNode == -1) break;
    }
    return ans;
}


int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);

    int n;
    cin >> n;
    trie.reserve(210000);
    trie.push_back(TrieNode());

    string s;
    for (int i = 0; i < n; i++){
        cin >> s;
        insertTrie(s);
    }

    buildChainSegments();

    precomputePowers(210000);

    int m;
    cin >> m;
    tStrings.resize(m);
    for (int i = 0; i < m; i++){
        cin >> s;
        tStrings[i].s = s;
        computeHashForT(tStrings[i]);
    }

    int q;
    cin >> q;
    for (int qi = 0; qi < q; qi++) {
        int k;
        cin >> k;
        vector<int> indices(k);
        for (int i = 0; i < k; i++){
            int tmp;
            cin >> tmp;
            indices[i] = tmp - 1;
        }
        ll answer = simulateQuery(indices);
        cout << answer << endl;
    }
    return 0;
}

// AOJ #3627 Expression Sum
// 2025.4.19

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int MOD = 998244353;

int add(int a, int b){ a += b; if(a >= MOD) a -= MOD; return a; }
int mul(long long a, long long b){ return int(a * b % MOD); }

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);

    string S;
    cin >> S;
    int n = S.size();

    vector<int> v0(n+2,0), s0(n+2,0),
                v1(n+2,0), s1(n+2,0), p1(n+2,0),
                v2(n+2,0), s2(n+2,0);
    vector<int> u0(n+2,0), t0(n+2,0),
                u1(n+2,0), t1(n+2,0), q1(n+2,0),
                u2(n+2,0), t2(n+2,0);

    v0[0] = 1;

    for(int i = 0; i < n; i++){
        fill(u0.begin(), u0.end(), 0);
        fill(t0.begin(), t0.end(), 0);
        fill(u1.begin(), u1.end(), 0);
        fill(t1.begin(), t1.end(), 0);
        fill(q1.begin(), q1.end(), 0);
        fill(u2.begin(), u2.end(), 0);
        fill(t2.begin(), t2.end(), 0);

        char c = S[i];
        for(int b = 0; b <= n; b++){
            int c0 = v0[b], e0 = s0[b];
            int c1 = v1[b], e1 = s1[b], w1 = p1[b];
            int c2 = v2[b], e2 = s2[b];

            if(c=='(' || c=='?'){
                if(b+1 <= n){
                    u0[b+1] = add(u0[b+1], c0);
                    t0[b+1] = add(t0[b+1], e0);
                }
            }
            if(c=='?' || isdigit(c)){
                bool ok0 = (c=='?' || c=='0');
                if(ok0){
                    u2[b] = add(u2[b], c0);
                    t2[b] = add(t2[b], e0);
                }
                int cnt9 = 0, sum9 = 0;
                if(c=='?') cnt9 = 9, sum9 = 45;
                else if(c>='1' && c<='9') cnt9 = 1, sum9 = c - '0';
                if(cnt9){
                    u1[b] = add(u1[b], mul(c0, cnt9));
                    t1[b] = add(t1[b], mul(e0, cnt9));
                    q1[b] = add(q1[b], mul(c0, sum9));
                }
            }

            if(c1){
                if(c=='?' || isdigit(c)){
                    int cntD=0, sumD=0;
                    if(c=='?'){ cntD=10; sumD=45; }
                    else{ cntD=1; sumD=c-'0'; }
                    u1[b] = add(u1[b], mul(c1, cntD));
                    t1[b] = add(t1[b], mul(e1, cntD));
                    q1[b] = add(q1[b],
                        add( mul(mul(w1,10), cntD),
                             mul(c1, sumD) ));
                }
                int totEndC = add(e1, w1);
                if(c=='+' || c=='?'){
                    u0[b] = add(u0[b], c1);
                    t0[b] = add(t0[b], totEndC);
                }
                if(b>0 && (c==')' || c=='?')){
                    u2[b-1] = add(u2[b-1], c1);
                    t2[b-1] = add(t2[b-1], totEndC);
                }
            }

            if(c2){
                if(c=='+' || c=='?'){
                    u0[b] = add(u0[b], c2);
                    t0[b] = add(t0[b], e2);
                }
                if(b>0 && (c==')' || c=='?')){
                    u2[b-1] = add(u2[b-1], c2);
                    t2[b-1] = add(t2[b-1], e2);
                }
            }
        }

        v0.swap(u0); s0.swap(t0);
        v1.swap(u1); s1.swap(t1); p1.swap(q1);
        v2.swap(u2); s2.swap(t2);
    }

    vector<int> final2(n+2,0), finalS(n+2,0);
    for(int b=0;b<=n;b++){
        final2[b] = add(final2[b], v2[b]);
        finalS[b] = add(finalS[b], s2[b]);
        if(v1[b]){
            final2[b] = add(final2[b], v1[b]);
            finalS[b] = add(finalS[b], add(s1[b], p1[b]));
        }
    }

    int ans = finalS[0];
    cout << ans << endl;
    return 0;
}

// AOJ #3629 Give Me a Lot of Triangles
// 2025.3.10

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

#define gc() getchar_unlocked()
#define pc(c) putchar_unlocked(c)

int Cin() {  // 整数の入力
    int n = 0, c = gc();
    do n = 10*n + (c & 0xf), c = gc(); while (c >= '0');
    return n;
}

void Cout(ll n) { // 整数の表示（出力）
    char b[30];
    if (!n) pc('0');
    else {
        if (n < 0) pc('-'), n = -n;
        int i = 0; while (n) b[i++] = n % 10 + '0', n /= 10;
        while (i--) pc(b[i]);
    }
    pc('\n');
}

int main(){
    int T = Cin();
    while(T--){
        int a = Cin(), b = Cin(), c = Cin();
        ll ans = 0;
        for (int i = 0; i < 3; i++){
            for (int j = 0; j < 3; j++){
                for (int k = 0; k < 3; k++){
                    for (int l = 0; l < 3; l++){
                        ll ra = a - (i + j);
                        ll rb = b - (2LL*i + 2LL*k + l);
                        ll rc = c - (2LL*j + k + 2LL*l);
                        if(ra < 0 || rb < 0 || rc < 0) continue;
                        ll eq = ra/3 + rb/3 + rc/3;
                        ans = max(ans, (ll)(i+j+k+l) + eq);
                    }
                }
            }
        }
        Cout(ans);
    }
    return 0;
}

// AOJ #3630 Half Plane Painting
// 2025.4.26

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

#define gc() getchar_unlocked()

int Cin() {
    int n = 0; int c = gc();
    if (c == '-') { c = gc();
        do n = 10*n + (c & 0xf), c = gc(); while (c >= '0');
        return -n;
    }
    do n = 10*n + (c & 0xf), c = gc(); while (c >= '0');
    return n;
}

const int MAXN = 4000;
struct P { ll x, y; };
bitset<MAXN> bitL[MAXN], bitR[MAXN];
int cntL[MAXN], cntR[MAXN];
bool used[MAXN], inq[MAXN];
int q[MAXN];

int main(){
    int N = Cin();
    vector<P> p(N);
    for(int i = 0; i < N; i++) p[i].x = Cin(), p[i].y = Cin();

    for(int k = 0; k < N; k++){
        auto &A = p[k];
        auto &B = p[(k+1)%N];
        for(int e = 0; e < N; e++){
            if(e == k) continue;
            auto &C = p[e];
            auto &D = p[(e+1)%N];
            ll c1 = (B.x - A.x) * (C.y - A.y) - (B.y - A.y) * (C.x - A.x);
            ll c2 = (B.x - A.x) * (D.y - A.y) - (B.y - A.y) * (D.x - A.x);
            if(c1 < 0 || c2 < 0) bitL[k].set(e);
            if(c1 > 0 || c2 > 0) bitR[k].set(e);
        }
        cntL[k] = bitL[k].count();
        cntR[k] = bitR[k].count();
    }

    int ql = 0, qr = 0, sel = 0;
    for(int i = 0; i < N; i++){
        if(cntL[i] == 0 || cntR[i] == 0){
            q[qr++] = i;
            inq[i] = true;
        }
    }

    while(ql < qr){
        int e = q[ql++];
        inq[e] = false;
        if(used[e]) continue;
        used[e] = true;
        sel++;
        for(int k = 0; k < N; k++){
            if(used[k]) continue;
            if(bitL[k].test(e)){
                bitL[k].reset(e);
                if(--cntL[k] == 0 && !inq[k]){
                    q[qr++] = k;
                    inq[k] = true;
                }
            }
            if(bitR[k].test(e)){
                bitR[k].reset(e);
                if(--cntR[k] == 0 && !inq[k]){
                    q[qr++] = k;
                    inq[k] = true;
                }
            }
        }
    }
    cout << (sel == N ? "Yes" : "No") << endl;
    return 0;
}

// AOJ #3631 I Love Square Number
// 2025.3.31

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using ull = unsigned long long;

#define gc() getchar_unlocked()
#define pc(c) putchar_unlocked(c)

int Cin() {
    int n = 0, c = gc();
    do n = 10*n + (c & 0xf), c = gc(); while (c >= '0');
    return n;
}

void Cout(ll n) {
    char b[30];
    if (!n) pc('0');
    else {
        if (n < 0) pc('-'), n = -n;
        int i = 0; while (n) b[i++] = n % 10 + '0', n /= 10;
        while (i--) pc(b[i]);
    }
    pc('\n');
}

const int MAXV = 1000000;
vector<int> spf(MAXV+5);

void buildSpf(){
    for (int i = 1; i <= MAXV; i++) spf[i] = i;
    for (int i = 2; i * i <= MAXV; i++)
        if (spf[i] == i)
            for (int j = i * i; j <= MAXV; j += i) if (spf[j] == j) spf[j] = i;
}

unordered_map<int, ull> H;
mt19937_64 rng((unsigned)chrono::steady_clock::now().time_since_epoch().count());

ull sf(int x) {
    ull r = 0;
    while(x > 1){
        int p = spf[x], c = 0;
        while(x % p == 0){ c++; x /= p; }
        if(c & 1) {
            if(H.find(p) == H.end()) H[p] = rng();
            r ^= H[p];
        }
    }
    return r;
}

inline int idx(int r, int p){ return r*(r+1)/2 + p; }

int main(){
    buildSpf();

    int n = Cin();
    vector<vector<int>> A(n-1), B(n-1);
    for (int r = 0; r < n-1; r++){
        A[r].resize(r+1);
        for (int j = 0; j <= r; j++) A[r][j] = Cin();
    }
    for (int r = 0; r < n-1; r++){
        B[r].resize(r+1);
        for (int j = 0; j <= r; j++) B[r][j] = Cin();
    }
    vector<vector<int>> C(n-1);
    for (int r = 1; r < n; r++){
        C[r-1].resize(r);
        for (int j = 0; j < r; j++) C[r-1][j] = Cin();
    }

    int tot = n*(n+1)/2;
    vector<vector<pair<int,ull>>> g(tot);

    for (int r = 0; r < n-1; r++){
        for (int j = 0; j <= r; j++){
            int u = idx(r, j), v = idx(r+1, j);
            ull w = sf(A[r][j]);
            g[u].push_back({v, w});
            g[v].push_back({u, w});
        }
    }
    for (int r = 0; r < n-1; r++){
        for (int j = 0; j <= r; j++){
            int u = idx(r, j), v = idx(r+1, j+1);
            ull w = sf(B[r][j]);
            g[u].push_back({v, w});
            g[v].push_back({u, w});
        }
    }
    for (int r = 1; r < n; r++){
        for (int j = 0; j < r; j++){
            int u = idx(r, j), v = idx(r, j+1);
            ull w = sf(C[r-1][j]);
            g[u].push_back({v, w});
            g[v].push_back({u, w});
        }
    }

    vector<int> vis(tot,0);
    vector<ull> f(tot, 0);
    ll ans = 0;
    for (int s = 0; s < tot; s++){
        if(!vis[s]){
            vector<int> comp;
            bool ok = true;
            deque<int> dq;
            dq.push_back(s);
            vis[s] = 1;
            f[s] = 0;
            comp.push_back(s);
            while(!dq.empty()){
                int u = dq.front(); dq.pop_front();
                for(auto &e : g[u]){
                    int v = e.first; ull w = e.second;
                    ull nv = f[u] ^ w;
                    if(!vis[v]){
                        vis[v] = 1;
                        f[v] = nv;
                        dq.push_back(v);
                        comp.push_back(v);
                    } else if(f[v] != nv) ok = false;
                }
            }
            if(ok){
                unordered_map<ull, ll> mp;
                for(auto v : comp) mp[f[v]]++;
                for(auto &p : mp){
                    ll m = p.second;
                    ans += m*(m-1LL)/2;
                }
            }
        }
    }
    Cout(ans);
    return 0;
}

// AOJ #3636 Noncoprime Subsequences
// 2025.4.20

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

#define gc() getchar_unlocked()
#define pc(c) putchar_unlocked(c)

int Cin() {
    int n = 0; int c = gc();
    do n = 10*n + (c & 0xf), c = gc(); while (c >= '0');
    return n;
}

void Couts(const string &s) {
    for (char c : s) pc(c);
    pc('\n');
}

const int MAXA = 1000000;
const int MOD  = 998244353;

int spf[MAXA+1];
int dp_len[MAXA+1];
int dp_cnt[MAXA+1];

int main(){
    int N = Cin();
    vector<int> A(N);
    for(int i = 0; i < N; i++) A[i] = Cin();

    for(int i = 2; i <= MAXA; i++){
        if(spf[i] == 0) for(int j = i; j <= MAXA; j += i) if(spf[j] == 0) spf[j] = i;
    }

    int  L = 0;
    ll ans = 0;

    static int ds[1<<7], dsH[1<<7];
    vector<int> ps; ps.reserve(7);
    vector<int> H;  H.reserve(7);

    for(int x : A){
        ps.clear();
        int t = x;
        while(t > 1){
            int p = spf[t];
            ps.push_back(p);
            while(t % p == 0) t /= p;
        }

        int best = 0;
        for(int p : ps) best = max(best, dp_len[p]);

        ll cnt;
        if(best == 0) cnt = 1;
        else {
            H.clear();
            for(int p : ps) if(dp_len[p] == best) H.push_back(p);

            int k = (int)H.size();
            int M = 1 << k;
            dsH[0] = 1;
            for(int mask = 1; mask < M; mask++){
                int lsb = mask & -mask;
                int i   = __builtin_ctz(lsb);
                dsH[mask] = dsH[mask ^ lsb] * H[i];
            }
            cnt = 0;
            for(int mask = 1; mask < M; mask++){
                int d = dsH[mask];
                if(dp_len[d] == best){
                    if(__builtin_popcount(mask) & 1) cnt = (cnt + dp_cnt[d]) % MOD;
                    else                             cnt = (cnt - dp_cnt[d] + MOD) % MOD;
                }
            }
        }

        int curL = best + 1;
        if(curL > L) L = curL, ans = cnt;
        else if(curL == L) ans = (ans + cnt) % MOD;

        int m = (int)ps.size();
        int M = 1 << m;
        ds[0] = 1;
        for(int mask = 1; mask < M; mask++){
            int lsb = mask & -mask;
            int i   = __builtin_ctz(lsb);
            ds[mask] = ds[mask ^ lsb] * ps[i];
        }
        for(int mask = 1; mask < M; mask++){
            int d = ds[mask];
            if(dp_len[d] < curL){
                dp_len[d] = curL;
                dp_cnt[d] = (int)(cnt % MOD);
            } else if(dp_len[d] == curL) dp_cnt[d] = (dp_cnt[d] + (int)(cnt % MOD)) % MOD;
        }
    }
    cout << L << endl;
    cout << (ans % MOD + MOD) % MOD << endl;
    return 0;
}

