// AOJ #3638
// Renovation 2025.1.24

#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);

    int H, W;
    cin >> H >> W;
    vector<string> grid(H);
    int start_r = -1, start_c = -1;
    for(int i=0;i<H;i++){
        cin >> grid[i];
        for(int j=0;j<W;j++) if(grid[i][j] == 'S'){
            start_r = i;
            start_c = j;
        }
    }

    // Directions: up, down, left, right
    vector<pair<int, int>> directions = { {-1,0}, {1,0}, {0,-1}, {0,1} };

    vector<vector<int>> component_id(H, vector<int>(W, 0));
    // BFS from S
    queue<pair<int, int>> q;
    q.push({start_r, start_c});
    component_id[start_r][start_c] = 1;
    int C_size = 1;
    while(!q.empty()){
        pair<int, int> current = q.front(); q.pop();
        int r = current.first, c = current.second;
        for(auto &[dr, dc] : directions){
            int nr = r + dr, nc = c + dc;
            if(nr >=0 && nr < H && nc >=0 && nc < W){
                if( (grid[nr][nc] == '.' || grid[nr][nc] == 'S') && component_id[nr][nc]==0 ){
                    component_id[nr][nc] = 1;
                    C_size++;
                    q.push({nr, nc});
                }
            }
        }
    }

    int current_id = 2;
    vector<int> component_size;
    component_size.push_back(0);
    component_size.push_back(C_size); // component_id=1
    for(int i=0;i<H;i++) {
        for(int j=0;j<W;j++) {
            if( (grid[i][j] == '.' || grid[i][j] == 'S') && component_id[i][j]==0 ){
                // Start BFS for new component
                queue<pair<int, int>> qq;
                qq.push({i, j});
                component_id[i][j] = current_id;
                int size = 1;
                while(!qq.empty()){
                    pair<int, int> curr = qq.front(); qq.pop();
                    int r = curr.first, c = curr.second;
                    for(auto &[dr, dc] : directions){
                        int nr = r + dr, nc = c + dc;
                        if(nr >=0 && nr < H && nc >=0 && nc < W){
                            if( (grid[nr][nc] == '.' || grid[nr][nc] == 'S') && component_id[nr][nc]==0 ){
                                component_id[nr][nc] = current_id;
                                size++;
                                qq.push({nr, nc});
                            }
                        }
                    }
                }
                component_size.push_back(size);
                current_id++;
            }
        }
    }

    int total_components = current_id;
    // Initialize last_seen array
    // To handle large component_ids, use a vector and resize accordingly
    vector<int> last_seen(total_components, 0);
    int wall_number = 0;
    int max_reachable = C_size;

    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            if(grid[i][j] == '#'){
                bool adjacent_to_C = false;
                // Check if this wall is adjacent to C
                for(auto &[dr, dc] : directions){
                    int ni = i + dr, nj = j + dc;
                    if(ni >=0 && ni < H && nj >=0 && nj < W){
                        if(component_id[ni][nj] == 1){
                            adjacent_to_C = true;
                            break;
                        }
                    }
                }
                if(adjacent_to_C){
                    wall_number++;
                    int sum_other = 0;
                    for(auto &[dr, dc] : directions){
                        int ni = i + dr, nj = j + dc;
                        if(ni >=0 && ni < H && nj >=0 && nj < W){
                            int cid = component_id[ni][nj];
                            if(cid > 1 && last_seen[cid] != wall_number){
                                sum_other += component_size[cid];
                                last_seen[cid] = wall_number;
                            }
                        }
                    }
                    // After adding, also add the wall cell itself
                    int total = C_size + 1 + sum_other;
                    if(total > max_reachable){
                        max_reachable = total;
                    }
                }
            }
        }
    }
    cout << max_reachable << '\n';
    return 0;
}

// AOJ #3639 Commutativity
// 2025.3.16

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int MOD = 998244353;

int N;
vector<int> f;
vector<vector<int>> inv;

vector<int> col;
vector<bool> cyc;
vector<int> cl;
vector<vector<int>> cycList;

vector<vector<int>> ch;

void dfsCycle(int v){
    vector<int> st;
    int cur = v;
    while(true){
        if(col[cur]==0){
            col[cur]=1;
            st.push_back(cur);
            cur = f[cur];
        } else if(col[cur]==1){
            int idx=-1;
            for (int i=0; i<st.size(); i++){
                if(st[i]==cur){ idx = i; break; }
            }
            int L = st.size()-idx;
            vector<int> cycV;
            for (int i=idx; i<st.size(); i++){
                int u = st[i];
                cyc[u]=true; cl[u] = L;
                cycV.push_back(u);
            }
            cycList.push_back(cycV);
            for (int u : st) col[u]=2;
            break;
        } else {
            for (int u : st) col[u]=2;
            break;
        }
    }
}

vector<vector<int>> dp;
vector<bool> dpDone;

void dfsDP(int v){
    for (int w : ch[v]) dfsDP(w);
    for (int x=1; x<=N; x++){
        ll sum = 0;
        for (int u : inv[x]){
            ll prod = 1;
            for (int w : ch[v]) prod = (prod * dp[w][u]) % MOD;
            sum = (sum + prod) % MOD;
        }
        dp[v][x] = (int)sum;
    }
    dpDone[v] = true;
}

int Fval(int v, int x){
    ll prod = 1;
    for (int w : ch[v]) prod = (prod * dp[w][x]) % MOD;
    return (int) prod;
}

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin >> N;
    f.resize(N+1);
    for (int i=1; i<=N; i++) cin >> f[i];

    inv.assign(N+1, vector<int>());
    for (int i=1; i<=N; i++) inv[f[i]].push_back(i);

    col.assign(N+1, 0);
    cyc.assign(N+1, false);
    cl.assign(N+1, 0);
    for (int i=1; i<=N; i++){
        if(col[i]==0) dfsCycle(i);
    }

    ch.assign(N+1, vector<int>());
    for (int i=1; i<=N; i++){
        if(!cyc[i]){
            int p = f[i];
            ch[p].push_back(i);
        }
    }

    dp.assign(N+1, vector<int>(N+1,0));
    dpDone.assign(N+1, false);
    for (int i=1; i<=N; i++){
        if(!cyc[i] && !dpDone[i]) dfsDP(i);
    }

    ll ans = 1;
    for (auto &cycV : cycList){
        int start = cycV[0];
        vector<int> dC;
        int cur = start;
        do {
            dC.push_back(cur);
            cur = f[cur];
        } while(cur != start);
        int L = dC.size();

        ll sumC = 0;
        for (int a = 1; a<=N; a++){
            if(!cyc[a]) continue;
            if(L % cl[a] != 0) continue;
            ll prod = 1;
            int t = a;
            for (int i=0; i<L; i++){
                prod = (prod * Fval(dC[i], t)) % MOD;
                t = f[t];
            }
            sumC = (sumC + prod) % MOD;
        }
        ans = (ans * sumC) % MOD;
    }
    cout << ans << endl;
    return 0;
}

