ll Cin() {
    ll n = 0; int c = gc();
    do n = 10*n + (c & 0xf), c = gc(); while (c >= '0');
    return n;
}

void Couts(const string &s) {
    for (char c : s) pc(c);
    pc('\n');
}

ll g(ll x) {
    while (x & 1) {
        if (x == 1) return 0;
        x = (x - 1) >> 1;
    }
    return x >> 1;
}

int main() {
    int T = Cin();
    while (T--) {
        ll n = Cin(), m = Cin();
        ll gn = g(n);
        ll gm = g(m);
        Couts((gn ^ gm)? "First": "Second");
    }
    return 0;
}

// AOJ #3647 Equal or Not Equal
// 2025.4.20

#include <bits/stdc++.h>
using namespace std;

#define gc() getchar_unlocked()
#define pc(c) putchar_unlocked(c)

int Cin() {
    int n = 0; int c = gc();
    do n = 10*n + (c & 0xf), c = gc(); while (c >= '0');
    return n;
}

void Couts(const string &s) {
    for (char c : s) pc(c);
    pc('\n');
}

int N, M, id;
vector<int> p, rk, cur;
vector<unordered_set<int>> nei;

int findp(int x) {
    return p[x]==x ? x : p[x]=findp(p[x]);
}

void merge_nei(int r, int s){
    if(nei[s].empty()) return;
    for(int v : nei[s]){
        nei[r].insert(v);
        nei[v].erase(s);
        nei[v].insert(r);
    }
    nei[s].clear();
}

void unite(int x, int y){
    x = findp(x);
    y = findp(y);
    if(x == y) return;
    if(rk[x] < rk[y]) swap(x,y);
    p[y] = x;
    if(rk[x] == rk[y]) rk[x]++;
    merge_nei(x, y);
}

int main(){
    N = Cin(), M = Cin();
    id = N;
    int SZ = N + M + 5;

    p.resize(SZ);
    rk.assign(SZ, 0);
    cur.resize(N+1);
    nei.assign(SZ, unordered_set<int>());

    for(int i = 1; i < SZ; i++) p[i] = i;
    for(int i = 1; i <= N; i++) cur[i] = i;

    for(int i = 0; i < M; i++){
        int t = Cin() & 0xf, gc();
        int x, y;
        if(t == 1){
            x = Cin(), y = Cin();
            unite(cur[x], cur[y]);
        } else if(t == 2){
            x = Cin(), y = Cin();
            int rx = findp(cur[x]), ry = findp(cur[y]);
            if(rx != ry){
                nei[rx].insert(ry);
                nei[ry].insert(rx);
            }
        } else if(t == 3){
            x = Cin();
            int old = cur[x];
            cur[x] = ++id;
            p[id]    = id;
            rk[id]   = 0;
            int rx = findp(old), ry = findp(id);
            if(rx != ry){
                nei[rx].insert(ry);
                nei[ry].insert(rx);
            }
        } else {
            x = Cin(), y = Cin();
            int rx = findp(cur[x]), ry = findp(cur[y]);
            if(rx == ry) Couts("Yes");
            else if(nei[rx].count(ry)) Couts("No");
            else Couts("Unknown");
        }
    }
    return 0;
}

