int main(){
  ios::sync_with_stdio(false),cin.tie(nullptr);
  int n,q;
  cin>>n>>q;

  vector<int>ans(n);
  vector<array<int,3>>a(n);
  vector<int>fa(n);
  iota(fa.begin(),fa.end(),0);
  auto find=[&](int x){
    while(fa[x]!=x){
      x=fa[x]=fa[fa[x]];
    }
    return x;
  };
  auto merge=[&](int x,int y){
    if(x<0||y==n)return ;
    x=find(x),y=find(y);
    if(a[x][0]!=a[y][0])return;
    if(x==y)return ;
    fa[y]=x;
    a[x][2]=a[y][2];
  };

  for(int i=0;i<n;i++)a[i][0]=a[i][1]=a[i][2]=i;

  int op,x,c;
  while(q--){
    cin>>op;
    if(op==1){
      cin>>x>>c;
      x--,c--;
      x=find(x);
      if(a[x][0]!=c){
        ans[c]+=a[x][2]-a[x][1]+1;
        ans[a[x][0]]-=a[x][2]-a[x][1]+1;
      }
      a[x][0]=c;
      merge(a[x][1]-1,x);
      merge(x,a[x][2]+1);
    }else {
      cin>>c;
      c--;
      cout<<ans[c]+1<<'\n';
    }
  }

  return 0;
};

