const int maxsiz=531441;
int n,m,l;
int pw3[13];
int a[13];
int dp[maxsiz][2];
int dfs(int msk,bool who){
    if(dp[msk][who])return dp[msk][who];
    int status[13];
    int old=msk;
    FOR(_,0,n+m+l-1){
        status[_]=msk%3;
        msk/=3;
    }

    msk=old;
    // status 0/1 是双方的牌
    FOR(i,0,n+m+l-1){
        if(status[i]==who){
            // case1：不拿走任何牌
            if(dfs(msk-status[i]*pw3[i]+2*pw3[i],who^1)==2){
                return dp[msk][who]=1;// current victory.
            }
            FOR(j,0,n+m+l-1){
                if(a[j]<a[i]&&status[j]==2){
                    if(dfs(msk-status[i]*pw3[i]+2*pw3[i]-2*pw3[j]+int(who)*pw3[j],who^1)==2){
                        return dp[msk][who]=1;
                    }
                }
            }
        }
    }
    return dp[msk][who]=2;
}
void solve(int id_of_test){
	read(n);
    read(m);
    read(l);
    FOR(i,0,n-1){
        read(a[i]);
    }
    FOR(i,0,m-1){
        read(a[n+i]);
    }
    FOR(i,0,l-1){
        read(a[n+m+i]);
    }
    int msk=0;
    FOR(i,0,m-1){
        msk+=pw3[n+i];
    }
    FOR(i,0,l-1){
        msk+=2*pw3[n+m+i];
    }
    if(dfs(msk,0)==1)puts("Takahashi");
    else puts("Aoki");
}
