void solve(){
	int n;
	cin>>n;
	vector<int> a(n);
	for(auto& i:a)cin>>i;
	int ans=0;
	for(int s=0;s<=1;++s){
		vector<bool> vis(n+1);
		for(int cnt=0,i=s;i+1<n;i+=2){
			if(a[i]==a[i+1]&&!vis[a[i]]){
				cnt+=2;
				vis[a[i]]=1;
			}
			else{
				while(cnt){
					if(a[i]==a[i+1]&&a[i-cnt]==a[i])break;
					vis[a[i-cnt]]=0;
					cnt-=2;
				}
			}
			ans=max(ans,cnt);
		}
	}
	cout<<ans<<endl;

	return;
}

