using namespace std;

void solve(){
	int h, w, d;
	cin >> h >> w >> d;
	char ch[h][w];
	for(int i = 0; i < h; i++){
		for(int j = 0; j < w; j++) cin >> ch[i][j];
	}
	int ans = 0;
	for(int i = 0; i < h; i++){
		for(int j = 0; j < w; j++){
			if(ch[i][j] == '#') continue;
			int grid[h][w] = {};
			int cnt1 = 0;
			for(int k = 0; k < h; k++){
				for(int r = 0; r < w; r++){
					if(ch[k][r] == '#') continue;
					if(abs(i - k) + abs(j - r) <= d){
						cnt1++;
						grid[k][r] = 1;
					}
				}
			}
			for(int x = 0; x < h; x++){
				for(int y = 0; y < w; y++){
					if(ch[x][y] == '#' || x == i && y == j) continue;
					int cnt2 = 0;
					for(int s = 0; s < h; s++){
						for(int t = 0; t < w; t++){
							if(ch[s][t] == '#' || grid[s][t] != 0) continue;
							if(abs(x - s) + abs(y - t) <= d) cnt2++;
						}
					}
					ans = max(ans, cnt1 + cnt2);
				}
			}
		}
	}
	cout << ans << endl;
}

