bool notP[10000100];
vector<long long> prim;

void sieve(){
    notP[0]=1;
    notP[1]=1;

    for(long long i=2;i<=1000000;i++){
        if(notP[i]) continue;
        for(long long j=i*i;j<=1000000;j+=i){
            notP[j]=1;;
        }
    }

    for(long long i=2;i<=1000000;i++){
        if(!notP[i]) prim.push_back(i);
    }
}
