            if(prim[i]*prim[i]*prim[i]*prim[i]*prim[i]*prim[i]*prim[i]*prim[i]<=n){
                //cout << prim[i] << '\n';
                ans++;
            }
        }
        if(prim[i]*prim[i]>n){
                break;
        }
        for(int j=i+1;j<prim.size();j++){
            if(prim[j]*prim[j]>n){
                break;
            }
            if(prim[j]*prim[j]*prim[i]>n){
                break;
            }
            if(prim[j]*prim[j]*prim[i]*prim[i]>n){
                break;
            }
          //  cout << prim[j] << ' ' << prim[i] << ' ' << prim[i]*prim[j]*prim[i]*prim[j] << '\n';
            ans++;
        }
