    cout << ans << '\n';
    return 0;
}

#include<bits/stdc++.h>

using namespace std;

typedef long long ll;
int const maxn = 2e5 + 5;
int type[maxn], par[maxn], sA[maxn], sB[maxn];

int get(int v) {
    if (par[v] == v) return v;
    return par[v] = get(par[v]);
}

main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int n, m, k;
    cin >> n >> m >> k;
    vector < array < int, 3 > > edge;
    for (int i = 1; i <= m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        edge.push_back({w, u, v});
    }
    for (int i = 1; i <= k; i++) {
        int v;
        cin >> v;
        sA[v]++;
    }
    for (int i = 1; i <= k; i++) {
        int v;
        cin >> v;
        sB[v]++;
    }
    for (int i = 1; i <= n; i++) par[i] = i;
    sort(edge.begin(), edge.end());
    ll ans = 0;
    for (auto [w, u, v] : edge) {
        u = get(u), v = get(v);
        if (u == v) continue;
        int x = min(sA[u], sB[v]), y = min(sA[v], sB[u]);
        ans += (ll)(x + y) * w;
        par[u] = v;
        sA[v] += sA[u] - (x + y);
        sB[v] += sB[u] - (x + y);
    }
    cout << ans << '\n';
    return 0;
}

#include <iostream>
#include <vector>
#include <utility>

using namespace std;
using ll = long long;
using Data = pair<ll, ll>;

int main(void) {
    int N, X, K;
    cin >> N >> X >> K;

    // c別のP,Uを管理する
    vector<vector<Data>> g(N+1);
    for (int i = 0; i < N; i++) {
        ll p, u, c;
        cin >> p >> u >> c;
        c--;
        g[c].emplace_back(p, u);
    }

    const ll INF = -2e18;
    vector<ll> dp(X + 1,INF);
    dp[0] = 0;
    for (int i = 0; i < N; i++) {
        vector<ll> next = dp;
        for (int pi = 0; pi < g[i].size(); pi++) {
            auto [p, u] = g[i][pi];
            for (int x = X; x >= p; x--) {
                if (dp[x - p] != INF) {
                    next[x] = max(next[x], dp[x-p] + u + K);
                }

                if (next[x - p] != INF) {
                    next[x] = max(next[x], next[x-p] + u);
                }
            }
        }
        swap(dp, next);
    }

    ll ans = 0;
    for (int x = 0; x <= X; x++) {
        ans = max(ans, dp[x]);
    }
    cout << ans << endl;
    return 0;
}

