using namespace std;

int main(){
    cin.tie(nullptr);
    ios_base::sync_with_stdio(false);
    ll n,s;
    cin >> n >> s;
    ll Asum = 0;
    vector<ll> A(2*n);
    rep(i,0,n){
        cin >> A[i];
        Asum += A[i];
        A[n + i] = A[i];
    }
    s %= Asum;
    int right = 0;
    ll sum = 0;
    for(int left = 0; left < n; left++){
        while(right < 2*n and sum + A[right] <= s){
            sum += A[right];
            right++;
        }
        if(sum == s){
            cout << "Yes" << endl;
            return 0;
        }
        if(left == right){
            right++;
        }
        else{
            sum -= A[left];
        }
    }
    cout << "No" << endl;
}

