template<class T> 
inline bool chmin(T &a,const T &b){
	if(a>b){
		a=b;
		return true;
	}
	return false;
}
template<class T> 
inline bool chmax(T &a,const T &b){
	if(a<b){
		a=b;
		return true;
	}
	return false;
}
template<typename T>
T modpow(T a,T b,T m){
	T r=1;
	a%=m;
	while(b>0){
		if(b&1) r=(r*a)%m;
		a=(a*a)%m;
		b>>=1;
	}
	return r;
}
template<typename T>
T ipow(T a,long long b){
    T res=1;
    while(b>0){
        if (b & 1) res*=a;  
        a*=a;              
        b>>=1;             
    }
    return res;
}


