typedef long long ll;
typedef vector<ll> vll;
typedef vector<int> vi;
typedef pair<int,int> ii;

const int K=25;

int cnt[1<<K];
ll sum[1<<K];

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);

    int n;
    cin>>n;
    vi a(n);
    forn(i,n) cin>>a[i];
    vll tot(K,0LL);
    forn(k,K){
        forn(i,n){
            int curr=a[i]%(1<<k);
            cnt[curr]++;
            sum[curr]+=a[i];
            int need=(1<<k)-curr;
            if(need==(1<<k)) need=0;
            tot[k]+=1LL*cnt[need]*a[i]+sum[need];
        }
        forn(i,n){
            int curr=a[i]%(1<<k);
            cnt[curr]--,sum[curr]-=a[i];
        }
    }
    forn(k,K-1) tot[k]-=tot[k+1];
    ll res=0;
    forn(k,K){
        res+=tot[k]>>k;
    }
    cout<<res<<'\n';

    return 0;
}

