const ll MAXN=100+5;
ll n,m,x,y;
char s[MAXN][MAXN];
bool vs[MAXN][MAXN];
int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);cout.tie(0);
	cin>>n>>m>>x>>y;
	rep(i,1,n){
	    rep(j,1,m){
	        cin>>s[i][j];
	    }
	}
	string T;
	cin>>T;
	ll c=0;
	for(auto a:T){
	    ll X=x,Y=y;
	    if(a=='L'){
	        y--;
	    }else if(a=='R'){
	        y++;
	    }else if(a=='U'){
	        x--;
	    }else{
	        x++;
	    }
	    if(s[x][y]=='#'){
	        x=X,y=Y;
	        continue;
	    }
	    if(s[x][y]=='@'){
	        c+=(!vs[x][y]);
	        vs[x][y]=true;
	    }
	}
	cout<<x<<" "<<y<<" "<<c<<endl;
	return 0;
}

// 贪心算法
// 大概思路是这样的：考虑到雪花树的树深度仅仅为2
// 那么对于每个节点来说，其所有的儿子可以保留任意个
