#define mem(a, b) memset(a, b, sizeof a)
#define mp make_pair
#define pb emplace_back

using namespace std;

const double eps = 1e-8;
const int N = 300005, M = 600005, INF = 0x3f3f3f3f;
const int Mod = 998244353;

int n;
int head[N], ver[M], nxt[M], idx, d[N];
int ans = INF;

inline void add(int a, int b) {
    ver[idx] = b, nxt[idx] = head[a], head[a] = idx++;
}

struct Node {
    int deg, id;
};

inline bool cmp(int a, int b) {
    return a > b;
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    cin >> n;
    mem(head, -1);
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        add(u, v), add(v, u);
        d[u]++, d[v]++;
    }
    //for (int i = 1; i <= n; i++) cout << i << " " << d[i] << '\n';

    for (int i = 1; i <= n; i++) {
        //cout << "NOW:" << i << '\n';
        vector <int> tmp;
        for (int j = head[i]; ~j; j = nxt[j]) tmp.pb(d[ver[j]]);
        sort(tmp.begin(), tmp.end(), cmp);
        int nx = 0;
        for (int p = 0; p < tmp.size(); p++) {
            if (tmp[p] == 1) break;
            nx++;
            ans = min(ans, n - 1 - nx - nx * (tmp[p] - 1));
            //cout << n - 1 - nx - nx * (tmp[p] - 1) << '\n';
        }
    }

    cout << ans << '\n';
    return 0;
}

#include<bits/stdc++.h>
#define int long long
using namespace std;

void solve(){
    int n; cin >> n;
    vector<pair<int, int>> p(n);
    for(int i = 0; i < n; i++){
    	cin >> p[i].first >> p[i].second;
    }

    double h = -1;
    for(int i = 1; i < n; i++){
    	auto [a, b] = p[i - 1];
    	auto [c, d] = p[i];

    	h = max(h, 1. * (a * d - b * c) / (a - c));
    }

    if(h < 0){
    	cout << -1 << '\n';
    }
    else{
    	cout << fixed << setprecision(10);
    	cout << h << '\n';
    }
}

signed main(){
    ios::sync_with_stdio(0);
    cin.tie(0);
    solve();
    return 0;
}

