int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S;
    cin >> S;

    int ans = 0;
    bool pre_zero = false;

    for (auto c : S)
    {
        ans += 1;

        if (c != '0')
        {
            pre_zero = false;
        } else {
            ans -= pre_zero;
            pre_zero = !pre_zero;
        }
    }

    cout << ans << endl;

    return 0;
}

