template<typename T1, typename T2> inline bool chmax(T1 &a, T2 b) {
    bool compare = a < b;
    if(compare) a = b;
    return compare;
}
template<typename T1, typename T2> inline bool chmin(T1 &a, T2 b) {
    bool compare = a > b;
    if(compare) a = b;
    return compare;
}

int dx[4] = {-1,0,1,0};
int dy[4] = {0,1,0,-1};
int N,K;
ll base = 0;
ll ans = 0;
vector<ll> A(200005);

void check_xor_value(int last, int rem, ll val){
    if(rem == 0){
        ans = max(ans,val);
        return;
    }
    REP(i,last+1,N-rem){
        check_xor_value(i,rem-1,val^A[i]);
    }
}
int main(void){
    cin >> N >> K;
    rep(i,0,N) cin >> A[i];
    if(K*2 > N){
        rep(i,0,N) base ^= A[i];
        K = N-K;
    }
    check_xor_value(-1,K,base);
    cout << ans << endl;
}

