//#define LOCAL
void yes(){cout << "Yes\n";}
void no(){cout << "No\n";}
const int dx[4]={0,-1,0,1};
const int dy[4]={-1,0,1,0};
//const int dx[2]={0,1};
//const int dy[2]={1,0};

int main(){
  ll K;
  cin >> K;
  string S,T;
  cin >> S >> T;
  ll sl=S.length();
  ll tl=T.length();
  if(abs(tl-sl)>K){
    no();
    return 0;
  }
  vector<ll> dp(2*K+2,INFL);
  for(int i=0;i<=min(K,tl);i++){
    dp[K+i]=i;
  }
  for(int i=1;i<=sl;i++){
    vector<ll> nw(2*K+2,INFL);
    ll pre=INFL;
    for(int j=-K;j<=K;j++){
      if(i+j<0 || i+j>tl) continue;
      if(i+j==0){
        nw[K+j]=i;
        pre=i;
        continue;
      }
      ll add=1;
      if(S[i-1]==T[i+j-1])add=0;
      nw[K+j]=min({pre+1,dp[K+j]+add,dp[K+j+1]+1});
      pre=nw[K+j];
    }
    swap(dp,nw);
  }
  bool fl=false;
  if(dp[K+(tl-sl)]<=K) fl=true;
  if(fl) yes();
  else no();
}

