ll pw(ll n, int k) {
    assert(k >= 0);
    ll res = 1;
    while (k) {
        if (k & 1)
            res *= n;
        n *= n;
        k >>= 1;
    }
    return res;
}

ll f(ll x) {
    // x 未満
    if (x <= 10)
        return 0;
    auto s = std::to_string(x);
    ll res = 0;
    {
        // s より短いやつ
        for (int len = 2; len < s.size(); len++) {
            for (int x = 1; x <= 9; x++) {
                res += pw(x, len - 1);
            }
        }
    }
    debug(res);
    {
        // s と長さが同じで s より top が小さい
        for (int x = 1; x < s[0] - '0'; x++)
            res += pw(x, s.size() - 1);
    }
    debug(res);
    {
        // s に似てるやつ
        for (int i = 1; i < s.size(); i++) {
            if (s[0] > s[i]) {
                // [0, s[i]) を使う
                res += (s[i] - '0') * pw(s[0] - '0', s.size() - i - 1);

                // s[i] を使うパターンは後で
            } else {
                // [0, s[0]) を使う
                res += pw(s[0] - '0', s.size() - i);
                break;
            }
        }
    }
    return res;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    std::signal(SIGABRT, signal_hander);

    LL(l, r);
    fin(f(r + 1) - f(l));
}
