void solve() {
    auto good = [&](int x) -> bool {
        int sum = 0;
        string str = to_string(x);
        rep(i, si(str)) sum += (str[i] - '0');
        return x % sum == 0;
    };

    STR(s);
    int sz = si(s);

    if(sz <= 5) {
        int n = stoi(s);
        for(int a = n; a + 1 <= 2 * n; ++ a) {
            if(good(a) and good(a + 1)) {
                out(a);
                return;
            }
        } 
        out(-1);
    } else {
        int val = s[0] - '0';
        int val2 = s[1] - '0';
        if(val == 1 and val2 == 0) {
            string ans(sz, '0');
            ans[0] = '1';
            ans[1] = '1';
            out(ans);
        } else if(val <= 7) {  
            string ans(sz, '0');
            int nxt = val + 1;
            ans[0] = (char)('0' + nxt);
            ans[1] = (char)('0' + ((nxt <= 2 ? 2 : 8) - nxt));
            out(ans);
        } else {
            string ans(sz + 1, '0');
            ans[0] = '1';
            ans[sz - 1] = '1';
            out(ans);
        }
    }
}

signed main() {
    int testcase = 1;
    // in(testcase);
    while(testcase--) solve();
    return 0;
}

