void init() {
    int at = 1;
    for(int i = 1; i <= n; i++) {
        while(at <= n and a[i] > a[at] / 2) at += 1;
        nxt[i] = at;
    }
}

int main() {
    cin.tie(0) -> sync_with_stdio(false);
    cin >> n;
    for(int i = 1; i <= n; i++) cin >> a[i];
    init();
    long long res = 0;
    for(int i = 1; i <= n; i++) {
        if(nxt[i] == n + 1) continue;
        res += n - nxt[i] + 1;
    }
    cout << res << endl;
    return 0;
}

