const int N = 500000 + 5;

int n;
int a[N];
int ac[N];

int main() {
    cin.tie(0) -> sync_with_stdio(false);
    cin >> n;
    for(int i = 1; i <= n; i++) cin >> a[i];
    for(int i = 1; i <= n; i++) {
        ac[i] += ac[i - 1];
        a[i] += ac[i];
        int l = i + 1;
        int r = min(i + a[i], n);
        ac[l] += 1;
        ac[r + 1] -= 1;
        a[i] -= r - l + 1;
        cout << a[i] << " \n"[i == n];
    }
    return 0;
}

