#include <bits/stdc++.h>
using namespace std;

static const int MAXN = 200000;
static const int LOG  = 18;

int N, Q;
long long A[MAXN+5];
int p[MAXN+5], d[MAXN+5];
int st[LOG+1][MAXN+5];
int lg2[MAXN+5];

inline int rmq(int l, int r) {
    // return max_{i=l..r} d[i], or 0 if empty
    if (l > r) return 0;
    int len = r - l + 1;
    int k = lg2[len];
    return max(st[k][l], st[k][r - (1<<k) + 1]);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // 1) read input
    cin >> N;
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }
    cin >> Q;
    vector<pair<int,int>> qs(Q);
    for (int i = 0; i < Q; i++) {
        cin >> qs[i].first >> qs[i].second;
        // we'll convert to 0-based later
    }

    // 2) two‐pointer to compute p[i]
    //    p[i] = smallest j>i with A[j] >= 2*A[i], or N if none
    int j = 0;
    for (int i = 0; i < N; i++) {
        j = max(j, i+1);
        while (j < N && A[j] < 2LL * A[i]) 
            j++;
        p[i] = (j < N ? j : N);
    }

    // 3) build the d-array
    //    d[i] = p[i] - i  (>=1), or large if p[i]=N
    for (int i = 0; i < N; i++) {
        if (p[i] == N) 
            d[i] = N+1; 
        else 
            d[i] = p[i] - i;
    }

    // 4) build log‐table for RMQ
    lg2[1] = 0;
    for (int i = 2; i <= N; i++) 
        lg2[i] = lg2[i>>1] + 1;

    // 5) build sparse table on d[]
    for (int i = 0; i < N; i++)
        st[0][i] = d[i];
    for (int k = 1; k <= LOG; k++) {
        int len = 1 << k;
        for (int i = 0; i + len - 1 < N; i++) {
            st[k][i] = max(st[k-1][i], st[k-1][i + (1<<(k-1))]);
        }
    }

    // 6) answer queries
    //    For each [L,R], let m = R-L+1.
    //    Binary‐search minimal D in [ceil(m/2)..m] with
    //       max_{i=L..R-D} d[i] <= D
    //    Then K = m - D.
    for (auto &qr : qs) {
        int L = qr.first - 1;
        int R = qr.second - 1;
        int m = R - L + 1;

        int lo = (m + 1) / 2;  // ceil(m/2)
        int hi = m;
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            int right = R - mid;
            // check if sub‐range [L..right] is safe
            if (rmq(L, right) <= mid) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        int D = lo;
        int K = m - D;
        cout << K << "\n";
    }

    return 0;
}

