#include <bits/stdc++.h>

using namespace std;
using i128 = __int128_t;

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m;
    cin >> n >> m;

    vector<long long> P(n);
    for (int i = 0; i < n; i++)
    {
        cin >> P[i];
    }

    auto check = [&](long long mid) -> pair<i128, i128>
    {
        i128 cost = 0, cnt = 0;
        for (int i = 0; i < n; i++)
        {
            if (mid < P[i])
            {
                continue;
            }

            long long upper = mid / P[i];
            long long k = (upper + 1) / 2;

            cnt += k;
            cost += i128(P[i]) * k * k;

            if (cost > m)
            {
                break;
            }
        }

        return {cost, cnt};
    };

    long long l = 0, r = m + 1;
    while (r - l > 1)
    {
        long long mid = l + (r - l) / 2;
        (check(mid).first <= m ? l : r) = mid;
    }
    {
        auto [cost, cnt] = check(l);
        long long ans = cnt + (m - cost) / r;
        cout << fixed << setprecision(15);
        cout << ans << endl;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 5e5+100 ;
int n , q , f[N] , tr[N] ;

int lowbit(int x){
    return x & -x ;
}

void add(int x , int k){
    if(x == 0)x = 1;
    while(x <= N){
        tr[x] += k ;
        x = x + lowbit(x) ;
    }
}

int query(int x){
    int ans = 0 ;
    while(x){
        ans += tr[x] ;
        x -= lowbit(x) ;
    }
    return ans ;
}

int find(int x){
    int l = 0 , r = N , ans = 0 ;
    while(l <= r){
        int mid = (l+r) >> 1 ;
        if(f[mid]+query(mid) >= x){    
            ans = mid ;
            r = mid-1 ;
        }else{
            l = mid+1 ;
        }
    }
    return ans ;
}

