const ll INF = (ll)2e18;
vector<ll> seen;
ll N;
vector<ll> A;

void f(ll pos,vector<ll>&v){
    if(pos==N){
        ll ret = 0;
        rep(i,v.size()){
            ret ^= v[i];
        }
        seen.push_back(ret);
        return;
    }
    rep(i,v.size()){
        v[i] += A[pos];
        f(pos + 1, v);
        v[i] -= A[pos];
    }
    v.push_back(A[pos]);
    f(pos + 1, v);
    v.pop_back();
}

