void solve(){
    int n, q;
    std::cin >> n >> q;

    std::vector<int> siz(n + 1), idx(n + 1);
    for (int i = 1; i <= n; i ++) siz[i] = 1, idx[i] = i;

    int cnt = 0;
    for (int _ = 1; _ <= q; _ ++){
        int op, x, h;
        std::cin >> op;

        if (op == 1){
            std::cin >> x >> h;


            if (siz[idx[x]] == 2) cnt --;
            siz[idx[x]] --;

            if (siz[h] == 1) cnt ++;
            idx[x] = h, siz[h] ++;

        }else {
            std::cout << cnt << '\n';
        }
    }
}

