constexpr int P = 998244353;
using Z = MInt<P>;

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int N, M;
    std::cin >> N >> M;

    std::string S;
    std::cin >> S;

    auto get = [&](int mask, int go) {
        std::vector<int> pre(N + 1);
        for (int i = 0; i < N; i++) {
            pre[i + 1] = pre[i] + (mask >> i & 1);
        }
        std::vector<int> f(N + 1);
        for (int i = 0; i < N; i++) {
            if (S[i] == go + 'a') {
                f[i + 1] = pre[i] + 1;
            } else {
                f[i + 1] = std::max(f[i], pre[i + 1]);
            }
        }
        int ans = 0;
        for (int i = 0; i < N; i++) {
            ans += (f[i + 1] - f[i]) << i;
        }
        return ans;
    };

    std::vector f(1 << N, std::vector<int>(26));

    for (int i = 0; i < 1 << N; i++) {
        for (int j = 0; j < 26; j++) {
            f[i][j] = get(i, j);
        }
    }

    std::vector<Z> dp(1 << N);
    dp[0] = 1;
    for (int t = 0; t < M; t++) {
        std::vector<Z> g(1 << N);
        for (int i = 0; i < 1 << N; i++) {
            if (dp[i] == 0) {
                continue;
            }
            for (int j = 0; j < 26; j++) {
                g[f[i][j]] += dp[i];
            }
        }
        dp = g;
    }

    std::vector<Z> ans(N + 1);
    for (int i = 0; i < 1 << N; i++) {
        ans[__builtin_popcount(i)] += dp[i];
    }

    for (int i = 0; i <= N; i++) {
        std::cout << ans[i] << " \n"[i == N];
    }

    return 0;
}

