struct DSU
{
    std::vector<int> f, siz;
    DSU() {}
    DSU(int n)
    {
        init(n);
    }
    void init(int n)
    {
        f.resize(n);
        std::iota(f.begin(), f.end(), 0);
        siz.assign(n, 1);
    }
    int find(int x)
    {
        while (x != f[x])
        {
            x = f[x] = f[f[x]];
        }
        return x;
    }
    bool same(int x, int y)
    {
        return find(x) == find(y);
    }
    bool merge(int x, int y)
    {
        x = find(x);
        y = find(y);
        if (x == y)
        {
            return false;
        }
        siz[x] += siz[y];
        f[y] = x;
        return true;
    }
    int size(int x)
    {
        return siz[find(x)];
    }
};
void solve()
{
    int n, m;
    cin >> n >> m;
    vector<int> a(m), b(m);
    for (int i = 0; i < m; i++)
    {
        cin >> a[i] >> b[i];
        a[i]--, b[i]--;
    }
    vector<int> vis(m);
    DSU dsu(n);
    int ans = n - 1;
    for (int i = 0; i < m; i++)
    {
        if (!dsu.same(a[i], b[i]))
        {
            dsu.merge(a[i], b[i]);
            ans--;
            vis[i] = true;
        }
    }
    cout << ans << '\n';
    for (int i = 0, j = 0; i < m and ans > 0; i++)
    {
        if (vis[i])
            continue;
        while (dsu.same(j, a[i]))
            j++;
        cout << i + 1 << " " << b[i] + 1 << " " << j + 1 << '\n';
        dsu.merge(a[i], j);
        ans--;
    }
}

