template <typename T>
struct Fenwick {
    int n;
    std::vector<T> a;

    Fenwick(int n_ = 0) {
        init(n_);
    }

    void init(int n_) {
        n = n_;
        a.assign(n, T{});
    }

    void add(int x, const T &v) {
        for (int i = x + 1; i <= n; i += i & -i) {
            a[i - 1] = a[i - 1] + v;
        }
    }

    T sum(int x) {
        T ans{};
        for (int i = x; i > 0; i -= i & -i) {
            ans = ans + a[i - 1];
        }
        return ans;
    }

    T rangeSum(int l, int r) {
        return sum(r) - sum(l);
    }

    int select(const T &k) {
        int x = 0;
        T cur{};
        for (int i = 1 << std::__lg(n); i; i /= 2) {
            if (x + i <= n && cur + a[x + i - 1] <= k) {
                x += i;
                cur = cur + a[x - 1];
            }
        }
        return x;
    }
};


void solve(){
    int n;
    std::cin>>n;
    Fenwick<int> fen(n);
    for(int i=0;i<n;i++){
        fen.add(i,1);
    }
    std::vector<int> a(n);
    for(int i=0;i<n;i++){
        std::cin>>a[i];
        a[i]--;
    }
    std::vector<int> b(n);
    for(int i=n-1;i>=0;i--){
        int x=fen.select(a[i]);
        b[x]=i;
        fen.add(x,-1);
    }
    for(int i=0;i<n;i++){
        std::cout<<b[i]+1<<' ';
    }
    std::cout<<'\n';
}

