#include <bits/stdc++.h>
#define _(x, y) (x - 1) * m + y  
#define PII pair<int, int>
#define _1 first
#define _2 second 
using namespace std;
const int z = 507, Z = z * z, inf = 0x3f3f3f3f;
int n, m, N, vis[Z], dist[7], 
	L[Z], R[Z], nxt[Z], val[Z], 
	idx, id[Z], di[Z], st[Z][40], lg2[Z];
priority_queue<PII> pq;
int find_L(int x) {return x == L[x] ? x : L[x] = find_L(L[x]);}
int find_R(int x) {return x == R[x] ? x : R[x] = find_R(R[x]);}
void merge(int x, int y, int v) {
	int Lx = find_L(x), Rx = find_R(x), Ly = find_L(y), Ry = find_R(y);
	if(Lx == Ly || Rx == Ry) return;
	L[Ly] = Lx, R[Rx] = Ry; nxt[Rx] = Ly, val[Rx] = v;
}
int get_mn(int x, int y) {
	if(x > y) return inf;
	int ln = lg2[y - x + 1];
	return min(st[x][ln], st[y - (1 << ln) + 1][ln]);
}
int main() {
	ios::sync_with_stdio(false); cin.tie(0), cout.tie(0);
	int q, x, y, a, b, ia, ib, mn, ans;
	cin >> n >> m; N = n * m;
	lg2[1] = 0; lg2[2] = 1;
	for(int i = 3; i <= N; ++i) lg2[i] = lg2[i / 2] + 1;
	dist[0] = -1; dist[1] = 1; dist[2] = m; dist[3] = -m;
	for(int i = 1; i <= n; ++i)
	for(int j = 1; j <= m; ++j) x = _(i, j), cin >> y, pq.push({y, x}), L[x] = x, R[x] = x;
	while(!pq.empty()) {
		int w = pq.top()._1, u = pq.top()._2; pq.pop();
		vis[u] = 1;
		for(int i = 0; i < 4; ++i) {
			int v = u + dist[i];
			if(v < 0 || N < v || !vis[v] || (i == 0 && u % m == 1) || (i == 1 && u % m == 0)) continue;
			merge(u, v, w);
		}
	}
	for(int x = find_L(1); x; x = nxt[x]) id[x] = ++idx, di[idx] = x, st[idx][0] = val[x]; 
	for(int j = 1, j2 = 2; j2 < N; ++j, j2 <<= 1) 
	for(int i = 1; i <= N - j2; ++i) st[i][j] = min(st[i][j - 1], st[i + (j2 >> 1)][j - 1]); 
	cin >> q;
	while(q--) {
		ans = 0;
		cin >> ia >> ib >> a; x = id[_(ia, ib)]; 
		cin >> ia >> ib >> b; y = id[_(ia, ib)];
		if(x > y) swap(x, y); mn = get_mn(x, y - 1);
		if(a > mn) ans += a - mn, a = mn;
		cout << ans + abs(a - b) << "\n";
	}
	return 0;
}

