void solve(){
	int n, m;
	cin >> n >> m;
	vector<vector<array<ll, 2>>> adj(n);
	rep(i, 0, m){
		int u, v;
		ll w;
		cin >> u >> v >> w;
		u--, v--;
		adj[u].pb({v, w});
		adj[v].pb({u, w});
	}
	vll f(n, inf), vis(n);
	f[0] = 0;
	auto dfs = [&](auto&& self, int s,ll v)->void{

		if(s == n - 1){
			return;
		}
		vis[s] = 1;
		for(auto [x, w] : adj[s]){
			if(vis[x]) continue;
			// cout << s << " " << x << "\n";
			f[x] = min(f[x], v ^ w);
			self(self, x, v ^ w);
		}
		vis[s] = 0;
	};
	dfs(dfs, 0, 0);
	cout << f[n - 1] ;

}




