void tran(ll &x,ll &y){
    tie(x,y)=mkp(x+y,x-y);
}
void fwt(ll a[]){
    for(int o=1;o<(1<<m);o<<=1)
        for(int i=0;i<(1<<m);i+=o<<1)
            for(int j=0;j<o;j++)
                tran(a[i+j],a[i+j+o]);
}
void ifwt(ll a[]){
    for(int o=1;o<(1<<m);o<<=1)
        for(int i=0;i<(1<<m);i+=o<<1)
            for(int j=0;j<o;j++)
                tran(a[i+j],a[i+j+o]);
	for(int i=0;i<(1<<m);i++)a[i]>>=m;
}
