        for(char c:s)x=x<<1|(c&1);
        cnt[x]++;
    }
    for(int i=0;i<(1<<m);i++)
        f[i]=min(ppc(i),m-ppc(i));

    fwt(f),fwt(cnt);
    for(int i=0;i<(1<<m);i++)ans[i]=f[i]*cnt[i];
    ifwt(ans);
    cout<<*min_element(ans,ans+(1<<m));
}

