int main(){
  int n; cin >> n;
  vector<int> d(n),l(n),r(n);
  int cnt = 0,ans = 0;

  rep(i,n) cin >> d[i], d[i]--;
  rep(i,n){
    r[d[i]]++;
    if ( r[d[i]] == 1) cnt++;
  }

  rep(i,n){
    int t = d[i];
    if (l[t] ==0) cnt++;
    if (r[t] ==1) cnt--;
    l[t]++;r[t]--;
    ans = max(ans,cnt);
  }

  cout << ans << endl;
  return 0;
}

