using namespace std;
const int MAXN=200000+5;
vector<int>a[MAXN];
int son[MAXN],n,k;
vector<int>b[MAXN];

void dfs(int x,int fa)
{
	son[x]=1;
	for(int i=0;i<a[x].size();i++)
	{
		if(a[x][i]==fa) continue;
		dfs(a[x][i],x);
		son[x]+=son[a[x][i]];
		b[x].push_back(son[a[x][i]]);
	}
	int flag=0;
	for(int i=0;i<b[x].size();i++)
	{
    // 计算有贡献的儿子的个数
		if(b[x][i]>0)
		{
			flag++;
		}
	}
	if(son[x]==k) 
	{
		if(flag>2) 
		{
			cout<<"No\n";
			exit(0);
		}
		son[x]=0;
		return ;
	}
	if(flag<=1) return ;
	cout<<"No\n";
	exit(0);
}

