	for(int i=1;i<n*k;i++)
	{
		cin>>x>>y;
		a[x].push_back(y);
		a[y].push_back(x);	
	}
	dfs(1,-1);
	if(son[1]!=0) cout<<"No\n";
	else cout<<"Yes\n";
	return 0;
}

