    for(int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
        counter[a[i]]++;
    }
    int ans = -1, mx = 0;
    for(int i = 1; i <= n; i++) {
        if(mx < a[i] && counter[a[i]] == 1) {
            ans = i;
            mx = a[i];
        }
    }
    printf("%d\n", ans);
    return 0;
}

