#include <bits/stdc++.h>

using i64 = long long;
using u64 = unsigned long long;
using u32 = unsigned;
using u128 = unsigned __int128;

std::vector<int> minp, primes, np, lst;

void sieve(int n) {
    minp.assign(n + 1, 0);
    primes.clear();
    np.assign(n + 1, 0);

    for (int i = 2; i <= n; i++) {
        if (minp[i] == 0) {
            minp[i] = i;
            np[i] = 1;
            primes.push_back(i);
        }

        for (auto p : primes) {
            if (i * p > n) {
                break;
            }
            minp[i * p] = p;
            if (p == minp[i]) {
                np[i * p] = np[i];
                break;
            }
            np[i * p] = np[i] + 1;
        }
    }

    lst.resize(n + 1);
    for (int i = 1; i <= n; i++) {
        lst[i] = np[i] == 2 ? i : lst[i - 1];
    }
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    sieve(1E6);

    int Q;
    std::cin >> Q;

    for (int i = 0; i < Q; i++) {
        i64 A;
        std::cin >> A;

        A = std::sqrt(A);
        A = lst[A];
        A *= A;
        std::cout << A << "\n";
    }

    return 0;
}

