#define ff first
#define ss second

const int N = (5e5 + 5);

string s;

int ans, a[N], b[N], k, v[N][26];

char c[N];

void f(int x, int y) {
    ans -= a[x];
    for(int i = 0; i < 26; i++) {
        if(v[x][i] and !b[v[x][i]]) f(v[x][i], x);
    }
}

void dfs(int x, int y, int ind, int t) {
    if(t == 1) {
        if(ind == SZ(s)) {
            f(x, y);
            b[x] = true;
            return;
        }
        if(v[x][s[ind]-'a']) {
            if(b[v[x][s[ind]-'a']]) return;
            dfs(v[x][s[ind]-'a'], x, ind+1, t);
            return;
        }
        v[x][s[ind]-'a'] = (++k);
        c[k] = s[ind];
        dfs(k, x, ind+1, t);
        return;
    }
    if(ind == SZ(s)) {
        a[x]++;
        ans++;
        return;
    }
    if(v[x][s[ind]-'a'] and b[v[x][s[ind]-'a']]) return;
    if(v[x][s[ind]-'a']) {
        dfs(v[x][s[ind]-'a'], x, ind+1, t);
        return;
    }
    if(!v[x][s[ind]-'a']) {
        v[x][s[ind]-'a'] = (++k);
        c[k] = s[ind];
        dfs(k, x, ind+1, t);
    }
    return;
}

