#include <bits/stdc++.h>

using namespace std;
using ll = long long;

const int kMaxN = 2.5e5 + 1, mod = 998244353;

int n, k, K, o[3];
string s;
ll c[kMaxN], y[kMaxN], Y[kMaxN], ans, u, t;

inline ll C(int n, int m) { return c[n] * Y[n - m] % mod * Y[m] % mod; }

int main() {
  ios::sync_with_stdio(0), cin.tie(0);
  cin >> n >> k >> s, c[0] = Y[0] = y[1] = 1;
  for (int i = 1; i <= n; i++) {
    c[i] = c[i - 1] * i % mod, i > 1 && (y[i] = mod - mod / i * y[mod % i] % mod), Y[i] = Y[i - 1] * y[i] % mod, o[s[i - 1] - 'A']++;
  }
  for (int i = 0; i <= min({k, o[0], n / 2}); i++) {
    K = k - i;
    for (int j = 0; j <= min(i, o[1]); j++) {
      if (i - j <= o[2]) {
        u = 0;
        for (int l = 0; l <= min({K, j, o[2] - (i - j)}); l++) {
          t = 0;
          for (int p = 0; p <= min({K - l, o[1] - j, o[2] - (i - j) - l}); p++) {
            t = (t + C(o[1] - j, p) * C(o[2] - (i - j), p + l)) % mod;
          }
          u = (u + t * C(i, j - l)) % mod;
        }
        for (int l = 1; l <= min({K, i - j, o[1] - j}); l++) {
          t = 0;
          for (int p = 0; p <= min({K - l, o[1] - j - l, o[2] - (i - j)}); p++) {
            t = (t + C(o[1] - j, l + p) * C(o[2] - (i - j), p)) % mod;
          }
          u = (u + t * C(i, j + l)) % mod;
        }
        ans = (ans + u * C(o[1], j) % mod * C(o[2], i - j) % mod * C(o[0], i)) % mod;
      }
    }
  }
  cout << ans;
  return 0;
}

