void answer_to_the_question(){
    int n;      string s,t;         cin>>n>>s>>t;

    for(int i=0;i<n;i++){
        if(t[i]=='A')  break;

        if(s[i]=='A' && t[i]=='B'){
            cout<<-1<<nl;
            return;
        }
    }

    for(int i=n-1;i>=0;i--){
        if(t[i]=='B')  break;

        if(s[i]=='B' && t[i]=='A'){
            cout<<-1<<nl;
            return;
        }
    }

    int ans=0,op=0;
    for(int i=0;i<n;i++){
        if(s[i]=='B' && t[i]=='A'){
            op++;
        }

        if(s[i]=='A' && t[i]=='B'){
            if(op){
                op--;
            }
            ans++;
        }
    }
    ans+=op;

    cout<<ans<<nl;
}

