int fast_pow(int a,int b){
	a%=mod;
	b%=mod-1;
	int ans=1;
	while(b){
		if(b&1){
			ans=ans*a%mod;
		}
		a=a*a%mod;
		b>>=1;
	}
	return ans;
}
int C2(int a){
	a%=mod;
	return a*(a-1)%mod*(mod+1)/2%mod;
}
