struct BITree {
    int s[N];

    void mdf(int p, int k) {
        for (int i = max(p, 1); i <= n; i += lowbit(i))
            s[i] += k;
    }

    int qry(int p) {
        int res = 0;
        for (int i = min(p, n); i; i -= lowbit(i))
            res += s[i];
        return res;
    }
} T;

void mslv() {
    rd(n), rda(a, n);
    rep(i, 1, n) if (a[i] < i) return prs(0);
    per(i, n, 1) d[i] = a[i] != i ? d[c[i] = b[a[i]]] : i, b[a[i]] = i;
    rep(i, 1, n) if (d[i] != a[i]) return prs(0);
    mint ans = 1;
    rep(i, 1, n) {
        if (c[i]) T.mdf(c[i], 1);
        else ans *= i - T.qry(i), T.mdf(i, 1);
    } prs(ans);
}

