// https://atcoder.jp/contests/arc173/editorial/9520
void solve() {
    INT(n);
    vl x(n), y(n);
    rep(i, n) { input(x[i], y[i]); }
    int k = 0;
    auto f = [](ll a, ll b) -> P {
        if(a == 0)
            return {0, 1};
        if(b == 0)
            return {1, 0};
        ll g = gcd(a, b);
        a /= g, b /= g;
        if(a < 0)
            a *= -1, b *= -1;
        return {a, b};
    };
    vector<P> s;
    rep(i, n) {
        if(s.size() < 2) {
            s.emplace_back(x[i], y[i]);
        } else {
            auto p = s[0], q = s[1];
            if(f(p.first - q.first, p.second - q.second) ==
               f(p.first - x[i], p.second - y[i])) {
                s.emplace_back(x[i], y[i]);
            } else {
                s.pop_back();
                s.pop_back();
            }
        }
    }
    if(s.size() > 2) {
        auto p = s[0], q = s[1];
        auto f0 = f(p.first - q.first, p.second - q.second);
        k = 1;
        rep(i, n) {
            if(make_pair(x[i], y[i]) == p)
                continue;
            if(f0 == f(p.first - x[i], p.second - y[i]))
                ++k;
        }
    }
    int l = n - k;
    if(k >= 2 * l) {
        print(l);
    } else {
        print(n / 3);
    }
}
int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    solve();
}

