	int val = 10;
	int root = 10;
	while (root * root + root - 1 <= n) {
		cnt += 1 + root * 2;
		root *= 10;
	}
	if (n >= root * root) {
		cnt += 1 + root + n - root * root + 1;
	}
	else if (n >= (root - 1) * (root)) {
		cnt += 2 + n - (root - 1) * root;
	}
	else if (n >= (root - 2) * root) {
		cnt++;
	}
	return cnt;
}
