template <typename A, typename B>
bool chmin(A &a, const B &b) {
	if(a > b) {
		return a = b, true;
	}
	return false;
}

template <typename A, typename B>
bool chmax(A &a, const B &b) {
	if(a < b) {
		return a = b, true;
	}
	return false;
}

void solve() {
	int n, a, b; cin >> n >> a >> b;

	string s; cin >> s;

	int op = 0, cl = 0;

	for(int i = 0; i < 2 * n; i++) {
		if(s[i] == '(') {
			op++;
		} else {
			if(op == 0) cl++;
			else op--;
		}
	}

	if(op < cl) swap(op, cl);

	op -= cl;

	op >>= 1;
	cl = (cl + 1) / 2;

	cout << min(a, 2 * b) * cl + op * b << nl;
}

signed main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	solve();
}

