ostream& operator<<(ostream& os, __int128 x) {
    string s;
    int sign = x < 0 ? -1 : 1;
    while (x > 0) {
        s += (char)('0' + (x % 10));
        x /= 10;
    }
    if (s.empty()) {
        os << '0';
    } else {
        reverse(s.begin(), s.end());
        if (sign < 0) {
            os << "-" << s;
        } else {
            os << s;
        }
    }
    return os;
}

