    cout << fixed << setprecision(12);


    int t;
    cin >> t;
    int m = 5;
    while (t-- > 0) {
        int n;
        cin >> n;
        vector<vector<int>> A(n, vector<int>(m, 0));
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                cin >> A[i][j];
            }
        }
        vector<int> R(n);
        for (int i = 0; i < n; ++i) {
            cin >> R[i];
            --R[i];
        }
        cout << solve(A, R) << '\n';
    }

    return 0;
}

