// Division/inverses only allowed if `md` is prime
template<uint32_t md>
class modint {
    using mint = modint;

    public:
    static constexpr uint32_t mod = md;

    constexpr modint() : x() {}
#define CONSTR(type, utype) \
    constexpr modint(utype x_) : x(x_ < md ? x_ : x_ % md) {} \
    constexpr modint(type  x_) : x(0 <= x_ && (utype) x_ < md ? x_ : ((x_ %= md) < 0 ? x_ + md : x_)) {}
    CONSTR(signed char, unsigned char); CONSTR(signed int, unsigned int);
    CONSTR(signed long, unsigned long); CONSTR(signed long long, unsigned long long);
#ifdef __SIZEOF_INT128__
    CONSTR(__int128_t, __uint128_t);
#endif
#undef CONSTR

    template<typename T>
    static constexpr mint raw(T x) { return {x}; }

    constexpr uint32_t val() const { return x; }
    template<typename T>
    constexpr explicit operator T() const { return T(x); }

    constexpr mint &operator++() { ++x == md ? x = 0 : x; return *this; }
    constexpr mint operator++(int) { uint32_t x_ = x; operator++(); return {x_}; }

    constexpr mint &operator--() { x ? --x : x = md - 1; return *this; }
    constexpr mint operator--(int) { uint32_t x_ = x; operator--(); return {x_};}

    constexpr mint &operator+=(const mint &b) { x < md - b.x ? x += b.x : x += b.x - md; return *this; }
    constexpr mint &operator-=(const mint &b) { x >= b.x ? x -= b.x : x += md - b.x; return *this; }
    constexpr mint &operator*=(const mint &b) { x = uint64_t(x) * b.x % md; return *this; }
    constexpr mint &operator/=(const mint &b) { x = uint64_t(x) * inv_constexpr(b.x) % md; return *this; }

    constexpr friend mint operator+(const mint &a, const mint &b) { return {a.x + b.x - (a.x >= md - b.x) * md}; }
    constexpr friend mint operator-(const mint &a, const mint &b) { return {a.x - b.x + (a.x < b.x) * md}; }
    constexpr friend mint operator*(const mint &a, const mint &b) { return {uint64_t(a.x) * b.x % md}; }
    constexpr friend mint operator/(const mint &a, const mint &b) { return {uint64_t(a.x) * inv_constexpr(b.x) % md}; }

    constexpr mint operator+() const { return {x}; }
    constexpr mint operator-() const { return {x ? md - x : x}; }

#define CMP(c) constexpr friend bool operator c(const mint &a, const mint &b) { return a.x c b.x; }
    CMP(==); CMP(!=); CMP(<); CMP(<=); CMP(>); CMP(>=); 
#undef CMP

    template<typename I>
    friend I &operator>>(I &in, mint &a) { return in >> a.x; }
    template<typename O>
    friend O &operator<<(O &out, const mint &a) { return out << a.x; }

    friend std::string to_string(const mint &a) { return std::to_string(a.x); }

    constexpr mint inv() const { return {inv_constexpr(x)}; }

    static int inv_precomputed_up_to() { return inv_.size() - 1; }
    static int fact_precomputed_up_to() { return fact_.size() - 1; }

    // https://cp-algorithms.com/algebra/module-inverse.html#finding-the-modular-inverse-for-prime-moduli-using-euclidean-division
    static void precompute_inv(uint32_t n) {
        if (n < inv_.size()) return;
        uint32_t a = inv_.size(); inv_.resize(n + 1);
        for (; a <= n; ++a) inv_[a] = md - uint64_t(md / a) * inv_[md % a] % md;
    }

    static void precompute_fact(uint32_t n) {
        if (n < fact_.size()) return;
        precompute_inv(n);
        uint32_t a = fact_.size(); fact_.resize(n + 1); inv_fact_.resize(n + 1);
        for (; a <= n; ++a)
            fact_[a] = uint64_t(fact_[a - 1]) * a % md,
            inv_fact_[a] = uint64_t(inv_fact_[a - 1]) * inv_[a] % md;
    }

    static mint inv(uint32_t n) { return n < inv_.size() ? raw(inv_[n]) : inv_constexpr(n); }
    static mint fact(uint32_t n) { return precompute_fact(n), raw(fact_[n]); }
    static mint inv_fact(uint32_t n) { return precompute_fact(n), raw(inv_fact_[n]); };

    static mint binom(int n, int k) {
        if (n < 0 || k < 0 || k > n) return {0};
        return fact(n) * inv_fact(k) * inv_fact(n - k);
    }
    static mint catalan(int n) { return n < 0 ? raw(0) : binom(2 * n, n) * inv(n + 1); }

    private:
    uint32_t x;

    static inline std::vector<uint32_t> inv_ = {0, 1}, fact_ = {1, 1}, inv_fact_ = {1, 1};

    static constexpr uint32_t inv_constexpr(uint32_t x) {
        uint32_t ans = 1;
        for (uint32_t a = x, b = md - 2; b; b >>= 1, a = uint64_t(a) * a % md) if (b & 1) ans = uint64_t(ans) * a % md;
        return ans;
    }
};

using modint1000000007 = modint<1000000007>;
