mint mpow(mint a, ll e) {
    mint ans = 1;
    for (; e; a *= a, e /= 2) if (e & 1) ans *= a;
    return ans;
}

int main() {
    cin.tie(0)->sync_with_stdio(0);
    cin.exceptions(cin.failbit);

    const int N = 1e6 + 50;
    vector<mint> pw(N);
    pw[0] = 1;
    rep(i, 1, N) pw[i] = pw[i - 1] * 10;

    int t;
    cin >> t;
    while (t--) {
        int a1, a2, a3;
        cin >> a1 >> a2 >> a3;
        if (a2 < a1) {
            swap(a1, a2);
        }
        mint x;
        mint p1 = mpow(10, a1 - 1), p2 = mpow(10, a2 - 1);
        if (a1 == a2) {
            x = 8*p1 * (8*p1 + 1) / 2;
        } else {
            x = 9*p1 * (9*p2 - (p1 + 10*p1 - 1) / 2);
        }
        if (a3 == a2) {
            cout << x << '\n';
        } else if (a3 == a2 + 1) {
            cout << (9*p1)*(9*p2) - x << '\n';
        } else {
            cout << 0 << '\n';
        }
    }

    return 0;
}

