			{
				if (p[i] == p[j])
				{
					cout<<"0\n";
					return ;
				}
				else if (p[i] < p[j])
				{
					if (st[i] == 2 || st[j] == 1)
					{
						cout<<"0\n";
						return ;
					}
					st[i] = 1, st[j] = 2;
