        dp[i][1] = max(sz[ch[ch[i][0]][1]] + dp[ch[i][1]][1], sz[ch[ch[i][0]][0]] + dp[ch[i][1]][0]);
    }
    write(max(dp[1][0], dp[1][1]));
    return 0;
}

