#define fre(s) freopen(s ".in", "r", stdin), freopen(s ".out", "w", stdout)
namespace IO
{
    inline void read() {}
    template<typename _Tint, typename... _Args>
    inline void read(_Tint &n, _Args &...args)
    {
        char c, lst;
        lst = '0';
        while (!isdigit(c = getchar()))
            lst = c;
        n = (c ^ '0');
        while (isdigit(c = getchar()))
            n = (n << 3) + (n << 1) + (c ^ '0');
        if (lst == '-')
            n = -n;
        read(args...);
    }
    inline void write() {}
    template<typename _Tint, typename... _Args>
    inline void write(_Tint a, const _Args &...args)
    {
        char s[128];
        int ptr = 0;
        while (a)
        {
            s[++ptr] = '0' + a % 10;
            a /= 10;
        }
        for (int i = ptr; i; --i)
            putchar(s[i]);
        write(args...);
    }
}
namespace Solution
{
    using namespace std;
    typedef long long i64;
    typedef __int128 i128;
    typedef unsigned long long u64;
    const int MAXN = 2e5;
    i64 n;
    i64 a[MAXN + 1], b[MAXN + 1];
    inline void initialization()
    {
        i64 sum = 0;
        IO::read(n);
        for (int i = 1; i <= n; ++i)
            IO::read(a[i]), sum += a[i];
        for (int i = 1; i <= n; ++i)
            b[i] = sum / n + (i > (n - sum % n));
    }
    inline void main()
    {
        initialization();
        i64 res = 0;
        for (int i = n; i; --i)
        {
            res += a[i] - b[i];
            if (res < 0)
                return puts("No"), void();
        }
        puts("Yes");
    }
}
int main()
{
    // fre("b");
    int T = 1;
    IO::read(T);
    while (T--)
        Solution::main();
    return 0;
}

