bool brute(int n, int k) {
    int tp = 1;
    int c = 0;
    set<int> s;
    while (!s.count(c)) {
        s.insert(c);
        if (tp == 1) {
            c = (2 * k - c + n) % n;
        }
        else {
            c = (2 * 0 - c + n) % n;
        }
        tp ^= 1;
    }
    if (s.size() == n) return true;
    if (s.size() % 2 == 1) {
        int c = k;
        if (!s.count(k)) {
            c = k;
        }
    }
}
