    int tst;
    cin >> tst;
    while (tst--) {
        int n, k;
        cin >> n >> k;
        if (n % 2 == 1) {
            if (__gcd(n, k) == 1) {
                cout << "Yes\n";
            }
            else {
                cout << "No\n";
            }
        }
        else if (n == 2) {
            cout << "Yes\n";
        }
        else if (n == 2 * k) {
            cout << "No\n";
        }
        else {
            if (n % 4 == 2 && __gcd(n / 2, k) == 1) cout << "Yes\n";
            else cout << "No\n";
        }
    }
    return 0;
}

