	for(;c<'0'||c>'9';c=getchar())
		if(c=='-')flag=0;
	for(;c>='0'&&c<='9';c=getchar())
		num=(num<<1)+(num<<3)+c-'0';
	return flag?num:-num;
}
const int N=2e5+10;
int n,x,a[N],b[N],p[N],q[N],id[N];
struct BIT{
	#define lowbit(x) (x&-x)
	int c[N];
	void add(int x,int z){
		for(;x<=n;x+=lowbit(x)){
			c[x]=max(c[x],z);
		}
	}
	int getMax(int x){
		int Max=0;
		for(;x;x-=lowbit(x)){
			Max=max(Max,c[x]);
		}
		return Max;
	}
}Tr;
signed main(){
	n=read();x=read();int cnt=0;
	for(int i=1;i<=n;i++){
		a[i]=read();
		cnt+=a[i];
	}
	for(int i=1;i<=n;i++){
		b[i]=read();
		cnt+=b[i];
	}
	for(int i=1;i<=n;i++){
		p[i]=read();
	}
	for(int i=1;i<=n;i++){
		q[i]=read();
	}
	deque<int>A,B;
	int now=x;
	while(p[now]!=x){
		if(a[p[now]])cnt--;
		A.push_back(p[now]);
		now=p[now];
	}
	while(!A.empty()&&a[A.front()]==0)A.pop_front();
	if(a[x])cnt--;
	if(b[x])cnt--;
	now=x;
	while(q[now]!=x){
		if(b[q[now]]!=0)cnt--;
		B.push_back(q[now]);
		now=q[now];
	}
	while(!B.empty()&&b[B.front()]==0)B.pop_front();

	if(cnt!=0){
		printf("-1\n");
		return 0;
	}
	for(int i=0;i<A.size();i++){
		id[A[i]]=i+1;
	}
	vector<int>C;
	for(auto it:B){
		if(id[it]){
			C.push_back(id[it]);
		}
	}
	int Max=0;
	for(auto it:C){
		int now=Tr.getMax(it)+1;
		Max=max(Max,now);
		Tr.add(it,now);
	}
	printf("%d",A.size()+B.size()-Max);
	return 0;
}

