int solve() {
  ll N, Q;
  cin >> N;
  vi W(N+1), L(N+1), R(N+1);
  vc<pi> LI(N);
  rep(i, 1, N+1) cin >> W[i];
  rep(i, 1, N+1) cin >> L[i] >> R[i];

  const ll M = 2*N+1;
  vi l(M+1, inf), r(M+1, inf);
  rep(i, 1, N+1) {
    chmin(l[R[i]], W[i]);
    chmin(r[L[i]], W[i]);
  }
  rep(i, 1, M) chmin(l[i], l[i-1]);
  rrep(i, 1, M) chmin(r[i], r[i+1]);

  cin >> Q;
  rep(Q) {
    ll s, t;
    cin >> s >> t;
    if (L[s] > L[t]) swap(s, t);
    if (R[s] < L[t]) {
      print(W[s] + W[t]);
      continue;
    }
    ll ans = inf;
    chmin(ans, W[s] + W[t] + l[L[s]-1]);
    chmin(ans, W[s] + W[t] + r[max(R[s], R[t])+1]);
    if (R[s] < R[t]) chmin(ans, W[s] + W[t] + r[R[s]+1] + l[L[t]-1]);
    if (ans > inf/2) ans = -1;
    print(ans);
  }

  return 0;
}

