void chkmin(int &x,int y) {x>y?x=y:0;}

const int N=200200;

int n,m;
int a[N],b[N];

int x[N],y[N];

int main() {
    ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);
    cin>>n>>m;
    rep(i,1,n) cin>>a[i];
    rep(i,1,m) cin>>b[i];
    int p=0;
    rep(i,1,n) {
        if(p<m&&a[i]==b[p+1]) {
            p++;
            x[p]=i;
        }
    }
    if(p!=m) {
        cout<<"No\n";
        return 0;
    }
    p=m;
    per(i,n,1) {
        if(p>=1&&a[i]==b[p]) {
            y[p]=i;
            p--;
        }
    }
    int fl=0;
    rep(i,1,m) if(x[i]!=y[i]) fl=1;
    if(fl) cout<<"Yes\n"; else cout<<"No\n";
    return 0;
}

