struct custom_hash {
    const unsigned long long FIXED_RANDOM = chrono::duration_cast<chrono::nanoseconds>(chrono::high_resolution_clock::now().time_since_epoch()).count();
    static unsigned long long splitmix64(unsigned long long x) {
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }

    template <typename T>
    unsigned long long hash_combine(unsigned long long hr, const T &x) const noexcept {
        return hr ^ ((*this)(x) + (hr << 11) + (hr >> 13));
    }
    template <typename T, typename U>
    unsigned long long operator()(const pair<T, U> &p) const noexcept {
        return hash_combine((*this)(p.first), p.second);
    }

    unsigned long long operator()(const unsigned long long x) const noexcept {
        return splitmix64(x + FIXED_RANDOM);
    }
    unsigned long long operator()(const string& x) const noexcept {
        return splitmix64(std::hash<string>()(x) + FIXED_RANDOM);
    }
};

template <typename K, typename V>
struct HashMap {
    using u32 = uint32_t;
    using u64 = uint64_t;

    HashMap (u32 n = 0) { build(n); }
    void build(u32 n) {
        u32 k = 8;
        while (k < n*2) k *= 2;
        cap = k/2, mask = k-1;
        key.resize(k), val.resize(k), used.assign(k, false);
    }

    // do not change size
    void clear() {
        used.assign(used.size(), false);
        cap = (mask+1)/2;
    }
    int size() const { return used.size()/2 - cap; }

    int index(const K& k) const {
        int i = 0;
        for (i = hash(k); used[i] and key[i] != k; i = (i+1)&mask);
        return i;
    }

    V& operator[](const K& k) {
        if (cap == 0) extend();
        int i = index(k);
        if (!used[i]) { used[i] = true, key[i] = k, val[i] = V{}, cap--; }
        return val[i];
    }

    V get(const K& k, V default_value) const {
        int i = index(k);
        return used[i] ? val[i] : default_value;
    }

    bool count(const K& k) const {
        int i = index(k);
        return used[i] and key[i] == k;
    }

    void erase(const K& k) {
        int i = index(k);
        if(used[i]) { used[i] = false, key[i] = 0, val[i] = V{}, cap++; }
    }

    // execute f(key, val) for every entry
    template <typename F>
    void enumerate_all(F f) const {
        for (int i = 0; i < (int)used.size(); i++) if (used[i]) f(key[i], val[i]);
    }

private:
    custom_hash ch;
    u32 cap, mask;
    vector<K> key;
    vector<V> val;
    vector<bool> used;

    u64 hash(K x) const {
        return ch(x) & mask;
    }

    void extend() {
        vector<pair<K, V>> dat;
        dat.reserve(used.size()/2-cap);
        for (int i = 0; i < (int)used.size(); i++) if (used[i]) dat.emplace_back(key[i], val[i]);
        build(2 * dat.size());
        for (const auto& [k, v] : dat) (*this)[k] = v;
    }
};

int main() {
    int n; in(n);
    vector<int> a(n),b(n); in(a,b);
    int qa = 0, qb = 0;
    HashMap<int,int> mpa, mpb;
    rep(i,n){
        if(a[i]==-1) qa++;
        else mpa[a[i]]++;
    }
    rep(i,n){
        if(b[i]==-1) qb++;
        else mpb[b[i]]++;
    }
    if(qa + qb >= n){
        out("Yes");
        return 0;
    }
    HashMap<int,int> mp;
    mpa.enumerate_all([&](int ai, int ac){
        mpb.enumerate_all([&](int bi, int bc){
            mp[ai+bi] += min(ac,bc);
        });
    });
    int mx = max(MAX(a), MAX(b));
    mp.enumerate_all([&](int val, int cnt){
        if(cnt >= n-qa-qb and val >= mx){
            out("Yes");
            exit(0);
        }
    });
    out("No");
}

#include<bits/stdc++.h>
using namespace std;
namespace FastIO {
    constexpr int LEN = 1 << 20;
    char in[LEN + 1], out[LEN + 1];
    char *pin = in, *pout = out, *ein = in, *eout = out + LEN;

    char gc() { return pin == ein && (ein = (pin = in) + fread(in, 1, LEN, stdin), ein == in) ? EOF : *pin ++; }
    void pc(char c) { pout == eout && (fwrite(out, 1, LEN, stdout), pout = out); (*pout ++) = c; return; }
    struct Flush { ~Flush() { fwrite(out, 1, pout - out, stdout); pout = out; return; } } _flush;

    template<typename T> T Read() {
        T x = 0; int f = 1; char ch = gc();
        while (ch < '0' || ch > '9') f = (ch == '-' ? (~f + 1) : f), ch = gc();
        while (ch >= '0' && ch <= '9') x = (x << 1) + (x << 3) + (ch ^ 48), ch = gc();
        return x * f;
    }
    void Read(char *s) {
        char ch = gc();
        while (ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t') ch = gc();
        while ((ch != EOF) && !(ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t')) *s = ch, s ++, ch = gc();
        *s = '\0'; return;
    }
    template<typename T> void Read(T &x) { x = Read<T>(); return; }
    template<typename T, typename ...Args>
    void Read(T &x, Args &...args) { Read(x), Read(args...); return; }
    template<typename T> void Write(T x) {
        static char stk[40]; int tp = 0;
        if (x < 0) pc('-'), x = ~x + 1;
        do stk[tp++] = x % 10 + 48, x /= 10; while (x);
        while (tp --) pc(stk[tp]);
        return;
    }
    void Write(char ch) { pc(ch); return; }
    void Write(const char *s) {
        while (*s != '\0') pc(*s), s++;
        return;
    }
    void Puts(const char *s) {
        Write(s), pc('\n'); return;
    }
    template<typename T, typename ...Args>
    void Write(T x, Args ...args) { Write(x), Write(args...); return; }
}

using namespace FastIO;

void solve(int r, int b) {
    int k = (b & 1) > 0 ? 0 : 1;
    int rl = (b+3)>>1;
    for (int i = 1; i < rl; i++) {
        Write("B ", i, " ", i + k, "\n");
    }
    if (r > 0) {
        Write("R ", rl, " ", rl + k, "\n");
        for (int i = 1; i <= (r - 2) / 2; i++) {
            Write("R ", rl + i, " ", rl + k, "\n");
        }
        for (int i = (r - 2) / 2; i > 0; i--) {
            Write("R ", rl + i, " ", rl + k - 1, "\n");
        }
        if (k == 1) {
            Write("R ", rl, " ", rl, "\n");
        }
    }
    for (int row = rl; row >= 3 - k; row--) {
        Write("B ", row, " ", row - 1, "\n");
    }
    if (r > 0 && !k) {
        Write("R ", 2, " ", 1, "\n");
    }
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int T = Read<int>();
    int r, b;
    while (T--) {
        r = Read<int>();
        b = Read<int>();
        if ((r & 1) || (!r && (b & 1))) {
            Puts("No");
        } else {
            Puts("Yes");
            solve(r, b);
        }
    }
}

