#include <iostream>
#include <algorithm>
using namespace std;

void solve() {
	int h, w;
	cin >> h >> w;
	string s;
	cin >> s;
	long long not_reachable = 0;
	pair<int, int> pos = make_pair(1, 1);
	int moved_right = 0;
	int to_move_right = count(s.begin(), s.end(), 'R');
	for (char dir : s) {
		to_move_right -= (dir == 'R');
		if (dir == 'D' || moved_right + to_move_right == w - 1) {
			not_reachable += w - pos.second;
			++pos.first;
		}
		else {
			++pos.second;
			++moved_right;
		}
	}
	pos = make_pair(1, 1);
	int moved_down = 0;
	int to_move_down = count(s.begin(), s.end(), 'D');
	for (char dir : s) {
		to_move_down -= (dir == 'D');
		if (dir == 'R' || moved_down + to_move_down == h - 1) {
			not_reachable += h - pos.first;
			++pos.second;
		}
		else {
			++pos.first;
			++moved_down;
		}
	}
	cout << (long long)h * w - not_reachable << '\n';
}

