	for (int i = 0; i < n; ++i) {
		cin >> a[i];
	}
	sort(a, a + n);
	int answer = 0;
	long long sum = 0;
	int j = 0;
	for (int i = 0; i < n; ++i) {
		sum += a[i];
		while (j < i && (long long)a[j + 1] * (i + 1) <= sum) {
			++j;
		}
		answer = max(answer, i - j);
	}
	cout << answer << '\n';
}

