namespace fast_IO {
#define IOSIZE 100000
    int precision = 3, POW[10] = {1, 10, 100, 1000, 10000, 100000, 1000000, 10000000, 100000000, 1000000000};    // 向下取整到小数点后第 precision 位
    char ibuf[IOSIZE], obuf[IOSIZE], *p1 = ibuf, *p2 = ibuf, *p3 = obuf; 
#ifdef ONLINE_JUDGE
#define getchar() ((p1==p2)and(p2=(p1=ibuf)+fread(ibuf,1,IOSIZE,stdin),p1==p2)?(EOF):(*p1++))
#endif 
#define putchar(x) ((p3==obuf+IOSIZE)&&(fwrite(obuf,p3-obuf,1,stdout),p3=obuf),*p3++=x)
#define isdigit(ch) (ch>47&&ch<58)
#define isspace(ch) (ch<33)
    template<typename T> inline T read() { T s = 0; int w = 1; char ch; while (ch = getchar(), !isdigit(ch) and (ch != EOF)) if (ch == '-') w = -1; if (ch == EOF) return false; while (isdigit(ch)) s = s * 10 + ch - 48, ch = getchar(); return s * w; }
    template<typename T> inline bool read(T &s) { s = 0; int w = 1; char ch; while (ch = getchar(), !isdigit(ch) and (ch != EOF)) if (ch == '-') w = -1; if (ch == EOF) return false; while (isdigit(ch)) s = s * 10 + ch - 48, ch = getchar(); return s *= w, true; }
    template<typename T> inline void print(T x) { if (x < 0) putchar('-'), x = -x; if (x > 9) print(x / 10); putchar(x % 10 + 48); }
    inline bool read(char &s) { while (s = getchar(), isspace(s) and s != EOF); return s != EOF; }
    inline void print(char x) { putchar(x); }
    inline bool read(char *s) { char ch; while (ch = getchar(), isspace(ch) && ch != EOF); if (ch == EOF) return false; while (!isspace(ch) and (ch != EOF)) *s++ = ch, ch = getchar(); *s = '\0'; return true; }
    inline void print(char *x) { while (*x) putchar(*x++); }
    inline void print(const char *x) { for (int i = 0; x[i]; i++) putchar(x[i]); }
    inline bool read(std::string& s) { s = ""; char ch; while (ch = getchar(), isspace(ch) and ch != EOF); if (ch == EOF) return false; while (!isspace(ch)) s += ch, ch = getchar(); return true; }
    inline void print(std::string x) { for (int i = 0, n = x.size(); i < n; i++) putchar(x[i]); }
    inline bool read(bool &b) { char ch; while(ch=getchar(), isspace(ch) and ch != EOF); return ch == EOF ?false :(b=ch^48, true); }
    inline void print(bool b) { putchar(b+48); }
    inline bool read(double &x) { char ch = getchar(); int f = 1; for(; (ch<48 or 57<ch) and (ch != EOF); ch=getchar()) if(ch == '-')    f = -1; if(ch == EOF)    return false; for(x=0; 47<ch and ch<58; ch=getchar())    x = x*10 + (ch^48); if(ch != '.')    return x *= f, true; double y = 0.1; for(ch=getchar(); 47<ch and ch<58; ch=getchar())    x += y*(ch^48), y /= 10; return x *= f, true; }
    inline void print(double x) { if(x < 0)    putchar('-'), x = -x; print((unsigned long long)(x)); if(precision) putchar('.'), print((unsigned long long)((x-(unsigned long long)(x))*POW[precision])); }
    // double 暂时只支持向下取整
    template<typename T, typename... T1> inline int read(T& a, T1&... other) { return read(a) + read(other...); }
    template<typename T, typename... T1> inline void print(T a, T1... other) { print(a), print(other...); }
    struct Fast_IO { 
        bool flag = 1;
        inline ~Fast_IO() { fwrite(obuf, p3 - obuf, 1, stdout); } 
        inline void SetPrecision(int x) { if(x > 9)    throw runtime_error("Precision too high!"); else if(x < 0) throw runtime_error("Precision too low!"); else precision = x; } // 浮点数精度设为 x，即精确到小数点后 x 位。
        inline operator bool() { return flag; }
    } io;
    template<typename T> Fast_IO& operator >> (Fast_IO &io, T &b) { return io.flag &= read(b), io; }
    template<typename T> Fast_IO& operator << (Fast_IO &io, T b) { return print(b), io; }
#define cout io
#define cin io
#define endl '\n'
} using namespace fast_IO;
namespace furina{
const int N = 2e5, mod = 998244353, inf = 0x7fffffff >> 1;
int inv2, inv6;
inline int add(int a, int b){
    return a + b >= mod ? a + b - mod : a + b;
}
inline int sub(int a, int b){
    return a - b < 0 ? a - b + mod : a - b;
}
inline int pow(int a, int b){
    int ans = 1;
    for(; b; b >>= 1, a = 1ll * a * a % mod)
        if(b & 1)
            ans = 1ll * ans * a % mod;
    return ans;
}
int n, h, w;
inline int sum1(int n){
    return ((1ll * (n + 1) * n) >> 1) % mod;
}
inline int sum2(int n){
    return 1ll * n * (n + 1) % mod * ((n << 1) + 1) % mod * inv6 % mod;
}
inline int sum3(int n){
    return 1ll * sum1(n) * sum1(n) % mod;
}
inline int get(int m){
    m -= n << 1;
    int ans = 0;
    ans = add(ans, 1ll * inv2 * add(sum2(m), sum1(m)) % mod);
    ans = add(ans, 1ll * inv6 * add(add(2ll * sum3(m) % mod, 3ll * sum2(m) % mod), sum1(m)) % mod);
    return 1ll * ans * inv2 % mod;
}
inline void solve(){
    cin >> n >> h >> w;
    if(h < (n << 1) || w < (n << 1)){
        cout << "0\n";
        return;
    }
    int x = sub(1ll * (h - (n << 1) + 1) * (h - (n << 1) + 2) % mod, sum1(h - (n << 1) + 1));
    int y = sub(1ll * (w - (n << 1) + 1) * (w - (n << 1) + 2) % mod, sum1(w - (n << 1) + 1));
    int ans = 1ll * x * x % mod * y % mod * y % mod;
    x = get(h);
    y = get(w);
    cout << sub(ans, 2ll * x * y % mod) << '\n';
}
int main(){
    inv2 = pow(2, mod - 2), inv6 = pow(6, mod - 2);
    int T;
    cin >> T;
    while(T--)
        solve();
    return 0;
}
}
