int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

int gcd(int a, int b, int c) {
    return gcd(a, gcd(b, c));
}


int lcm(int a, int b) {
    return (a / gcd(a, b)) * b;
}
bool isPrime(int num) {
    if (num <= 1) return false;
    for (int i = 2; i <= sqrt(num); i++) {
        if (num % i == 0)
            return false;
    }
    return true;
}
int mod_add(int a, int b, int m = mod) {
    return (a + b) % m;
}

int mod_sub(int a, int b, int m = mod) {
    return (a - b + m) % m;
}

int mod_mul(int a, int b, int m = mod) {
    return (1LL * a * b) % m;
}

int mod_exp(int base, int exp, int m = mod) {
    int res = 1;
    while (exp > 0) {
        if (exp % 2 == 1) res = (1LL * res * base) % m;
        base = (1LL * base * base) % m;
        exp /= 2;
    }
    return res;
}

vector<int> compress(vector<int> &v) {
    vector<int> temp = v;
    sort(all(temp));
    temp.erase(unique(all(temp)), temp.end());
    for (auto &x : v) x = lower_bound(all(temp), x) - temp.begin();
    return v;
}
