const ll MOD7 = 1000000007, MOD998 = 998244353, INF = (1LL << 60);
#define dout(a) cout<<fixed<<setprecision(10)<<a<<endl;

template<int MOD> struct Modint {
    long long val;
    constexpr Modint(long long v = 0) noexcept : val(v % MOD) { if (val < 0) val += MOD; }
    constexpr int mod() const { return MOD; }
    constexpr long long value() const { return val; }
    constexpr Modint operator - () const noexcept { return val ? MOD - val : 0; }
    constexpr Modint operator + (const Modint& r) const noexcept { return Modint(*this) += r; }
    constexpr Modint operator - (const Modint& r) const noexcept { return Modint(*this) -= r; }
    constexpr Modint operator * (const Modint& r) const noexcept { return Modint(*this) *= r; }
    constexpr Modint operator / (const Modint& r) const noexcept { return Modint(*this) /= r; }
    constexpr Modint& operator += (const Modint& r) noexcept {
        val += r.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }
    constexpr Modint& operator -= (const Modint& r) noexcept {
        val -= r.val;
        if (val < 0) val += MOD;
        return *this;
    }
    constexpr Modint& operator *= (const Modint& r) noexcept {
        val = val * r.val % MOD;
        return *this;
    }
    constexpr Modint& operator /= (const Modint& r) noexcept {
        long long a = r.val, b = MOD, u = 1, v = 0;
        while (b) {
            long long t = a / b;
            a -= t * b, swap(a, b);
            u -= t * v, swap(u, v);
        }
        val = val * u % MOD;
        if (val < 0) val += MOD;
        return *this;
    }
    constexpr bool operator == (const Modint& r) const noexcept { return this->val == r.val; }
    constexpr bool operator != (const Modint& r) const noexcept { return this->val != r.val; }
    friend constexpr istream& operator >> (istream& is, Modint<MOD>& x) noexcept {
        is >> x.val;
        x.val %= MOD;
        if (x.val < 0) x.val += MOD;
        return is;
    }
    friend constexpr ostream& operator << (ostream& os, const Modint<MOD>& x) noexcept {
        return os << x.val;
    }
    constexpr Modint<MOD> pow(long long n) noexcept {
        if (n == 0) return 1;
        if (n < 0) return this->pow(-n).inv();
        Modint<MOD> ret = pow(n >> 1);
        ret *= ret;
        if (n & 1) ret *= *this;
        return ret;
    }
    constexpr Modint<MOD> inv() const noexcept {
        long long a = this->val, b = MOD, u = 1, v = 0;
        while (b) {
            long long t = a / b;
            a -= t * b, swap(a, b);
            u -= t * v, swap(u, v);
        }
        return Modint<MOD>(u);
    }
};

const int MOD = MOD998;
using mint = Modint<MOD>;

struct Combination {
    long long C_MOD;
    vector<long long> fac, finv, inv;
    Combination(long long n, long long mod) noexcept : C_MOD(mod) {
        n = max(n, 2LL);
        fac.resize(n, 0);
        finv.resize(n, 0);
        inv.resize(n, 0);
        fac[0] = fac[1] = finv[0] = finv[1] = inv[1] = 1;
        for(int i = 2; i < n; i ++) {
            fac[i] = fac[i - 1] * i % mod;
            inv[i] = mod - inv[mod % i] * (mod / i) % mod;
            finv[i] = finv[i - 1] * inv[i] % mod;
        }
    }
    long long com(long long n, long long k) {
        if(n < k || n < 0 || k < 0) return 0;
        return fac[n] * (finv[k] * finv[n - k] % C_MOD) % C_MOD;
    }
};

mint memo[100][100];
bool thr[100][100];

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    Combination comb(10000, MOD998);
    memset(thr, 0, sizeof(thr));
    int t; cin >> t;

    auto calc = [&](auto calc, int n, int k) -> mint {
        if(n < 0 or k < 0) return mint(0);
        if(thr[n][k]) return memo[n][k];
        // n bit not used
        // k want use
        if(k == 0) {
            thr[n][k] = 1;
            return memo[n][k] = 1;
        } 
        mint ret = 0;
        for(int i = 1; i <= n; i ++) {
            ret += calc(calc, n - i, k - 1) * mint(comb.com(n, i));
        }
        thr[n][k] = 1;
        return memo[n][k] = ret;
    };
    bool ex[100][100];
    memset(ex, 0, sizeof(ex));
    mint dp[100][100];
    auto C = [&](int cnt, int i) -> mint {
        if(ex[cnt][i]) return dp[cnt][i];
        mint ans = 0;
        for(int j = 0; j <= i; j ++) {
            for(int k = 0; k <= 60; k ++) {
                ans += calc(calc, cnt - j, k) * mint(comb.com(i, j)) * mint(k + 1);
            }
        }
        ex[cnt][i] = 1;
        return dp[cnt][i] = ans;
    };
    while(t --) {
        ll m; cin >> m;
        int id = 0;
        for(int i = 0; i < 60; i ++) {
            if(m >> i & 1) {
                id = i;
            }
        }
        mint ans = 0;
        for(int i = 1; i <= 60; i ++) {
            ans += calc(calc, id, i);
        }
        int cnt = id;
        for(ll i = id - 1; i >= 0; i --) {
            if(m >> i & 1) {
                ans += C(cnt, i);
                cnt --;
            }
        }
        for(int j = 0; j <= 60; j ++) {
            ans += calc(calc, cnt, j) * mint(j + 1);
        }
        cout << ans << endl;
    }
    return 0;
}

