void solve() {
    int n; cin >> n;
    vector<pair<int,int>> a;
    for (int i = 0; i < n; i++) {
        int x; cin >> x;
        a.emplace_back(x, i);
    }
    sort(a.begin(), a.end());
    vector<int> p(n);
    for (int i = 0; i < n; i++) p[i] = a[i].second;
    int ans = n;
    for (int i = 0; i + 1 < n; i++) {
        if (abs(p[i] - p[i + 1]) != 1) continue;
        int j = i + 1;
        while(j < n and abs(p[j - 1] - p[j]) == 1) j++;
        int len = j - i;
        ans -= len - 1;
        i = j - 1;
    }
    cout << ans << '\n';
}

