        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                cin >> matrix[i][j];
            }
        }
        int totalCells = N * M;
        int bestChange = totalCells;
        for (int d1 : {1, -1}) {
            for (int d2 : {1, -1}) {
                unordered_map<long long, int> freq;
                int localMax = 0;
                for (int i = 0; i < N; i++) {
                    for (int j = 0; j < M; j++) {
                        long long candidate = matrix[i][j] - 1LL * d1 * i - 1LL * d2 * j;
                        freq[candidate]++;
                        localMax = max(localMax, freq[candidate]);
                    }
                }
                bestChange = min(bestChange, totalCells - localMax);
            }
        }
        cout << bestChange << "\n";
    }
    return 0;
}

