void solve()
{
    ll n;
    cin >> n;
    ia(a, n);
    ll k = a[0];
    sort(a, a + n);

    if (n == 1)
    {
        cout << 1000000 << nline;
        return;
    }

    if (a[n - 1] == k)
    {
        ll ans = 0;
        // k to 1e6
        ans += 1000000 - k + 1;
        ans += k - (k + a[n - 2] + 1) / 2;
        cout << ans << nline;
    }
    else if (a[0] == k)
    {
        ll ans = 0;
        // 1 to k
        ans += k;
        ans += (a[1] + k) / 2 - k;
        cout << ans << nline;
    }
    else
    {
        auto it = lower_bound(a, a + n, k) - a;
        ll low = (a[it - 1] + a[it] + 1) / 2;
        ll high = (a[it + 1] + a[it]) / 2;
        cout << high - low + 1 << nline;
    }
}

