        int h = a[n - 1];
        int swaps = 0;
        int pos = n - 1;
        while(pos > 0 && a[pos - 1] >= h){
            swap(a[pos], a[pos - 1]);
            pos--;
            swaps++;
        }
        while(pos > 0){
            bool f = true;
            for(int i = 0; i < pos; i++){
                if(a[i] >= h){
                    f = false;
                    break;
                }
            }
            if(f) break;
            pos--;
            swaps++;
        }
        cout << swaps << "\n";
    }
    return 0;
}

