void solve() {
    int x1, y1, z1, x2, y2, z2, k;
    cin >> x1 >> y1 >> z1 >> x2 >> y2 >> z2 >> k;

    int max_diff = max({abs(x1 - x2), abs(y1 - y2), abs(z1 - z2)});
    int total_dist = abs(x1 - x2) + abs(y1 - y2) + abs(z1 - z2);

    int max_moves = ((max_diff + k - 1) / k) - 1;
    int moves = total_dist - max_diff;

    int diff = max_moves - moves;

    cwr(((diff < 0) ? total_dist : total_dist + diff + (diff & 1)));
}

