// ALWAYS USE FIXED << SETPRECISION WHILE OUTPUTTING FLOATS

void solve()
{
    ll n, k;
    cin >> n >> k;
    ia(a, n);
    vector<ll> fr(21);
    f(i, n)
    {
        fr[a[i]]++;
    }
    if (*max_element(fr.begin(), fr.end()) == fr[k])
    {
        cout << 0 << nline;
        return;
    }
    // prefix
    {
        auto temp = fr;
        f(i, n)
        {
            fr[a[i]]--;
            if (fr[k] == 0)
                break;
            if (*max_element(fr.begin(), fr.end()) == fr[k])
            {
                cout << 1 << nline;
                return;
            }
        }
        fr = temp;
    }

    // suffix
    {
        auto temp = fr;
        for (ll i = n - 1; i >= 0; i--)
        {
            fr[a[i]]--;
            if (fr[k] == 0)
            {
                break;
            }
            if (*max_element(fr.begin(), fr.end()) == fr[k])
            {
                cout << 1 << nline;
                return;
            }
        }
        fr = temp;
    }
    cout << 2 << nline;
}

