    int t;
    cin >> t;
    while(t--){
        int n;
        cin >> n;
        string s1, s2, s3;
        cin >> s1 >> s2 >> s3;

        int a1 = count(s1.begin(), s1.end(), '1');
        int a2 = count(s2.begin(), s2.end(), '1');
        int a3 = count(s3.begin(), s3.end(), '1');

        int totalOnes = a1 + a2 + a3;
        if(totalOnes != 0 && totalOnes != n && totalOnes != 2*n && totalOnes != 3*n){
            cout << -1 << "\n";
            continue;
        }

        int k = totalOnes / n;
        vector<int> dspp = {a1, a2, a3};
        int minn = INT_MAX;

        for(int dev = 0; dev < 8; dev++){
            if(__builtin_popcount(dev) == k){
                int sum = 0;
                for(int i = 0; i < 3; i++){
                    if(dev & (1 << i))
                        sum += (n - dspp[i]);
                }
                minn = min(minn, sum);
            }
        }

        cout << minn << "\n";
    }

    return 0;
}

