bool check ( int mid , vector < int > &pos , vector < int > & neg){
     int s = 0 , mx = 0 , j = 0;
     for ( int i = 0; i < pos.size(); i ++ ){
           s += pos[i];
           while ( j < neg.size() && s > mid ){
                s = max ( pos[i] , s + neg[j] );
                j ++ ;
           }
           if ( s > mid ) return false;
     }
     return true;
}
void solve( int tc ){
       int n;
       cin >> n;
       vector < int > pos , neg;
       for ( int i = 0; i < n; i ++ ){
             int x;
             cin >> x;
             if ( x > 0) pos.push_back(x);
             else neg.push_back(x);
       }
       if ( pos.empty() ){
               cout << 0 << endl;
               return;
       }
       int lo = *max_element(all(pos));
       int hi = accumulate(all(pos) , 0ll);
       int ans = 0;
       while ( lo <= hi ){
            int mid = hi + lo ;
            mid /= 2;
            if ( check(mid , pos , neg )){
                ans = mid ;
                hi = mid - 1;
            }
            else lo = mid + 1;
       }
       cout << ans << endl;
}


