    std::cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;

// The maximum value of N is 100,000.
const int MAX = 100000;
vector<long long> fact(MAX + 1), invfact(MAX + 1), pow2Arr(MAX + 1);

// Fast modular exponentiation (mod MOD)
long long modExp(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1)
            result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

// Precompute factorials, inverse factorials and powers of 2 up to MAX.
void precompute() {
    fact[0] = 1;
    for (int i = 1; i <= MAX; i++) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }

    invfact[MAX] = modExp(fact[MAX], MOD - 2, MOD);
    for (int i = MAX - 1; i >= 0; i--) {
        invfact[i] = (invfact[i + 1] * (i + 1)) % MOD;
    }

    pow2Arr[0] = 1;
    for (int i = 1; i <= MAX; i++) {
        pow2Arr[i] = (2 * pow2Arr[i - 1]) % MOD;
    }
}

// Compute nCr modulo MOD (assumes 0 <= r <= n)
long long nCr(int n, int r) {
    if (r < 0 || r > n)
        return 0;
    return ((fact[n] * invfact[r]) % MOD * invfact[n - r]) % MOD;
}

// Main solution
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    precompute();

    int T;
    cin >> T;
    while (T--) {
        int N, K;
        cin >> N >> K;

        // Determine the number m of unordered pairs (a, b) such that:
        // 1 <= a < b <= N  and  a + b = K.
        // Since a < b, we have a < K - a, i.e. 2a < K.
        // Hence a must be in: [ max(1, K-N), floor((K-1)/2) ]
        int lower = max(1, K - N);
        int upper = (K - 1) / 2; // floor((K-1)/2)
        int m = 0;
        if (lower <= upper)
            m = upper - lower + 1;

        // If no valid pair exists, then answer is 0.
        if (m <= 0) {
            cout << 0 << "\n";
            continue;
        }

        // Use inclusion-exclusion:
        // answer = sum_{j=1}^{m} (-1)^(j+1) * C(m, j) * 2^j * (N - j)!
        long long ans = 0;
        for (int j = 1; j <= m; j++) {
            long long ways = nCr(m, j);
            ways = (ways * pow2Arr[j]) % MOD;
            ways = (ways * fact[N - j]) % MOD;

            // Apply sign: (+) when j is odd, (-) when j is even.
            if (j % 2 == 1)
                ans = (ans + ways) % MOD;
            else
                ans = (ans - ways) % MOD;
        }
        if (ans < 0)
            ans += MOD;

        cout << ans % MOD << "\n";
    }
    return 0;
}

