int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while(T--){
        int N;
        cin >> N;
        string S;
        cin >> S;
        string P;
        cin >> P;

        vector<int> pos(26);
        for (int i = 0; i < 26; i++){
            pos[P[i] - 'a'] = i + 1;
        }

        vector<char> A(N), B(N);
        for (int i = 0; i < N; i++){
            A[i] = S[i];
            int p = pos[S[i] - 'a'];
            int x = 27 - p;
            B[i] = P[x - 1];
        }

        const long long INF = 1LL << 60;
        long long dp0 = 0, dp1 = 1;
        for (int i = 1; i < N; i++){
            long long ndp0 = INF, ndp1 = INF;
            for (int j = 0; j < 2; j++){
                char prev = (j == 0 ? A[i - 1] : B[i - 1]);
                long long cost = (j == 0 ? dp0 : dp1);
                if(cost == INF) continue;
                if(prev <= A[i])
                    ndp0 = min(ndp0, cost);
                if(prev <= B[i])
                    ndp1 = min(ndp1, cost + 1);
            }
            dp0 = ndp0;
            dp1 = ndp1;
        }
        long long ans = min(dp0, dp1);
        cout << (ans >= INF ? -1 : ans) << "\n";
    }
    return 0;
}

