lld dist(ii &p1, ii &p2)
{
  if (p1.first == p2.first)
    return (abs(p1.second - p2.second) + 1) / 2;
  if (p1.second == p2.second)
    return (abs(p1.first - p2.first) + 1) / 2;
  return max(abs(p1.first - p2.first), abs(p1.second - p2.second));
}

void solv()
{
  int n;
  cin >> n;
  forn(i, n)
  {
    lld x, y;
    cin >> x >> y;
    wells[i] = {x, y};
  }
  lld inf = 1e10;
  vi dst(n + 1, inf);
  bool vis[n] = {};
  dst[0] = 0;
  lld res = 0;
  forn(p, n)
  {
    int node = n;
    forn(i, n) if (dst[i] < dst[node] && !vis[i]) node = i;
    vis[node] = true;
    res = max(res, dst[node]);
    forn(i, n)
    {
      if (i == node)
        continue;
      if (!vis[i] && dst[i] > dist(wells[node], wells[i]))
      {
        dst[i] = dist(wells[node], wells[i]);
      }
    }
  }
  cln(res);
}

