int maxLength(vector<int>arr,int size,int magicNum){
    int maxLen = 1;
    for(int i=0;i<size;i++){
        int originalArr = arr[i];
        arr[i]=arr[i]*magicNum;
        int count = 1;
        for(int j=1;j<size;j++){
            if(arr[j]>=arr[j-1]){
                count++;
            }else{
                count = 1;
            }
            if(count>maxLen){
                maxLen=count;
            }
        }
        arr[i]=originalArr;
    }
    return maxLen;
}
