using ll = int64_t;
#define sz(x) ((int)(x).size())
const char nl = '\n';

const int maxn = 2e5 + 5;
int grundy[maxn + 1];

int mex (vector<int> v) {
  int ret = 0;

  for (int i = 0; i < sz(v); i++) {
    if (v[i] == ret)
      ret++;
    else if (v[i] < ret) 
      continue;
    else  
      break;
  }

  return ret;
}

template <typename T>
struct Fenwick {  // 1-based
  const int n;
  std::vector<T> a;
  Fenwick(int m) : n(m), a(m) {}
  void add (int x, T v) { // add v to index x
    x--;
    for (int i = x + 1; i <= n; i += i & -i) {
      a[i - 1] += v;
    }
  }
  T sum (int x) {  // sum till index x (1...x)
    T ans = 0;
    for (int i = x; i > 0; i -= i & -i) {
      ans += a[i - 1];
    }
    return ans;
  }
};

int twop[maxn + 1];
const int mod = 1e9 + 7;
vector<int> masks;

void solve() {
  int n;
  cin >> n;
  vector<int> a (n + 1);
  for (int i = 1; i <= n; ++i) 
    cin >> a[i], a[i] = grundy[a[i]];

  vector<Fenwick<int>> f (7, Fenwick<int> (n)); 
  for (int i = 1; i <= n; ++i) {
    f[a[i]].add (i, 1);
  }

  int q;
  cin >> q;

  for (int i = 0, t, x, y; i < q; ++i) {
    cin >> t >> x >> y;

    if (t == 1) {
      ll ans = 0;

      for (int mask : masks) {
        ll cur = 1;

        for (int j = 0; j < 7; ++j) {
          int cnt = f[j].sum (y) - f[j].sum (x - 1);

          if ((mask & (1 << j)) and !cnt) {
            cur = 0;
            break;
          } else if (!cnt)
            continue;

          cur *= twop[cnt - 1];
          cur %= mod;
        } 

        ans += cur;
        ans %= mod;
      }

      ans = (twop[y - x + 1] - ans + mod) % mod;

      cout << ans << nl;
    } else {
      f[a[x]].add (x, -1);
      a[x] = grundy[y];
      f[a[x]].add (x, 1);
    }
  }

}

int32_t main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);

  int mx = 0;
  int p = 1;
  twop[0] = 1;
  for (int i = 1; i <= maxn; ++i) {
    p *= 2, p %= mod;
    twop[i] = p; 

    int x = i;

    vector<int> states;
    while (x) {
      int y = x % 10;
      if (y)
        states.push_back (grundy[i - y]);
      x = x / 10;
    }

    sort (states.begin(), states.end());
    grundy[i] = mex (states);
    mx = max (mx, grundy[i]);
  }

  for (int i = 0; i < (1 << 7); ++i) {
    int xo = 0;
    for (int j = 0; j < 7; ++j) {
      if (i & (1 << j)) {
        xo ^= j;
      }
    }

    if (!xo)
      masks.push_back (i);
  }

  int t = 1;
  for (int i = 1; i <= t; i++)
    solve();

  return 0;
}

#include <bits/stdc++.h>
