#define ll long long
#define pb push_back

int main() {
    int x;
    cin >> x;
    while (x--) {
        int y;
        cin >> y;
        vector < int > z(y);
        for (int i = 0; i < y; i++) cin >> z[i];
        unordered_map < int, int > xy;
        xy.reserve(y * 2);
        for (auto v: z) xy[v]++;
        ll yz = (ll) y * (y - 1) / 2;
        vector < pair < int, int >> xz;
        xz.reserve(xy.size());
        for (auto & p: xy) xz.pb({
            p.first,
            p.second
        });
        unordered_map < int, ll > zy;
        for (auto & p: xz) {
            int noob = p.first;
            int cnt = p.second;
            vector < int > zz;
            for (int i = 0; i < 31; i++)
                if (noob & (1 << i)) zz.pb(i);
            int k = zz.size();
            int val = (1 << k);
            for (int mask = 1; mask < val; mask++) {
                int sub = 0;
                for (int j = 0; j < k; j++)
                    if (mask & (1 << j)) sub |= (1 << zz[j]);
                zy[sub] += cnt;
            }
        }
        ll ans = 0;
        for (auto & p: zy) {
            ll cnt = p.second;
            if (__builtin_popcount(p.first) & 1) ans += cnt * (cnt - 1LL) / 2;
            else ans -= cnt * (cnt - 1LL) / 2;;
        }
        cout << yz + ans << "\n";
    }
    return 0;
}

