#include<bits/stdc++.h>

#define int long long

using namespace std;

const int N = 1e6 + 10 , mod = 1e9 + 7;
bool TC = 1;

void solve() {
    int x , y , z; cin >> x >> y >> z;
    int a , b , c; cin >> a >> b >> c;

    int res = 0 , mx = 0 , my = 0 , mz = 0;
    int zy = 0 , zz= 0;

    if(x >= a) {
        res += a;
    }
    else {
        mx = a - x;
        res += x;
    }

    if(y >= b) {
        res += b;
        zy = y - b;

        if(mx > 0) {
            res += min(mx , zy);
            mx -= min(mx , zy);
        }
    }
    else {
        res += y;
        my = b - y;
    }

    if(z >= c) {
        res += c;
        zz = z - c;
        if(mx > 0) {
            res += min(mx , zz);
            zz -= min(mx , zz);
        }
        if(my > 0) {
            res += min(my , zz);
        }
    }
    else {
        res += z;
    }

    cout << res << '\n';

}

signed main() {
    ios::sync_with_stdio(0); cin.tie(0), cout.tie(0); 

    if (TC) {
        int tc;
        cin >> tc;

        while (tc--) {
            solve();
        }
    } 
    else {
        solve();
    }

    return 0;
}

