int trans(string s){
	s.pop_back();int ans=0;
	for (int i=0;i<s.size();)
		for (int j=0;j<9;j++){
			if (i+str[j].size()>s.size()) continue;
			bool flag=1;
			for (int k=0;k<str[j].size();k++)
				if (s[i+k]!=str[j][k]) {flag=0;break;}
			if (flag) {ans=ans*9+j;i+=str[j].size();break;}
