#include <span>

class Solution {
    int find_pair(std::span<int> nums) {
        const int target = nums.front();
        int bit = std::bit_floor(uint32_t(nums.back()));
        while (nums.size() > 16 && bit) {
            if ((nums.front() & bit) == (nums.back() & bit)) {
                bit >>= 1;
                continue;
            }
            auto it = std::partition_point(nums.begin(), nums.end(), [&](int n) { return !(n & bit); });
            if (target & bit)
                nums = { nums.begin(), it };
            else
                nums = { it, nums.end() };
        }
        int x = 0;
        for (auto n: nums)
            x = std::max(x, n ^ target);
        return x ^ target;
    }
public:
    int maximumStrongPairXor(vector<int>& nums) {
        std::sort(nums.begin(), nums.end());
        int best = 0;
        for (auto l = nums.begin(), r = nums.begin(); l != nums.end(); ++l) {
            while (r != nums.end() && *r <= 2 * *l)
                ++r;
            best = std::max(best, find_pair({l, r}) ^ *l);
        }
        return best;
    }
};

class Solution {
public:
    int distributeCandies(int n, int limit) {
        int cnt = 0;

        for(int i=0; i<limit+1; i++){
            for(int j=0; j<limit+1; j++){
                if(n-j-i <= limit && n-j-i>=0) cnt++;
            }
        }

        return cnt;
    }
};

class Solution {
private:
    long pow(long x, long n, long mod) {
        long result = 1, p = x % mod;
        while (n) {
            if (n & 1) {
                result = (result * p) % mod;
            }
            p = (p * p) % mod;
            n >>= 1;
        }
        return result;
    }

public:
    int stringCount(int n) {
        long mod = 1e9 + 7;
        return ((
            + pow(26, n, mod)
            - (n + 75) * pow(25, n - 1, mod)
            + (2 * n + 72) * pow(24, n - 1, mod)
            - (n + 23) * pow(23, n - 1, mod)
        ) % mod + mod) % mod;
    }
};

class Solution {
public:
    long long comb(int n)
    {
        return 1ll*n*(n-1)/2;
    }
    long long distributeCandies(int n, int limit) {

        if (n > limit * 3)
        return 0;

        long long res = comb(n+2);

        if (n>limit)
        res -= 3*comb(n-limit+1);
        if(n-2>=2*limit) res+= 3*comb(n-2*limit);

        return res;

    }
};

class Solution {
public:
    vector<string> findHighAccessEmployees(vector<vector<string>>& time) {
        int n=time.size();
        vector<string> ans;
        string flag;

        sort(time.begin(), time.end());
        for(int i=0; i<n-2; i++){
            if(flag!=time[i][0] && time[i][0]==time[i+2][0]){
               int a = stoi(time[i][1]);
               int b = stoi(time[i+2][1]);

               if(b-a<100){
                  flag=time[i][0];
                  ans.push_back(flag);
                  i++;
               }
            }
        }

        return ans;
    }
};

int a[50001][26], b[50001][26];
class Solution {
public:
    bool checkAvailable(int x1, int y1, int x2, int y2, bool flag){
        for(int i = 0; i < 26; i++){
            if(flag && a[y1][i] - a[x1-1][i] < b[y2][i] - b[x2-1][i])
                return false;
            if(!flag && a[y1][i] - a[x1-1][i] > b[y2][i] - b[x2-1][i])
                return false;
        }
        return true;
    }

    bool checkRest(int &x1, int &y1, int &x2, int &y2, set<int> &st){
        int mx = max(y1, y2), mn = min(x1, x2);

        auto it = st.lower_bound(0);
        if(it != st.end() && *it < mn) return false;
        it = st.upper_bound(mx);
        if(it != st.end()) return false;

        if(y1 < x2){
            it = st.upper_bound(y1);
            if(it != st.end() && *it < x2) return false;
        }
        if(y2 < x1){
            it = st.upper_bound(y2);
            if(it != st.end() && *it < x1) return false;
        }
        return true;
    }

    vector<bool> canMakePalindromeQueries(string s, vector<vector<int>>& queries) {
        int n = s.size();
        vector<bool> ans;
        set<int> st;

        for(int i = 0; i < n; i++){
            if(i < n/2){
                for(int j = 0; j < 26; j++) a[i+1][j] = a[i][j];
                a[i+1][s[i]-'a']++;
            }
            else{
                for(int j = 0; j < 26; j++) b[i+1-n/2][j] = b[i-n/2][j];
                b[i+1-n/2][s[n-1-(i-n/2)]-'a']++;
            }

            if(i < n/2 && s[i] != s[n-1-i]) st.insert(i+1);
        }   

        for(int i = 0; i < 26; i++)
            if(a[n/2][i] != b[n/2][i])
                return vector<bool>(queries.size(), false);

        for(auto &i : queries){
            bool val = true;
            int &x1 = i[0], &y1 = i[1], &x2 = i[3], &y2 = i[2];
            x1++, y1++, y2 = n-y2, x2 = n-x2;

            if(!checkRest(x1, y1, x2, y2, st)) val = false;

            if(x1 < x2 && !checkAvailable(x1, y1, x1, min(x2-1, y1), true))
                val = false;
            if(x2 < x1 && !checkAvailable(x2, min(x1-1, y2), x2, y2, false))
                val = false;
            if(y1 < y2 && !checkAvailable(max(y1+1, x2), y2, x2, y2, false))
                val = false;
            if(y2 < y1 && !checkAvailable(x1, y1, max(y2+1, x1), y1, true))
                val = false;

            ans.push_back(val);
        }
        return ans;
    }
};

class Solution {
public:
    int findMinimumOperations(string s1, string s2, string s3) {
        int i=0;
        while(i<s1.length() && i<s2.length() && i<s3.length() && s1[i]==s2[i] && s1[i]==s3[i]){
            i++;
        }
        if(i==0) return -1;
        int total=s1.length()+s2.length()+s3.length()-3*i;
        return total;
    }
};

class Solution {
    using ll = long long;
    const int AEIOU_MASK = 0x104111;
    int p_sqrt(int n) {
        int res = 1;
        for (int i = 2; i * i <= n; ++i) {
            int i2 = i * i;
            while (n % i2 == 0) {
                res *= i;
                n /= i2;
            }
            if (n % i == 0) {
                res *= i;
                n /= i;
            }
        }
        n > 1 ? res *= n : 0;
        return res;
    }

public:
    long long beautifulSubstrings(string s, int k) {
        int n = s.length(), sum = n;
        ll ans = 0;
        unordered_map<int, int> cnt;
        k = p_sqrt(k * 4);
        cout << k << endl;
        ++cnt[(k - 1) << 17 | sum]; // add (k - 1, sum)

        for (int i = 0; i < n; ++i) {
            int bit = (AEIOU_MASK >> (s[i] - 'a')) & 1;
            sum += bit * 2 - 1; // 1 -> 1    0 -> -1
            ans += cnt[(i % k) << 17 | sum]++;
        }
        return ans;
    }
};

