class Solution {
public:
    int minimumCoins(vector<int>& prices) 
    {
        ios::sync_with_stdio(false); cin.tie(0);
        int n = prices.size();
        vector<int> dp(n+1, INT_MAX);
        dp[n-1] = prices[n-1];
        for (int i = n-2; i >= 0; i --)
        {
            for (int j = i+1; j <= min(n, 2*i+2); j++)
            {
                if (j == n) dp[i] = prices[i];
                else dp[i] = min(dp[i], prices[i] + dp[j]);
            }
        }
        return dp[0];
    }
};

class Solution {
public:

    bool isVowel(char &ch) {
        return (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u');
    }

    int beautifulSubstrings(string s, int k) {

        /*
            -> if we find sum again means in the substring from prevIndex to current Index,
               no. of vowels = no. of consonants.
            -> the no. of vowels = no. of consonamts = lenght / 2 
        */

        int n = s.size();
        unordered_map<long long, vector<int>> prefix;
        prefix[0].push_back(-1);

        long long cnt = 0;
        long long sum = 0;

        for (int i = 0; i < n; i++) {

            if (isVowel(s[i]))
                sum++;
            else
                sum--;

            if(prefix.find(sum) != prefix.end()) {
                for(auto &prevIndex: prefix[sum]) {
                    long long count = (i - prevIndex) / 2;

                    if((count * count) % k == 0)
                        cnt++;
                }
            }

            prefix[sum].push_back(i);
        }

        return cnt;
    }
};

class Solution {
public:
    int findMaximumLength(vector<int>& nums) {
        int n = nums.size();
        int f[n + 1];
        int pre[n + 2];
        long long s[n + 1];
        for (int i = 0; i < n; ++i) {
            s[i + 1] = s[i] + nums[i];
        }
        memset(f, 0, sizeof(f));
        memset(pre, 0, sizeof(pre));
        for (int i = 1; i <= n; ++i) {
            pre[i] = max(pre[i], pre[i - 1]);
            f[i] = f[pre[i]] + 1;
            int j = lower_bound(s, s + n + 1, s[i] * 2 - s[pre[i]]) - s;
            pre[j] = i;
        }
        return f[n];
    }
};

