class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {

        int maxElement = *max_element(nums.begin(), nums.end());
        int count = 0;
        long long result = 0;

        int left = 0;
        int right = 0;

        for(int right = 0; right < nums.size(); right++){
            if (nums[right] == maxElement) {
                count++;
            }


            while (count >= k) {
                result += nums.size() - right;
                if (nums[left] == maxElement) {
                    count--;
                }left++;
            }


        }

        return result;
    }
};

class Solution {
public:
    int maximizeSquareHoleArea(int n, int m, vector<int>& h, vector<int>& v) {
        int ans, L = 2, R = 2, maxL = 2, maxR = 2;
        sort(h.begin(), h.end());
        sort(v.begin(), v.end());
        for(int i = 0; i < h.size() - 1; i++){
            if(h[i] == h[i + 1] - 1){
                L++;
            }
            else{
                maxL = max(L, maxL);
                L = 2;
            }
        }
        maxL = max(L, maxL);
        for(int i = 0; i < v.size() - 1; i++){
            if(v[i] == v[i + 1] - 1){
                R++;
            }
            else{
                maxR = max(R, maxR);
                R = 2;
            }
        }
        maxR = max(R, maxR);
        return min(maxL, maxR) * min(maxL, maxR);
    }
};

class Solution {
public:
    bool areSimilar(vector<vector<int>>& mat, int k) {
        int n = mat.size(), m = mat[0].size();
        k %= m;
        for (int i = 0; i < n; i++) {
            int shift = i % 2 == 0 ? k : -k;
            for (int j = 0; j < m; j++) {
                if (mat[i][j] != mat[i][(j+shift+m) % m]) return false;
            }
        }
        return true;
    }
};

using i64 = long long;

constexpr int MAX = 20010;

int cnt[MAX];
i64 c[MAX], dp[MAX][2][4], buf[8];
vector<int> adj[MAX];

void Combine(const i64* a, const i64* b, i64* c) {
  std::copy(a, a + 3, buf);
  std::copy(b, b + 3, buf + 3);
  std::sort(buf, buf + 6, std::greater<i64>());
  std::copy(buf, buf + 3, c);
}

void DFS(int x, int p) {
  cnt[x] = 1;
  dp[x][0][0] = c[x] < 0 ? -1 : c[x];
  dp[x][0][1] = -1;
  dp[x][0][2] = -1;
  dp[x][1][0] = c[x] < 0 ? -c[x] : -1;
  dp[x][1][1] = -1;
  dp[x][1][2] = -1;
  for (int y : adj[x]) {
    if (y == p) {
      continue;
    }
    DFS(y, x);
    cnt[x] += cnt[y];
    Combine(dp[x][0], dp[y][0], dp[x][0]);
    Combine(dp[x][1], dp[y][1], dp[x][1]);
  }
}

class Solution {
public:
    vector<long long> placedCoins(vector<vector<int>>& edges, vector<int>& cost) {
      int n = cost.size();
      for (int i = 0; i < n; ++i) {
        c[i] = cost[i];
        std::vector<int>().swap(adj[i]);
      }
      for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
      }
      DFS(0, -1);
      std::vector<i64> ret(n);
      for (int i = 0; i < n; ++i) {
        if (cnt[i] < 3) {
          ret[i] = 1;
        } else {
          ret[i] = 0;
          if (dp[i][0][2] > 0) {
            ret[i] = std::max(ret[i], dp[i][0][0] * dp[i][0][1] * dp[i][0][2]);
          }
          if (dp[i][0][0] > 0 && dp[i][1][1] > 0) {
            ret[i] = std::max(ret[i], dp[i][0][0] * dp[i][1][0] * dp[i][1][1]);
          }
        }
      }
      return ret;
    }
};

class Solution {
public:
    vector<int> lexicographicallySmallestArray(vector<int>& nums, int limit) {
        // Create array of indexes and sort it based on values from nums
        vector<int> indexes(nums.size());
        iota(indexes.begin(), indexes.end(), 0);
        sort(indexes.begin(), indexes.end(), [&](auto a, auto b) {
            return nums[a] < nums[b];
        });

        // Subset of numbers which has difference between adjacent pairs <= limit
        vector<int> subset;
        subset.reserve(nums.size());
        subset.push_back(nums[indexes[0]]);
        for (int lo = 0, hi = 1; hi <= indexes.size(); hi++) {
            // Check if we reached to end of the subset. 
            if (hi == indexes.size() || nums[indexes[hi]] - nums[indexes[hi-1]] > limit) {
                // Now we want to sort indexes in range lo-hi in decreasing order
                // After that we can change elements in nums which are in same subset by setting highest element from subset to highest index from subset
                sort(begin(indexes) + lo, begin(indexes) + hi, greater<int>());
                for (int i = lo; i < hi; i++) {
                    nums[indexes[i]] = subset.back();
                    subset.pop_back();
                }
                lo = hi;
            }
            if (hi < indexes.size())
                subset.push_back(nums[indexes[hi]]);
        }

        return nums;
    }
};

