class Solution {
public:

    int solve(int start,int end,string &word,int k){
        int result=0;
        for(int unique_char=1;unique_char*k<=end-start+1 && unique_char<=26;unique_char++){
             vector<int>mp(26,0);
             int goodboy=0;
             int windowL=unique_char*k;
             int i=start;
             for(int j=start;j<=end;j++){
                 char ch=word[j];
                 mp[ch-'a']++;
                 if(mp[ch-'a']==k){
                    goodboy+=1;
                 }
                 else if(mp[ch-'a']==k+1){
                    goodboy-=1;
                 }
                 if((j-i+1)>windowL){
                    if(mp[word[i]-'a']==k){
                        goodboy-=1;
                    }
                    if(mp[word[i]-'a']==k+1){
                        goodboy+=1;
                    }
                    mp[word[i]-'a']--;
                    i++;

                 }
                if(goodboy==unique_char){
                result++;
             }
             }

        }
        return result;
    }
    int countCompleteSubstrings(string word, int k) {
         int n=word.size();
         int result=0;
         int last=0;
         for(int i=1;i<=n;i++){
             if(abs(word[i]-word[i-1]) > 2){
            result+=solve(last,i-1,word,k);
            last=i;
             }
         }
         return result;

    }
};

constexpr int m = 100000;
long long fact[m+1], inv_fact[m+1], mod = 1000000007;
bool init = false;
class Solution {
    // Time complexity O(slogm); Memory complexity O(m);
public:
    int numberOfSequence(int n, vector<int>& sick) {
        // (sum(segments))!/(multiply(for each segments!)) * 2 ^ (sum(segments)-len(segments));
        if (!init) {
            init = fact[0] = 1;
            // we only need modular factorials and inverse factorials up to mx inclusive:
            for (int i=1;i<=m;i++) 
                fact[i] = i * fact[i-1] % mod;
            // FLT: a^(p-1)%p = 1
            // a * a^(p-2)%p = a^-1
            // thus:
            // a * a^(p-2) = a^(p-1) * a^-1 = 1 * a^(-1) (mod p)
            // a^-1 = a^(p-2)
            inv_fact[m] = modPow(fact[m], mod - 2, mod);
            for (int i=m-1;i>=0;i--) {
                inv_fact[i] = inv_fact[i+1] * (i+1) % mod;
            }
        }
        long long res = 1;
        res = (res * inv_fact[sick[0]]) % mod;
        res = (res * inv_fact[n-sick.back()-1]) % mod;
        for (int i = 1;i<sick.size();i++) {
            int dist = sick[i] - sick[i-1]-1;
            if (dist == 0)
                continue;
            res = (res * modPow(2, dist-1, mod)) % mod;
            res = (res * inv_fact[dist]) % mod;
        }
        return (res * fact[n-sick.size()]) % mod;
    }
private:
    int modPow(int x, int y, int mod) {
        if (y == 0)
            return 1;
        long p = modPow(x,y/2,mod)%mod;
        p = (p*p)% mod;
        return y%2 ? (p*x) % mod : p;
    }
    long long binom_coeff(int n, int k) {
        return max(1LL, fact[n] * inv_fact[k] % mod * inv_fact[n-k] % mod);
    }
};

class Solution 
{
public:
  int maxSubarrayLength(vector<int>& nums, int k) 
  {
    int n = nums.size();
    unordered_map<int, int> m; m.reserve(n);

    int bads = 0, r = 0, i = 0, j = 0;
    //while (i+r<n)
    for (;;)
    {
      while (j<n && bads==0)
      {
        int x = nums[j++];
        if (k+1 == ++m[x]) bads++;
        else r = max(r, j-i);
      }
      if (i+r>=n) break;
      int x = nums[i++];
      if (k == --m[x]) bads--;
    }
    return r;      
  }
};

