class Solution {
public:
    vector<int> findMissingAndRepeatedValues(vector<vector<int>>& grid) {
        int n = grid.size();
        vector<int> hash(n * n + 1, 0); // Correctly initializing the hash vector

        // Filling the hash array by iterating over all elements of the 2D grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < grid[i].size(); j++) {
                hash[grid[i][j]]++;
            }
        }

        int repeating = -1;
        int missing = -1;

        // The loop should go from 1 to n * n because the numbers are expected to be within this range
        for (int i = 1; i <= n * n; i++) { // Corrected loop range
            if (hash[i] == 2) {
                repeating = i; // Find the repeating element
            }
            if (hash[i] == 0) {
                missing = i; // Find the missing element
            }
        }

        // Return a 0-indexed array with the repeating and missing values
        return {repeating, missing};
    }
};

class Solution {
  public:
    int maximumSetSize(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();

        ranges::sort(nums1);
        ranges::sort(nums2);

        auto [s1, e1] = ranges::unique(nums1);
        int remove_cnt1 = min(n / 2, (int)ranges::distance(s1, e1));
        // 0
        nums1.erase(s1, e1);

        auto [s2, e2] = ranges::unique(nums2);
        int remove_cnt2 = min(n / 2, (int)ranges::distance(s2, e2));
        // 3
        nums2.erase(s2, e2);

        vector<int> intersection;
        // 2
        ranges::set_intersection(nums1, nums2, std::back_inserter(intersection));

        // [1,2,3,4,5,6]
        // [2,3,2,3,2,3]
        int last = n - (remove_cnt1 + remove_cnt2);
        if (last > intersection.size()) {
            return nums1.size() + nums2.size() - last;
        } else {
            return nums1.size() + nums2.size() - intersection.size();
        }
        // 3 - 1 + 2
    }
};

