class Solution {
public:
    ll minimumCost(vector<int>& nums) {
        sort(nums.begin(), nums.end());

        const int SIZE = nums.size();
        int median = SIZE & 1
            ? nums[SIZE / 2]
            : (nums[SIZE / 2] + nums[SIZE / 2 - 1]) / 2
        ;

        const string as_str = to_string(median);
        const int LEN = as_str.length();
        int n = calculate_palindrome_number(as_str);

        ll vars[5] = {
            nPalindrome(LEN, n),
            nPalindrome(LEN, n + 1),
            nPalindrome(LEN, n - 1),
            nPalindrome(LEN + 1, 0),
            stoll(string(max(1, LEN - 1), '9'))
        };

        ll results[5] = {0};
        for(int n : nums){
            for(int i = 0; i < 5; ++i){
                if(vars[i] == -1){
                    results[i] = -1;
                    continue;
                }
                results[i] += abs(vars[i] - n);
            }
        }

        ll result = LLONG_MAX;
        for(int i = 0; i < 5; ++i){
            if(results[i] == -1)continue;
            result = min(result, results[i]);
        }
        return result;
    }

private:
    //calculates the number of the closest palindrome
    int calculate_palindrome_number(string number){
        const int LEN = number.length(); 
        const int HALF = (LEN - 1) / 2;

        int n = 0;
        int mult = pow(10, HALF);

        for(int i = 0; i <= HALF; ++i){
            n += (number[i] - (i == 0 ? '1' : '0')) * mult;
            mult /= 10;
        }

        return n;
    }

    ll nPalindrome(int length, int n){
        int mult = pow(10, (length + 1) / 2 - 1);
        if(n != 0 && (n / mult > 8 || n < 0))return -1;

        string str(length, '0');
        str[0] = str[length - 1] = '1';

        int l = 0, r = length - 1;
        while(l <= r){
            str[r--] = str[l++] += (n / mult) % 10;
            mult /= 10; 
        }

        return stoll(str);
    }
};

