class Solution {
public:
    int removeAlmostEqualCharacters(string word) 
    {
        int n = word.size(), res = 0;
        for (int i = 0; i < n-1; i++)
        {
            if (abs(word[i] - word[i+1]) <= 1)
            {
                res ++;
                i = i+1;
            }
        }
        return res;
    }
};

class Solution {
public:
    int minimumAddedCoins(vector<int>& coins, int target) {
        ios_base::sync_with_stdio(0);cin.tie(NULL);
        int n = coins.size();
        sort(coins.begin(),coins.end());
        int answer=0;
        int maxunobt=1;
        int i=0;
        while(i<n){
            if(maxunobt>target)break;
            if(coins[i]>maxunobt){
                answer++;
                maxunobt=maxunobt*2;
            }
            else if(coins[i]==maxunobt){
                i++;
                maxunobt*=2;
            }
            else{
                maxunobt+=coins[i];
                i++;
            }
        }
        while(maxunobt<=target){
            answer++;
            maxunobt*=2;
        }

        return answer; 
    }
};

