// prefix sum, greedy
class Solution {
public:
    int maxPartitionsAfterOperations(string s, int k) {
        vector<int> left(size(s) + 1);
        vector<int> left_mask(size(s) + 1);
        for (int i = 0, cnt = 0, mask = 0; i < size(s); ++i) {
            mask |= 1 << (s[i] - 'a');
            if (__builtin_popcount(mask) > k) {
                ++cnt;
                mask = 1 << (s[i] - 'a');
            }
            left[i + 1] = cnt;
            left_mask[i + 1] = mask;
        }
        vector<int> right(size(s) + 1);
        vector<int> right_mask(size(s) + 1);
        for (int i = size(s) - 1, cnt = 0, mask = 0; i >= 0; --i) {
            mask |= 1 << (s[i] - 'a');
            if (__builtin_popcount(mask) > k) {
                ++cnt;
                mask = 1 << (s[i] - 'a');
            }
            right[i] = cnt;
            right_mask[i] = mask;
        }

        int result = 0;
        for (int i = 0; i < size(s); ++i) {
            int curr = left[i] + right[i + 1];
            const int mask = left_mask[i] | right_mask[i + 1];
            if (__builtin_popcount(left_mask[i]) == k && __builtin_popcount(right_mask[i + 1]) == k && __builtin_popcount(mask) != 26) {
                curr += 3;
            } else if (__builtin_popcount(mask) + (__builtin_popcount(mask) != 26 ? 1 : 0) > k) {  // test case: s = "abcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyz", k = 26
                curr += 2;
            } else {
                curr += 1;
            }
            result = max(result, curr);
        }
        return result;
    }
};

class Solution {
    int mod_pow(int a, int p, int mod) {
        int result{1};
        for (; p; p >>= 1, (a *= a) %= mod) {
            if (p & 1) { (result *= a) %= mod; }
        }
        return result;
    }

public:
    vector<int> getGoodIndices(vector<vector<int>> & variables, int target) {
        vector<int> result;
        for (size_t i = 0; i < variables.size(); ++i) {
            const auto & v = variables[i];
            if (target == mod_pow(mod_pow(v[0], v[1], 10), v[2], v[3])) { result.push_back(i); }
        }
        return result;
    }
};

constexpr int MAX = 0x10000000;
struct Solution {
    constexpr inline long minimumCost(string_view src, string_view trg, const vector<char>& og,
                     const vector<char>& chg, const vector<int>& cost) const {
        long output = 0;
        int price, *tmp;
        array<array<int, 26>, 26> data;
        for (int i = 0; i < 26; ++i) {
            for (int j = 0; j < 26; ++j)
                data[i][j] = i == j ? 0 : MAX;
        }
        for (int i = 0; i < og.size(); ++i) {
            tmp = &data[og[i] - 'a'][chg[i] - 'a'];
            if (cost[i] < *tmp)
                *tmp = cost[i];
        }
        for (int i = 0; i < 26; ++i) {
            for (int j = 0; j < 26; ++j) {
                if (i != j and data[i][j] != MAX) {
                    for (int k = 0; k < 26; ++k) {
                        price = data[k][i] + data[i][j];
                        if (price < data[k][j])
                            data[k][j] = price;
                    }
                }
            }
        }
        for (int i = 0; i < src.length(); ++i) {
            price = data[src[i] - 'a'][trg[i] - 'a'];
            if (price == MAX)
                return -1;
            output += price;
        }
        return output;
    }
};

