class Solution {
public:
    int missingInteger(vector<int>& nums) {
        unordered_set<int> set(nums.begin(), nums.end());
        int sum = nums[0];
        for (int i = 1; i < nums.size(); i++) {
            if (nums[i] == nums[i - 1] + 1) {
                sum += nums[i];
            } else {
                break;
            }
        }
        for (int i = sum;; i++) {
            if (!set.count(i))
                return i;
        }
    }
};

long d[201][201];
long dp[1001];
struct TrieNode {
    array <TrieNode *, 26> children;
    int id = -1;
    void init() {
        id = -1;
        for (auto &x : children)
            x = NULL;
    }
} all[26 << 10];
// Pre-allocate Nodes!

class Solution {
public:
    long dfs(int i, string &s, string &t) {
        if (i == s.size())
            return 0; // base
        if (dp[i] != -1)
            return dp[i]; // memo

        long ret = s[i] == t[i] ? dfs(i + 1, s, t) : inf;
        TrieNode *l = root;
        TrieNode *r = root;

        for (int j = i; j < s.size(); j++) {
            // Trie move
            advance(l, s[j]);
            advance(r, t[j]);
            if (l == NULL || r == NULL)
                break ; // none matches to be found further

            if (l->id == -1 || r->id == -1)
                continue ; // not a word yet

            int x = l->id;
            int y = r->id;
            if (d[x][y] == inf)
                continue ; // no conversion

            ret = min(ret, d[x][y] + dfs(j + 1, s, t));
        }
        return dp[i] = ret;
    }
    // main
    long long minimumCost(string s, string t, vector<string>& a,  vector<string>& b, vector<int>& c) {
        init(a, b, c); 
        memset(dp, -1, sizeof(long) * s.size());
        long ret = dfs(0, s, t);
        return ret == inf ? -1 : ret;
    }


private:
    TrieNode *root;
    long inf = 1e3 * 1e6 * 100;
    void advance(TrieNode *&cur, char c) {
        auto &m = cur->children;
        int n = c - 'a';
        cur = m[n];
    }
    int M = 0;
    void add(TrieNode *cur, string &s, int id) {
        for (auto c : s) {
            auto &m = cur->children;
            int n = c - 'a';
            if (m[n] == NULL) {
                m[n] = all + M++;
                m[n]->init();
            }
            cur = m[n];
        }
        cur->id = id;
    }
    void init( vector<string>& a, vector<string>& b, vector<int>& c) {
        unordered_map <int, vector <int>> sz;
        unordered_map <string, int> ids;
        int m = a.size();
        int K = 0;
        for (int i = 0; i < m; i++) {
            if (ids.find(a[i]) == ids.end()) {
                sz[a[i].size()].push_back(K);
                ids[a[i]] = K++;
            }
            if (ids.find(b[i]) == ids.end()) {
                sz[a[i].size()].push_back(K);
                ids[b[i]] = K++;
            }
        }

        for (int i = 0; i < K; i++) 
            for (int j = 0; j < K; j++) 
                d[i][j] = inf;

        root = new TrieNode();
        for (int i = 0; i < m; i++) {
            int x = ids[a[i]];
            int y = ids[b[i]];

            add(root, a[i], x);
            add(root, b[i], y);

            d[x][y] = min(d[x][y], (long)c[i]);
        }

        // Floyd
        for (auto &[key, lst] : sz)
        for (auto k : lst)
        for (auto i : lst)
        if (d[i][k] != inf)
        for (auto j : lst)
            d[i][j] = min(d[i][j], d[i][k] + d[k][j]);

    }
};

class Solution {
public:
int vis[10020];
    int minimumOperationsToMakeEqual(int x, int y) {
        memset(vis,0,sizeof(vis));
        if(y>=x)return y-x;
        queue<int> bfs;
        bfs.push(x);
        vis[x]=true;
        int ans=0;
        while(!bfs.empty()){
            int size=bfs.size();
            while(size--){
                int curr=bfs.front();
                bfs.pop();
                if(curr==y)return ans;
                if(curr%5==0 && !vis[curr/5]){
                    vis[curr/5]=1, bfs.push(curr/5);
                }
                if(curr%11==0 && !vis[curr/11]){
                    vis[curr/11]=1, bfs.push(curr/11);
                }
                if(curr+1 > x){
                    if(curr+1-x<=11 && !vis[curr+1])vis[curr+1]=1, bfs.push(curr+1);
                }
                else{
                    if(!vis[curr+1])vis[curr+1]=1, bfs.push(curr+1);
                }
                if(curr-1>=0 && !vis[curr-1]){
                    vis[curr-1]=1, bfs.push(curr-1);
                }
            }
            ans++;
        }
        return ans;
    }
};

#define ll long long
class Solution 
{
public:
    ll findMaximumNumber(ll k, int x) 
    {
        ios::sync_with_stdio(false); cin.tie(0);

        ll left = 1, right = 1e15;
        while (left <= right)
        {
            ll mid = (left+right)/2;
            if (solve(mid, x) <= k) left = mid+1;
            else right = mid-1;
        }
        return right;
    }
private:
    ll power2(int i)
    {
        return 1LL << i;
    }
    ll solve(ll num, int x)
    {
        int len = 0;
        ll tmp = num;
        while (tmp)
        {
            tmp = tmp >> 1;
            len++;
        }
        len -= (len%x);
        ll res = 0;
        num++;
        while (len > 0)
        {
            res += (num/power2(len)) * power2(len-1) + max(0LL, (num%power2(len)) - power2(len-1));
            len -= x;
        }   
        return res;
    }
};

