class Solution {
public:
    vector<vector<int>> divideArray(vector<int>& nums, int k) {
        int size = nums.size();
        sort(nums.begin(), nums.end());
        vector<vector<int>> result(size / 3);
        for (int i = 0; i < size / 3; i++) {
            if (nums[3 * i + 2] - nums[3 * i] <= k) {
                result[i] = {nums[3 * i], nums[3 * i + 1], nums[3 * i + 2]};
            } else {
                return {};
            }
        }
        return result;
    }
};
