class Solution {
public:
    int maxFrequencyElements(vector<int>& nums) {
        int result = 0;

        int max_frequency = 0;
        unordered_map<int, int> frequency;
        for (int num : nums) {
            frequency[num]++;

            int freq = frequency[num];
            if (freq > max_frequency) {
                result = freq;
                max_frequency = freq;
            } else if (freq == max_frequency) {
                result += freq;
            }
        }

        return result;
    }
};

typedef long long ll;
class Solution {
public:
	// index, tight
    ll dp[16][2]; 

    ll f(int index, bool tight, int& maxAllowed, string &suffix, string &s){
        // Base case : index out of bound
        if(index == s.size()) 
			return 1;

        // already calculated
        if(dp[index][tight] != -1)
            return dp[index][tight];

		ll ans = 0;
        // calculate limit for current index 
        int limit = tight ? s[index] - '0' : 9;
        limit = min(limit, maxAllowed);

        int suffixIndex = s.size() - suffix.size();
        // two cases :
        // 1. Index in suffix range - special handling
        if(index >= suffixIndex) {
            // tight 0 ==> we can fill remaining places with suffix values and create matching suffix
            if(tight == false)      
                return dp[index][tight] = 1;

            // number suffix < required suffix -> can't create matching suffix
            if(s[index] < suffix[index - suffixIndex]) 
                return dp[index][tight] = 0;

            // number suffix == required suffix -> can fill this index, check for others
            if(s[index] == suffix[index - suffixIndex]) 
                return dp[index][tight] = f(index + 1, true, maxAllowed, suffix, s);

            // number suffix > required suffix -> can create matching suffix
            if(s[index] > suffix[index - suffixIndex])
                return dp[index][tight] = 1;
        }

        // 2. Index not in suffix range - normal digit dp
        for(int d = 0; d <= limit; d++) {
            int newTight = tight & (d == s[index] - '0');
            ans += f(index + 1, newTight, maxAllowed, suffix, s);
        }

        return dp[index][tight] = ans;
    }

    long long numberOfPowerfulInt(long long start, long long finish, int maxAllowed, string suffix) {
        // find answer from 1 to low-1
        ll countNum1 = 0;
        string l = to_string(start - 1);
        if(l.size() >= suffix.size()) {
            memset(dp, -1, sizeof(dp));
            countNum1 = f(0, true, maxAllowed, suffix, l);
        }

		// find answer from 1 to high
        string h = to_string(finish);
        memset(dp, -1LL, sizeof(dp));
        ll countNum2 = f(0, true, maxAllowed, suffix, h); 

        return countNum2 - countNum1;
    }
};

class Solution {
public:
    int minimumArrayLength(vector<int>& nums) {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);
        cout.tie(nullptr);
        int min_v = INT_MAX;
        for (int i = 0; i < nums.size(); i++) {
            min_v = min(min_v, nums[i]);
        } 
        int cnt = count(nums.begin(), nums.end(), min_v);  
        for (int i = 0; i < nums.size(); i++) {
            if (nums[i] % min_v != 0) {
                return 1;
            }
        }
        return (cnt+1)/2;
    }
};

class Solution {
public:
    vector<int> beautifulIndices(string s, string a, string b, int k) {
        vector<int> idx{};
        for(int index = s.find(b, 0); index!=string::npos; index = s.find(b, index+1)){
            idx.push_back(index);
        }
        vector<int> result{};
        for(int index = s.find(a, 0); index!=string::npos; index = s.find(a, index+1)){
            auto pos = lower_bound(idx.begin(), idx.end(), index-k);
            if(pos==idx.end()) continue;
            int index2 = pos-idx.begin();
            if(abs(index-idx[index2])<=k) result.push_back(index);
        }
        return result;
    }
};

class Solution {
public:
    bool hasTrailingZeros(vector<int>& nums) {
        const int n = nums.size();
        for(int i = 0; i < n;i ++){
            for(int j = i + 1; j < n; j++){
                int k = nums[i]|nums[j];
                if((k & 1)==0) return true;
            }
        }
        return false;
    }
};

class Solution {
public:
    long long incremovableSubarrayCount(vector<int>& nums) {
        ios::sync_with_stdio(false); cin.tie(nullptr);
        bool sorted = true;
        for(int i = 0; i < nums.size()-1; i++) if(nums[i] >= nums[i+1]) sorted = false;
        if(sorted) return (nums.size() * (nums.size()+1))/2;

        int l = 0, r = nums.size()-1;
        while(r > 0 && nums[r-1] < nums[r]) r--;
        long long ans = nums.size()-r+1;

        while(l < nums.size() && (l == 0 || nums[l-1] < nums[l])){
            while(r < nums.size() && nums[l] >= nums[r]) r++;
            ans += nums.size()-r+1;
            l++;
        }
        return ans;
    }
};

class Solution {
public:
    int maximizeSquareArea(int m, int n, vector<int>& hFences, vector<int>& vFences) {
        constexpr long MOD = 1'000'000'007;
        auto calcSides =
            [](const std::vector<int> &fences, int max_side) -> std::priority_queue<int>
        {
            const int fs = static_cast<int>(fences.size());
            std::priority_queue<int> sides;
            for (int i = 0; i < fs - 1; ++i)
                for (int j = i + 1; j < fs; ++j)
                    if (int side = std::abs(fences[j] - fences[i]); side <= max_side)
                        sides.emplace(side);
            return sides;
        };
        if (m == n)
            return static_cast<int>(static_cast<long>(m - 1) * (n - 1) % MOD);
        hFences.push_back(1);
        hFences.push_back(m);
        vFences.push_back(1);
        vFences.push_back(n);
        std::priority_queue<int> h_sides = calcSides(hFences, std::min(m, n) - 1),
                                v_sides = calcSides(vFences, std::min(m, n) - 1);
        while (!h_sides.empty() && !v_sides.empty())
        {
            long h_top = h_sides.top(), v_top = v_sides.top();
            if (h_top == v_top)
                return static_cast<int>(h_top * v_top % MOD);
            if (h_top > v_top) h_sides.pop();
            else v_sides.pop();
        }
        return -1;
    }
};

class Solution {
public:
    int incremovableSubarrayCount(vector<int>& nums) {
        // Using Binary search optimal and goto approach
        ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);

        // Initialize variables
        int n = nums.size(), j = n - 1;

        // Find the rightmost index from where the array is not in increasing order upto end
        while (j > 0 and nums[j - 1] < nums[j]) j--;

        // If the entire array is in increasing order, return the total count of subarrays
        if (j == 0) return (n * (n + 1)) / 2;

        // Initialize variables for the final answer calculation
        int ans = n - j + 1, last = -1; 

        // Iterate through the array and count removable subarrays
        for (int i = 0; nums[i] > last; last = nums[i], i++)
            ans += n - (int)(upper_bound(nums.begin() + j, nums.end(), nums[i]) - nums.begin()) + 1;

        // Return the final count of increasing removable subarrays
        return ans;
    }
};

