class Solution {
public:
    int minimumCost(vector<int>& nums) {
        int ans = nums[0];
        int min1 = nums[1], idx = 1;
        for (int i = 1; i < nums.size(); i++) {
            if (nums[i] < min1) {
                min1 = nums[i];
                idx = i;
            }
        }
        int min2 = nums[1];
        if (idx == 1) min2 = nums[2];
        for (int i = 1; i < nums.size(); i++) {
            if (i == idx) continue;
            if (nums[i] < min2) {
                min2 = nums[i];
            }
        }
        return ans + min1 + min2;
    }
};

