class Solution {
public:
    long long maximumSubarraySum(vector<int>& nums, int k) {
        long long ans=LLONG_MIN,sum=0;
        unordered_map<int,long long>map;
        int n=nums.size();
        for(int i=0; i<n; i++){
            if(map.find(nums[i])==map.end() || sum<map[nums[i]]) map[nums[i]]=sum;
            sum+=nums[i];
            if(map.find(nums[i]-k) != map.end()) ans= max(ans, sum-map[nums[i]-k]);
            if(map.find(nums[i]+k) != map.end()) ans= max(ans, sum-map[nums[i]+k]);
        }
        return ans==LLONG_MIN ? 0:ans;
    }
};

class Solution {
public:
    int maximumLength(string s) {
        std::ios_base::sync_with_stdio(0);

        int n = s.length();
        int ans = 0;
        vector<vector<int>> vec(26, vector<int>(3, 0));

        for (int i = 0; i < n;) {
            int& m0 = vec[s[i] - 'a'][0];
            int& m1 = vec[s[i] - 'a'][1];
            int& m2 = vec[s[i] - 'a'][2];

            int cnt = 0;
            int j = i;
            for (; j < n && s[i] == s[j]; j++) {
                cnt++;

                if (cnt > m2) {
                    m0 = m1;
                    m1 = m2;
                    m2 = cnt;
                } else if (cnt > m1) {
                    m0 = m1;
                    m1 = cnt;
                } else if (cnt > m0) {
                    m0 = cnt;
                }
            }

            i = j;
            ans = max(ans, m0);
        }

        return ans == 0 ? -1 : ans;
    }
};

class Solution {
public:
    int maximumLength(string s) {
        int n = s.size();
        int left = 1, right = n;
        int result = -1;

        auto check = [&](int length) -> bool {
            vector<int> count(26, 0);
            int i = 0;
            while (i < n) {
                int j = i;
                while (j < n && s[j] == s[i]) {
                    j++;
                }
                int seq_len = j - i;
                if (seq_len >= length) {
                    count[s[i] - 'a'] += (seq_len - length + 1);
                }
                i = j;
            }

            for (int c : count) {
                if (c >= 3) return true;
            }
            return false;
        };

        while (left <= right) {
            int mid = (left + right) / 2;
            if (check(mid)) {
                result = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return result;
    }
};

class Solution {
public:
    int countMatchingSubarrays(vector<int>& nums, vector<int>& p) {
        int n = nums.size();
        int m = p.size();
        int cnt = 0;

        for(int i=0; i<n-m; i++){
            int c = 1;
            for(int j=0; j<m; j++){
                if((p[j]==1 && nums[i+j+1]>nums[i+j])
                   ||(p[j]==0 && nums[i+j+1]==nums[i+j])
                   ||(p[j]==-1 && nums[i+j+1]<nums[i+j])){
                    c++;
                }
                else break;
            }
            if(c==m+1) cnt++;
        }
        return cnt;
    }
};

class Solution {
public:
    // time/space: O(1)/O(1)
    int minMovesToCaptureTheQueen(int yRook, int xRook, int yBishop, int xBishop, int yQueen, int xQueen) {
        // try to move the rook in 1 step
        if (xRook == xQueen) {
            // check if the bishop is block the vertical way
            if ((xRook == xBishop) && 
                (((yRook < yBishop) && (yBishop < yQueen)) ||
                ((yQueen < yBishop) && (yBishop < yRook)))) {}
            else return 1;
        }
        if (yRook == yQueen) {
            // check if the bishop is block the horizontal way
            if ((yRook == yBishop) && 
                (((xRook < xBishop) && (xBishop < xQueen)) ||
                ((xQueen < xBishop) && (xBishop < xRook)))) {}
            else return 1;
        }

        // try to move the bishop in 1 step
        int dxQ2B = xQueen - xBishop;
        int dyQ2B = yQueen - yBishop;
        if (abs(dxQ2B) == abs(dyQ2B)) {
            int dxR2B = xRook - xBishop;
            int dyR2B = yRook - yBishop;
            // check if the rock is block the bishop's way
            if (isSameSlope(dxQ2B, dyQ2B, dxR2B, dyR2B) &&
                isSameDirection(dxQ2B, dyQ2B, dxR2B, dyR2B) &&
                (abs(dxQ2B) > abs(dxR2B)) &&
                (abs(dyQ2B) > abs(dyR2B))) {}
            else return 1;
        }

        return 2;
    }
private:
    bool isSameSlope(int dx1, int dy1, int dx2, int dy2) {
        return ((dx1 * dy2) == (dx2 * dy1));
    }
    bool isSameDirection(int dx1, int dy1, int dx2, int dy2) {
        if ((dx1 * dx2) < 0) return false;
        if ((dy1 * dy2) < 0) return false;
        return true;
    }
};

class Solution {
public:
    vector<int> countOfPairs(int n, int x, int y) 
    {
        vector<int> ans(n, 0);

        if(x>y)
            swap(x, y);

        for(int i=1;i<=n;i++)
        {
            for(int j=1;j<i;j++)
            {
                int ways = i-j;

                ways = min(ways, abs(j-x) + 1 + abs(y-i));


                    ans[ways-1]+=2;
            }
        }

        return ans;
    }
};

class Solution {
public:
    int minimumPushes(string word) {
        int n = word.size();
        if(n <= 8)return n;
        if(n <= 16) return (n-8) * 2 + 8;
        if(n <= 24) return (n-8) * 3 ;

        if(n == 25)return 52;
        return 56;
    }
};
