struct Solution {
    int minimumPushes(string_view input) {
        int i = 0;
        int j;

        array<int, 26> data;
        for (const char c : input)
            if (96 < c && c < 123)
                ++data[c - 'a'];

        const int SIZE = *max_element(data.begin(), data.end()) + 1;
        int countingSort[SIZE];
        while (i < SIZE)
            countingSort[i++] = 0;
        for (const int n : data)
            ++countingSort[n];

        int k = data.size();
        for (i = 0; i < SIZE; ++i) {
            for (j = 0; j < countingSort[i]; ++j)
                data[--k] = i;
        }

        i = 0;
        j = 8;
        for (const int n : data)
            i += (j++ / 8) * n;
        return i;

        return 0;
    }
};

