class Solution {
  struct Point {
    int x, y;
    bool operator < (const Point& other) const 
    {
      if (x < other.x) return true;
      if (x > other.x) return false;
      return y > other.y;
    }

  };
public:
    int numberOfPairs(vector<vector<int>>& points) {
      int n = points.size();
      vector<Point> p(n);
      for (int i=0; i<n; i++) p[i] = Point{points[i][0], points[i][1]};
      sort(p.begin(), p.end());

      int r = 0;
      for (int i=0; i<n-1; i++)
      {
        int ay = p[i].y;
        int y_limit = INT_MIN;        
        for (int j=i+1; j<n; j++)
        {
          int by = p[j].y;
          if (by>ay || by<=y_limit) continue;
          r++;
          y_limit = by;
        }
      }
      return r;        
    }
};

