class Solution {
public:
    int numberOfPairs(vector<vector<int>>& points) {
        int n = points.size();
        int res = 0;
        for(int i=0;i<n;++i){
            for(int j=0;j<n;++j){
                if(i==j) continue;
                int x1 = points[i][0], y1 = points[i][1];
                int x2 = points[j][0], y2 = points[j][1];
                if(x1 <= x2 && y1 >= y2){
                    bool valid = true;
                    for(int k=0;k<n;++k){
                        if(k==i||k==j) continue;
                        int x = points[k][0], y = points[k][1];
                        if(x1 <= x && x <= x2 && y2 <= y && y <= y1){
                            valid = false;
                            break;
                        }
                    }
                    if(valid) res++;
                }
            }
        }
        return res;
    }
};

class Solution {
public:
    typedef long long ll;
    long long flowerGame(int n, int m) {
        ll evenx =n/2;
        ll oddx = (n+ 1)/2;
        ll eveny  = m/2;
        ll oddy = (m + 1)/2;
        return evenx*oddy + eveny * oddx;
    }
};

class Solution {
public:
    int earliestSecondToMarkIndices(vector<int>& nums, vector<int>& changeIndices) {
        int n = (int)size(nums), m = (int)size(changeIndices);
        // Observation 1: it's always better to change nums[i] to zero directly than 
        // decrement, if possible (i.e. if we have enough time to mark it later)
        //
        // Observation 2: if we have multiple change to change nums[i] to zero, do it as
        // early as possible since we need to mark it afterwards.



        // change_to_zero[i]: we want to change nums[changeIndices[i]] at time i to zero,
        // if possible
        vector<int> seen(n), change_to_zero(m);
        for (int i = 0; i < m; i++) {
            changeIndices[i]--;
            if (nums[changeIndices[i]] != 0 && !seen[changeIndices[i]]) {
                seen[changeIndices[i]] = 1;
                change_to_zero[i] = 1;
            }
        }

        // Sum of numbers need to be changed
        long long sum = 0;
        for (auto x : nums) sum += x;


        auto check = [&](int mid) {
            // Total work we need to do, which is changing to zero plus marking them
            auto total = sum + n;

            // If we don't have enough time to mark, we need to pick a number and don't 
            // change it to zero directly. Obviously we need to pick the smallest number 
            // to do so.
            //
            priority_queue<int, vector<int>, greater<>> cand;
            // The number of seconds to we could use to mark
            int balance = 0;
            for (int i = mid; i >= 0; i--) {
                if (change_to_zero[i]) { // we want to change to zero in one step
                    balance--; // use one of the balance
                    cand.push(nums[changeIndices[i]]); // put it into candidate for undo
                    total -= nums[changeIndices[i]];
                    if (balance < 0) { // if we don't have enough time to mark
                        total += cand.top() - 1; // -1 because the undone second can be used to decrement another number
                        cand.pop(); // undo
                        balance += 2; // we got two more seconds
                    }
                } else {
                    balance++;
                    total -= 1;
                }
            }
            return total <= 0;
        };

        int l = 0, r = m - 1;
        while (l <= r) {
            int mid = (l + r) / 2;
            if (check(mid)) {
                r = mid - 1;
            } else {
                l = mid + 1;
            }
        }
        return l == m ? -1 : l + 1;
    }
};

class Solution {
public:
    bool canSortArray(vector<int>& nums) {
        vector<int> ans;
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            int x = __builtin_popcount(nums[i]);
            ans.push_back(x);
        }
        int i = 0;
        while (i < n) {
            int j = i;
            while (j + 1 < n && ans[j] == ans[j + 1]) {
                j++;
            }
            if (j > i) {
                sort(nums.begin() + i, nums.begin() + j + 1);
            }
            i = j + 1;
        }
        return is_sorted(nums.begin(), nums.end());
    }
};

class Solution {
public:

    bool allMarked(vector<int>&marked){
        for(int i=0;i<marked.size();i++){
            if(!marked[i]) return false;
        }
        return true;
    }
    bool possible(int mid,vector<int>& nums, vector<int>& changeIndices){
        long long count=0;

        vector<int>marked(nums.size(),0);
        for(int sec=mid;sec>=0;sec--){
            if(!marked[changeIndices[sec]-1]){
                marked[changeIndices[sec]-1]=1;
                count+=nums[changeIndices[sec]-1];
            }
            else if(marked[changeIndices[sec]-1]){
                if(count>0) count--;
            }
        }

        if(allMarked(marked) && count==0) return true;
        return false;
    }

    int earliestSecondToMarkIndices(vector<int>& nums, vector<int>& changeIndices) {
        long long low=0;
        long long high=changeIndices.size()-1;
        long long ans=INT_MAX;

        while(low<=high){

            long long mid=(long long)low+(high-low)/2;
            if(possible(mid,nums,changeIndices)){
                ans=min(ans,(long long)mid);
                high=mid-1;
            }
            else{
                low=mid+1;
            }
        }
        return ans==INT_MAX?-1:(int)ans+1;
    }
};

class Solution {
    vector<int> calcLps(string& word) {
        int n = word.size();
        vector<int> lps(n, 0);
        int len = 0;
        lps[0] = 0;

        int i = 1;
        while (i < n) {
            if (word[i] == word[len]) {
                len++;
                lps[i] = len;
                i++;
            } else {
                if (len != 0) {
                    len = lps[len - 1];
                } else {
                    lps[i] = 0;
                    i++;
                }
            }
        }
        return lps;
    }

public:
    int minimumTimeToInitialState(string s, int k) {
        ios_base::sync_with_stdio(0);
        cin.tie(0);
        cout.tie(0);

        int n = s.length();

        vector<int> lps = calcLps(s);

        // maxlps stores the longest prefix of the entire string that is also a suffix.
        int maxlps = lps.back();

        // The while loop tries to find the largest repeating prefix-suffix such
        // that the leftover portion (n - maxlps) can be evenly divided by k. 
        // If (n - maxlps) % k != 0, it means that the current maxlps doesn't allow
        // a complete cycle that matches k, so maxlps is reduced to 
        // lps[maxlps - 1].

        while (maxlps > 0 && (n - maxlps) % k != 0) {
            maxlps = lps[maxlps - 1];
        }

        if ((n - maxlps) % k == 0) {
            return (n - maxlps) / k;
        }
        return ceil(n / (double)k);
    }
};

class Solution {
public:
    int minimumTimeToInitialState(string word, int k) {
        const int N = word.length();

        vector<int> z(N);
        int l = 0;
        int r = 0;
        for(int i = 1; i < N; ++i){
            if(i <= r){
                z[i] = min(z[i - l], r - i + 1);
            }
            while(i + z[i] < N && word[z[i]] == word[i + z[i]]){
                z[i] += 1;
            }
            if(r <= i + z[i] - 1){
                l = i;
                r = i + z[i] - 1;
            }
        }

        for(int i = k; i < N; i += k){
            if(i + z[i] == N){
                return i / k;
            }
        }

        return (N + k - 1) / k;
    }
};

class Solution {
public:
    int maxSelectedElements(vector<int>& nums) {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);
        cout.tie(nullptr);
        sort(nums.begin(), nums.end()); 
        vector<int> dp(nums.size(), 1);
        int ans = 1;
        int flag = -1;
        for (int i = 1; i < nums.size(); i++) {
            if (nums[i] == nums[i - 1]) {
                int j = i - 1;
                while (i < nums.size() && nums[i] == nums[j]) {
                    dp[i] = dp[j] + 1;
                    nums[i] = nums[i] + 1;
                    ans = max(ans, dp[i]);
                    flag = i + 1;
                    i++;
                }
                i--;
            }
            else if (nums[i] == nums[i - 1] + 1) {
                dp[i] = dp[i - 1] + 1;
            }
            else if (nums[i] == nums[i - 1] + 2) {
                if (flag != -1) {
                    dp[i] = i - flag + 1;
                    flag = i;
                }
                else {
                    flag = i;
                    dp[i] = dp[i - 1] + 1;
                }
            }
            else {
                dp[i] = 1;
                flag = -1;
            }
            ans = max(ans, dp[i]);
        }
        return ans;
    }
};

#define IOS ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
vector<int> get_matches(string &s_, string &p) { //O(s.length+p.length)
    string s=p+"#"+s_;
    int n=s.length();
    int kmp[n+1];
    int i=0,j=-1; kmp[0]=-1;
    while (i<n) {
        while (j!=-1 && s[i]!=s[j]) j=kmp[j];
        j++;i++;
        kmp[i]=j;
    }
    vector<int> matches;
    for (int i=0;i<s_.size();i++) {
        if (kmp[p.size()+i+2]==p.size())
            matches.push_back(i-p.size()+1);
    }
    return matches;
}
class Solution {
public:
vector<int> beautifulIndices(string s, string a, string b, int k) {
    IOS
    vector<int> amat=get_matches(s,a), bmat=get_matches(s,b);
    vector<int> ans;
    for (auto &i:amat) { //O(nlogn)
        auto it=lower_bound(bmat.begin(),bmat.end(),i-k);
        if (it!=bmat.end()) {
            int j=*it;
            if (j<=i+k) ans.push_back(i);
        }
    }
    return ans;
}
};

class Solution {
  static bool isPrefixAndSuffix(const string& str1, const string& str2)
  {
    int n1 = str1.length();
    int n2 = str2.length();
    if (n1>n2) return false;
    auto d1 = str1.data();
    auto d2 = str2.data();
    if (0!=memcmp(d1, d2, n1)) return false;
    if (n1<n2 && 0!=memcmp(d1, d2+n2-n1, n1)) return false;
    return true;
  }

  struct Info
  {
    string w;
    vector<int> ind;
    bool operator < (const Info& other) const { return w.length() < other.w.length(); }
  };

public:
    long long countPrefixSuffixPairs(const vector<string>& words) 
    {
      int n = words.size();
      unordered_map<string, vector<int>> s;
      for (int i=0; i<n; i++) s[words[i]].push_back(i);
      n = s.size();
      vector<Info> infos(n);
      int i=0;
      for (auto [w,ind] : s) infos[i++] = Info{w, ind};
      sort(infos.begin(), infos.end());

      long r = 0;
      for (int i=0; i<n-1; i++)
      {      
        int k = infos[i].ind.size();  
        r += long(k)*(k-1)/2;
        int n1 = infos[i].ind.size();
        for (int j=i+1; j<n; j++)
        {
          if (!isPrefixAndSuffix(infos[i].w, infos[j].w)) continue;
          int a=0, b=0, n2=infos[j].ind.size();

          while (a<n1 && b<n2)
          {
            if (infos[i].ind[a]<infos[j].ind[b]) { r += n2-b; a++; }
            else b++;
          }
        }
      }

      int k = infos[n-1].ind.size();  
      r += long(k)*(k-1)/2;
      return r;        
    }
};

class Solution {
public:
    vector<long long> unmarkedSumArray(vector<int>& nums, vector<vector<int>>& queries) {
        int n= nums.size();

        vector<long long> ans(queries.size());
        vector<int> marked(n,0);
        vector<pair<int,int>> index;
        long long sum=0;
        for(int i=0;i<n;i++){
            index.push_back({nums[i],i});
            sum+=nums[i];
        }
        sort(index.begin(),index.end());
        int j=0;
        for(int i=0;i<queries.size();i++){
            int ind= queries[i][0];
            int k= queries[i][1];

            if(marked[ind]==0){
                marked[ind]=1;
                sum-=nums[ind];
            }
            while(k && j<n){
                int x= index[j].second;
                if(marked[x]==0){
                    marked[x]=1;
                    sum-=nums[x];
                    k--;
                }
                j++;
            }
            ans[i]=sum;
        }
        return ans;
    }
};

class Solution {
public:
    string lastNonEmptyString(string s) {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);

        vector<pair<int, int>> mp(26);

        for (int i = 0; i < s.length(); i++)
            mp[s[i] - 'a'].first++, mp[s[i] - 'a'].second = i;

        sort(mp.rbegin(), mp.rend());

        string ans = "";

        for (int i = 0; i < 26; i++)
        {
            if (i == 0 || (mp[i].first == mp[i - 1].first && mp[i].first != 0))
                ans = s[mp[i].second] + ans;
            else
                break;
        }

        return ans;
    }
};

class Solution {
public:
    int countPrefixSuffixPairs(vector<string>& words) {
        int cnt=0;
        for(int a=0;a<words.size();a++){
            string s=words[a];
            for(int b=a+1;b<words.size();b++){
                string t=words[b];
                if(s.size()>t.size()){continue;}
                int i=0,j=0,pre=1,suf=1;
                while(i!=s.size()){
                    if(s[i]!=t[j]){
                        pre=0;
                        break;
                    }
                    i++;j++;
                }
                i=s.size()-1,j=t.size()-1;
                while(pre==1&&i>=0){
                    if(s[i]!=t[j]){
                        suf=0;break;
                    }
                    i--;j--;
                }
                if(suf==1&&pre==1){cnt++;}
            }
        }
        return cnt;
    }
};

class Solution {
public:
    vector<long long> countOfPairs(int n, int x, int y) {
        vector<long long> ans(n+2);
        if(x > y)swap(x,y);
        if(y-x <= 1)x=y=n;

        for(int i=1;i<=x;i++){
            ans[1]+=1;
            ans[i]-=1;
        }
        int ptr = x+1;
        int temp = ptr;
        while((ptr-x+1) < (y-ptr)) ptr++;
        temp=ptr;
        for(int i = y ;i > x; i--){
            int d1 = min(y-i+1,i-x);
            ans[d1]+=1;
            ans[d1+x]-=1;
            d1 = y-i+1;
            // 1 2 3 4
            while(ptr-x+d1 >= i-ptr && ptr > x)ptr--;


            ans[1]+=1;
            ans[i-ptr]-=1;
            if(ptr > x){
                ans[d1 + 1]+=1;
                ans[d1 + (ptr-x+1)]-=1;
            }    


        } 

        ptr=temp;
        for(int i = y+1;i<=n;i++){
            int d1 = i-y+1;
            ans[1]+=1;
            ans[i-ptr+1]-=1;
            ans[d1+x]-=1;
            ans[d1]+=1; 
            if(ptr-x > 1){
                ans[d1+1]+=1;
                ans[d1+ptr-x]-=1;
            }

        }


        for(int i =1;i<=n;i++)ans[i]+=ans[i-1];
        vector<long long> ans1(n) ;
        for(int i =1 ;i<=n;i++)ans1[i-1] = 2*ans[i];
        return ans1;
    }
};

