class Solution {
public:
    long long maximumStrength(vector<int>& nums, int k) {
        std::vector<int> work = nums;
        work.insert(work.begin(), 0);
        const int n = static_cast<int>(nums.size());
        std::vector<long> dp(k + 1, static_cast<long>(-1e15));
        dp[0] = 0;
        long result = -1e18;
        for (int i = n; i >= 1; --i)
        {
            for (int j = std::min(k, n - i + 1); j >= 1; --j)
            {
                long sign = 2 * (j & 1) - 1;
                dp[j] = std::max({dp[j], dp[j - 1], dp[j - 1]})
                    + sign * work[i] * j;
                if (j == k)
                    result = std::max(result, dp[j]);
            }
        }
        return result;
    }
};

class Solution {
public:
    bool isPrime(int n) {
        if (n <= 1)
            return false;
        int sqrtN = sqrt(n);
        for (int i = 2; i <= sqrtN; i++) {
            if (n % i == 0)
                return false;
        }
        return true;
    }
    int mostFrequentPrime(vector<vector<int>>& mat) {
        int n = mat.size(), m = mat[0].size();
        int drow[8] = {-1, -1, -1, 0, 0, 1, 1, 1};
        int dcol[8] = {-1, 0, 1, -1, 1, -1, 0, 1};

        unordered_map<int, int> mp;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                for (int k = 0; k < 8; k++) {
                    int digit = mat[i][j];
                    int row = i + drow[k];
                    int col = j + dcol[k];
                    while (row >= 0 && row < n && col >= 0 && col < m) {
                        digit = digit * 10 + mat[row][col];
                        if (digit > 10) {
                            if (isPrime(digit))
                                mp[digit]++;
                        }
                        row += drow[k];
                        col += dcol[k];
                    }
                }
            }
        }
        if (mp.empty())
            return -1;
        int freq = 0;
        int ans;
        for (auto it : mp) {
            if (it.second >= freq) {
                if (freq == it.second)
                    ans = max(ans, it.first);
                else {
                    freq = it.second;
                    ans = it.first;
                }
            }
        }
        return ans;
    }
};

class Solution {
public:
    int sumOfPowers(vector<int>& nums, int K) {
        int n = nums.size();
        sort(nums.begin(), nums.end());
        vector<int> diff;
        for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) diff.push_back(nums[j] - nums[i]);
        diff.push_back(0);
        sort(diff.begin(), diff.end());
        diff.resize(unique(diff.begin(), diff.end()) - diff.begin());

        const int MOD = 1e9 + 7;
        long long ans = 0;
        for (int p = 1; p < diff.size(); p++) {
            long long f[n][K + 1];
            memset(f, 0, sizeof(f));
            for (int i = 0, ii = 0; i < n; i++) {
                while (nums[i] - nums[ii] >= diff[p]) ii++;
                f[i][1] = 1;
                if (ii > 0) for (int j = 2; j <= K; j++) f[i][j] = f[ii - 1][j - 1];
                if (i > 0) for (int j = 1; j <= K; j++) f[i][j] = (f[i][j] + f[i - 1][j]) % MOD;
            }
            ans = (ans + (diff[p] - diff[p - 1]) * f[n - 1][K]) % MOD;
        }
        return ans;
    }
};

class Solution {
public:
    int maxPalindromesAfterOperations(vector<string>& words) {
        int ans=0;
        vector<int>freq(26,0);
        vector<int>vect;
        for(auto&str:words){
            vect.push_back(str.length());
            for(auto&ch:str)    freq[ch-'a']++;
        }
        sort(vect.begin(),vect.end());
        for(int i=0;i<vect.size();i++){
            int len=vect[i];
            int extra=0;
            if(len&1){
                extra=1;
                len--;
            }
            for(int i=0;i<26;i++){
                if(len==0)  break;
                if(freq[i]>0){
                    if(freq[i]<len){
                        if(freq[i]&1){
                            len=len-(freq[i])+1;
                            freq[i]=1;
                        }else{
                            len-=freq[i];
                            freq[i]=0;
                        }
                    }else{
                        freq[i]-=len;
                        len=0;
                    }
                }
            }
            if(extra==1){
                for(int i=0;i<26;i++){
                    if(freq[i]&1){
                        freq[i]-=1;
                        //len=0;
                        extra=0;
                        break;
                    }
                }
            }
            if(extra==1){
                for(int i=0;i<26;i++){
                    if(freq[i]>0){
                        freq[i]--;
                        //len=0;
                        extra=0;
                        break;
                    }
                }
            }
            if(len==0 && extra==0)  ans++;
        }
        return ans;
    }
};

