struct Rectangle {
    int x;
    int y;
    int width;
    int height;
};

bool Compare(Rectangle &a, Rectangle &b) {
    return min(a.width, a.height) > min(b.width, b.height);
}

int Side(Rectangle* a, Rectangle* b) {
    int left = max(a->x, b->x);
    int right = min(a->x + a->width, b->x + b->width);
    int top = min(a->y, b->y);
    int bottom = max(a->y - a->height, b->y - b->height);
    int width = right - left;
    int height = top - bottom;
    return min(right - left, top - bottom);
}

class Solution {
public:
    long long largestSquareArea(vector<vector<int>>& bottom_left, vector<vector<int>>& top_right) {
        vector<Rectangle> rectangles;
        for (int a = 0; a < bottom_left.size(); ++a) {
            rectangles.push_back({
                bottom_left[a][0],
                top_right[a][1],
                top_right[a][0] - bottom_left[a][0],
                top_right[a][1] - bottom_left[a][1]
            });
        }
        sort(rectangles.begin(), rectangles.end(), Compare);
        int side = 0;
        for (int a = 0; a < rectangles.size(); ++a) {
            for (int b = a + 1; b < rectangles.size(); ++b) {
                if (min(rectangles[b].width, rectangles[b].height) <= side)
                    break;
                side = max(side, Side(&rectangles[a], &rectangles[b]));
            }
        }
        return static_cast<long long>(side) * static_cast<long long>(side);
    }
};

class Solution {
public:
    vector<int> countPairsOfConnectableServers(vector<vector<int>>& edges, int signalSpeed) {
        ios::sync_with_stdio(false);cin.tie(NULL);cout.tie(NULL);
        int n=edges.size()+1;
        typedef pair<int,int> ii;
        vector<vector<ii>> g(n);
        for(auto& e:edges){
            g[e[0]].emplace_back(e[1], e[2]);
            g[e[1]].emplace_back(e[0], e[2]);
        }

        auto dfs=[&](int u, int p, int d, auto&& dfs)->int{
            int res=0;
            if(d%signalSpeed==0){
                res++;
            }
            for(auto& [v,w]: g[u]){
                if(v!=p){
                    res+=dfs(v,u,d+w, dfs);
                }
            }
            return res;
        };

        vector<int> ans(n);
        for(int i=0; i<n; i++){
            int m=g[i].size();
            if(m==1){
                ans[i]=0;
                continue;
            }
            int sum=0;
            ans[i]=0;
            for(auto& [v,w]:g[i]){
                int r=dfs(v,i,w, dfs);
                ans[i]+=sum*r;
                sum+=r;
            }
        }
        return ans;
    }
};

#define ll long long 
class Solution {
public:
    ll ans = 1e18;

    void Calc(vector<ll>&pre, ll one, ll two) {
        // cout<<one<<" "<<two<<endl;
        if(one < 0 || two < 0) return;
        if((pre.size()-1) < one) return;
        if(one == 0 || one == 1) {
            ans = min(ans, 2*two);
            return;
        }
        int n = pre.size();
        int med = one / 2;
        for(int i=1; i+one <= n; i++) {
            ll l = i, r = i+one-1;
            ll med = (l+r)/2;
            ll val = 0;
            ll mid = pre[med]-pre[med-1];
            ll lsum = pre[med-1]-pre[i-1];
            ll rsum = pre[i+one-1]-pre[med];
            val = ((med-l)*mid - lsum) + (rsum - (r-med)*mid);
            val += 2*two; 
            ans = min(ans,val);
        }
    }

    long long minimumMoves(vector<int>& nums, int k, int maxi) {
        int n = nums.size();
        vector<ll>idx;
        idx.push_back(0);
        for(int i=0; i<n; i++) {
            if(nums[i] == 1) {
                idx.push_back(i);
            }   
        }
        for(int i=1; i<idx.size(); i++) idx[i] += idx[i-1];
        for(int i=0; i<=3; i++) {
            if(k>maxi) Calc(idx,k-maxi+i,maxi-i);
            else Calc(idx,i,k-i);
        }
        return ans;
    }
};

