    vector<vector<int>> modifiedMatrix(vector<vector<int>>& matrix) {
        const int m = matrix.size();
        const int n = matrix[0].size();
        for(int j=0; j<n; ++j) {
            int maxi = -1;
            for(int i=0; i<m; ++i) {
                maxi = max(maxi, matrix[i][j]);
            }
            for(int i=0; i<m; ++i) {
                matrix[i][j] = matrix[i][j] == -1? maxi: matrix[i][j];
            }
        }
        return matrix;
    }
};

