class Solution {
public:
    int minimumOperationsToWriteY(vector<vector<int>>& grid) {
        ios_base::sync_with_stdio(false);
        cin.tie(NULL), cout.tie(NULL);

        vector<int> y(3, 0), rest(3, 0);
        int n = grid.size(), mid = n/2;
        for(int i=0; i<n; i++){
            for(int j=0; j<n; j++){
                if(((i==j || i+j==n-1) && i<mid) || (j==mid && i>=mid)){
                    y[grid[i][j]]++;
                }else{
                    rest[grid[i][j]]++;
                }
            }
        }

        int yCells = mid+n, restCells = n*n-yCells;

        int y0 = (yCells-y[0])+(restCells-max(rest[1], rest[2]));
        int y1 = (yCells-y[1])+(restCells-max(rest[0], rest[2]));
        int y2 = (yCells-y[2])+(restCells-max(rest[0], rest[1]));

        return min({y0, y1, y2});
    }
};

class Solution {
public:
    int maxBottlesDrunk(int numBottles, int numExchange) {
        int ans = 0;  
        int empty = 0;
        ans += numBottles;
        empty += numBottles; 
        int fullBottles = 0;
      while(numExchange <= empty){
        while(empty >= numExchange){
      empty -= numExchange;
       numExchange++;
       fullBottles++;
        }
        ans += fullBottles;
        empty += fullBottles;
        fullBottles = 0;
      }

        return ans;
    }
};

