class Solution {
public:
    int countSubmatrices(vector<vector<int>>& grid, int k) {
        int count = 0;
        for (int i = 0; i < grid.size(); i++)
            for (int j = 1; j < grid[0].size(); j++)
                grid[i][j] += grid[i][j-1];

        for (int i = 1; i < grid.size(); i++) {
            for (int j = 0; j < grid[0].size(); j++) {
                grid[i][j] += grid[i-1][j];
                count += grid[i][j] <= k;
            }
        }

        for (int j = 0; j < grid[0].size(); j++)
            count += grid[0][j] <= k;

        return count;
    }
};

