class Solution {
    vector<int> maxdis(vector<vector<int>>& a,int idx)
    {
        vector<int>ans={-1,-1,-1};
        pair<int,int>maxs={INT_MIN,-1},mins={INT_MAX,-1},maxd={INT_MIN,-1},mind={INT_MAX,-1};
        for(int i=0;i<a.size();i++)
        {
            if(i==idx)
            continue;

            int sum=a[i][0]+a[i][1],diff=a[i][0]-a[i][1];
            if(maxs.first<sum)
            {
                maxs.first=sum;
                maxs.second=i;
            }
            if(mins.first>sum)
            {
                mins.first=sum;
                mins.second=i;
            }
            if(maxd.first<diff)
            {
                maxd.first=diff;
                maxd.second=i;
            }
            if(mind.first>diff)
            {
                mind.first=diff;
                mind.second=i;
            }
        }
        if(maxs.first-mins.first>maxd.first-mind.first)
        {
            ans[0]=maxs.first-mins.first;
            ans[1]=maxs.second;
            ans[2]=mins.second;
        }
        else
        {
            ans[0]=maxd.first-mind.first;
            ans[1]=maxd.second;
            ans[2]=mind.second;
        }
        return ans;
    }
public:
    int minimumDistance(vector<vector<int>>& a) 
    {
        auto ans=maxdis(a,-1);
        int maxi=ans[1],mini=ans[2];
        return min(maxdis(a,maxi)[0],maxdis(a,mini)[0]);
    }
};
