class Solution
{
public:
	long long ans = 0;
	int mod = 1e9 + 7;
	vector<int> pow2;
    vector<vector<int>> dp;
	long long f(vector<int> &nums, int k, int curridx, int target)
	{
		if (target < 0)
		{
			return 0;
		}

		if (curridx == nums.size())
		{
			if (target == 0)
			{
				return 1;
			}

			return 0;
		}

        if(dp[curridx][target] != -1){
            return dp[curridx][target];
        }
		long long a = (f(nums, k, curridx + 1, target - nums[curridx]))% mod;
		long long b = (2 * (f(nums, k, curridx + 1, target) % mod))% mod;

		return dp[curridx][target] = (a + b)%mod;
	}

	int sumOfPower(vector<int> &nums, int k)
	{
        dp.resize(nums.size()+1,vector<int>(k+5,-1));
		return f(nums, k, 0, k);
	}
};

class Solution {
public:
    string getSmallestString(string s, int k) {
        int n=s.size();
        // let the smallest string of size n be "aaa....n"
        string t="";
        for(int i=0;i<n;i++){
            t+='a';
        }
        int i=0;
        while(i<n && k>0){
            if(s[i]==t[i]){
                i++;
                continue;
            }
            char ch=s[i];
            char c=t[i];
            int direct_dis=(ch-'a')- (c-'a');
            int reverse_dis=26-(ch-'a')+(c-'a');
            int dis=min(direct_dis,reverse_dis);
            // minimum distance is also greater than k than we have to replace the char
            if(k<dis){
                // replacing the char in t[i]
                t[i]=((ch-'a')-k)+'a';
                // no k left
                k=0;
            }
            else{
                k-=dis;
            }
            i++;
        }
        // for testcase lol we have to again travere the s.
        while(k==0 && i<n ){
            t[i]=s[i];
            i++;
        }
        return t;
    }
};

class Solution {
public:
    vector<int> resultArray(vector<int>& nums) {
        vector<int>arr1;
        vector<int>arr2;
        vector<int>result;
        arr1.push_back(nums[0]);
        arr2.push_back(nums[1]);
        for(int i=2;i<nums.size();i++){
            if(arr1.back()>arr2.back()){
                arr1.push_back(nums[i]);
            }
            else if(arr1.back()<arr2.back()){
                arr2.push_back(nums[i]);
            }
        }
        for(int i=0;i<arr1.size();i++){
            result.push_back(arr1[i]);
        }
        for(int i=0;i<arr2.size();i++){
            result.push_back(arr2[i]);
        }
        return result;
    }
};

/*
My Intuition -
I think bitwise `AND` of 2 operands will always result in a number that is `<=` both operands. So if problem asks you to minimize result of multiple `AND` operation, then you would want to take all operands as much as possible.

"It's important to note that a walk may visit the same edge or vertex more than once." implies AND operation of all edges in a connected component.

So we use DSU.

Now question is how to get the ANDResult of a component. The way I initially thought was to store result of ANDResult at parent level and when performing Union, I get ANDResult from both u and v and put & it to new parent of (u,v) after Union.

The constraints say that s!=t, but if that was not the case then when s==t, min cost = 0.
*/
// modified DSU
const int speedup = [] { ios::sync_with_stdio(0); cin.tie(0); return 0; }();
class DSU {
    public:
    vector<int> parent,size,ANDResult;
    DSU(int n){
        parent.resize(n);
        iota(parent.begin(),parent.end(),0);
        size.resize(n,1);
        ANDResult.resize(n,-1);     // -1 has all bits set to 1
    }
    int Find(int v){
        if(parent[v]==v)
            return v;
        return parent[v] = Find(parent[v]);
    }
    void Union(int a, int b){
        a=Find(a);
        b=Find(b);
        if(a==b) return;
        if(size[a]<size[b])
            swap(a,b);
        parent[b]=a;
        size[a]+=size[b];
        ANDResult[a]&=ANDResult[b];
    }
};
class Solution {
public:
    vector<int> minimumCost(int n, vector<vector<int>>& edges, vector<vector<int>>& query) {
        int q=query.size();
        DSU dsu(n);
        vector<int> answer(q,-1);
        for(auto &edge:edges){
            int u=edge[0], v=edge[1], w=edge[2];
            dsu.Union(u,v);
            int p=dsu.Find(u);
            dsu.ANDResult[p]&=w;
        }
        for(int i=0;i<q;i++){
            int s=query[i][0], t=query[i][1];
            if(dsu.Find(s)!=dsu.Find(t)) continue;
            answer[i]=dsu.ANDResult[dsu.Find(s)];
        }
        return answer;
    }
};
