class Solution {
public:
    int maximumLengthSubstring(string s) {
        int l=0;
        int r=0;
        int len=0;
        map<char,int> mp;
        while(r<s.size()){
            mp[s[r]]++;
            while(mp[s[r]]>2){
                mp[s[l]]--;
                l++;
            }
            if(mp[s[r]]<=2){
                len=max(len,r-l+1);
            }
            r++;

        }
        return len;
    }
};

class Fenwick{
    vector<int>t;
    public:
    Fenwick(int n)
    {
        t.resize(n+1,0);
    }
    void update(int idx)
    {
        while(idx<t.size())
        {
            t[idx]+=1;
            idx+=(idx & -idx);
        }
    }
    int query(int idx)
    {
        int sum=0;
        while(idx>0)
        {
            sum+=t[idx];
            idx-=(idx & -idx);
        }
        return sum;
    }
};
class Solution {
public:
    vector<int> resultArray(vector<int>& a) 
    {
        vector<pair<int,int>>ap;
        int n=a.size();
        for(int i=0;i<n;i++)
        {
            ap.push_back({a[i],i});
        }
        sort(ap.begin(),ap.end());
        vector<int>ans,a1,a2;
        vector<int>rank(n);
        for(int i=0;i<n;i++)
        {
            rank[ap[i].second]=i+1;
        }
        Fenwick t1(n+1),t2(n+1);
        a1.push_back(a[0]);
        t1.update(rank[0]);
        a2.push_back(a[1]);
        t2.update(rank[1]);
        for(int i=2;i<n;i++)
        {
            int sz1=a1.size()-t1.query(rank[i]);
            int sz2=a2.size()-t2.query(rank[i]);
            if(sz1>sz2)
            {
                a1.push_back(a[i]);
                t1.update(rank[i]);
            }
            else if(sz1<sz2)
            {
                a2.push_back(a[i]);
                t2.update(rank[i]);
            }
            else
            {
                if(a1.size()<=a2.size())
                {
                    a1.push_back(a[i]);
                    t1.update(rank[i]);
                }
                else
                {
                    a2.push_back(a[i]);
                    t2.update(rank[i]);
                }
            }
        }
        ans=a1;
        for(auto &x:a2)
        ans.push_back(x);
        return ans;
    }
};

class Solution {
public:
    bool isSubstringPresent(string s) {
        // Get the reverse of the string `s`
        string rev_s = string(s.rbegin(), s.rend());
        // Check for all substrings of length 2 in `s`
        for (int i = 0; i < s.length() - 1; ++i) {
            string substring = s.substr(i, 2);
            // Check if this substring exists in the reversed string
            if (rev_s.find(substring) != string::npos) {
                return true;
            }
        }
        return false;
    }
};

class Solution {
public:
    string minimizeStringValue(string s) {
        array<int, 27> freq;
        freq[26] = INT_MAX / 26; // 哨兵
        for (char c: s) {
            if (c != '?') {
                freq[c - 'a']++;
            }
        }

        auto f = freq;
        ranges::sort(f);

        int limit, extra;
        int q = ranges::count(s, '?');
        for (int i = 1;; i++) {
            int sum = i * (f[i] - f[i - 1]);
            if (q <= sum) {
                limit = f[i - 1] + q / i;
                extra = q % i;
                break;
            }
            q -= sum;
        }

        auto target = freq;
        for (int j = 0; j < 26; j++) {
            if (freq[j] > limit) {
                continue;
            }
            target[j] = limit;
            if (extra > 0) { // 还可以多分配一个
                extra--;
                target[j]++;
            }
        }

        char j = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s[i] != '?') {
                continue;
            }
            while (freq[j] == target[j]) {
                j++;
            }
            freq[j]++;
            s[i] = 'a' + j;
        }
        return s;
    }
};

