class TrieNode {
public:
    TrieNode *nxt[26];
    int cnt;
    TrieNode() {
        cnt = 0;
        for (auto &v : nxt) v = nullptr;
    }
};

class Trie {
public:
    TrieNode *root;

    Trie() {
        root = new TrieNode();
    }

    void insert(string word) {
        int n = word.size();
        for (int i = 0; i < n; ++i) {
            TrieNode* v = root;
            for (int j = i; j < n; ++j){
                char ch = word[j];
                if (v->nxt[ch - 'a'] == NULL) {
                    TrieNode* node = new TrieNode();
                    v->nxt[ch - 'a'] = node;
                }
                v = v->nxt[ch - 'a'];
                v->cnt++;
            }
        }
    }

    void delete_inserted(string word) {
        int n = word.size();
        for (int i = 0; i < n; ++i) {
            TrieNode* v = root;
            for (int j = i; j < n; ++j){
                char ch = word[j];
                if (v->nxt[ch - 'a'] == NULL) {
                    TrieNode* node = new TrieNode();
                    v->nxt[ch - 'a'] = node;
                }
                v = v->nxt[ch - 'a'];
                v->cnt--;
            }
        }
    }
};

class Solution {
public:
    vector<string> shortestSubstrings(vector<string>& arr) {
        Trie trie;
        for (string s : arr) trie.insert(s);
        vector<string> ans;
        for (string s : arr) {
            trie.delete_inserted(s);
            int n = s.size();
            string res = "";
            for (int i = 0; i < n; ++i) {
                string now;
                TrieNode *node = trie.root;
                for (int j = i; j < n; ++j) {
                    if (res != "" && j-i+1 > res.size()) break;
                    now += s[j];
                    node = node->nxt[s[j] - 'a'];
                    if (node->cnt == 0) {
                        if (res == "" || (res.size() > now.size() || (res.size() == now.size() && res > now))) res = now;
                        break;
                    }
                }
            }
            ans.push_back(res);
            trie.insert(s);
        }
        return ans;
    }
};

class Solution {
public:
    int minimumDeletions(string word, int k) {

        int res=INT_MAX;
        int freq[26];
        memset(freq,0,sizeof(freq));

        for(char c:word)
        {
            freq[c-'a']++;
        }       

        vector<pair<int,int>> vec;

        for(int i=0;i<26;i++)
        {
            vec.emplace_back(freq[i],i);
        }

        sort(begin(vec),end(vec));

        int del = 0;
        for(int i=0;i<vec.size();i++)
        {
            int ops = del;

            for(int j=i+1; j<vec.size();j++)
            {
                ops += max(0, vec[j].first - (vec[i].first+k));
            } 
            res=min(res,ops);

            del += vec[i].first;
        }

        return res;


    }

