};

class Solution {
public:
	string findLatestTime(string& s) {
		for (int i = 0; i < s.length(); i++) {
			if (s[i] == '?') {
				if (i == 0) {
					if (s[1] == '?' || s[1] - '0' < 2) s[0] = '1';
					else s[0] = '0';
				}
				else if (i == 1) s[0] == '1' ? s[1] = '1' : s[1] = '9';
				else if (i == 3) s[3] = '5';
				else if (i == 4) s[4] = '9';
			}
		}
		return s;
	}
};

using ll = long long;
short M[100010];
int S = 0;
class Solution {
public:
    ll counting(int x, vector<int>& nums){
        memset(M, 0, sizeof(M));
        S = 0;
        ll n = nums.size(), i = 0, j = 0, ans = 0;
        while(j < n){
            S += ++M[nums[j++]] == 1;
            while(S > x) if(--M[nums[i++]] == 0) --S;
            ans += j - i;
        }
        return ans;
    }
    int medianOfUniquenessArray(vector<int>& nums) {
        ll n = nums.size();
        ll p = (1 + n) * n / 2 ;
        if(p & 1) p = p / 2 + 1;
        else p = p / 2;
        int l = 1, r = n;
        while(l <= r){
            int m = l + ((r - l) >> 1);
            ll c = counting(m, nums);
            if(c >= p) r = m - 1;
            else l = m + 1;
        } 
        return r + 1;
    }
};

class Solution {
public:
    vector<long long> mostFrequentIDs(vector<int>& nums, vector<int>& freq) {
        int size=*max_element(nums.begin(),nums.end());

        vector<long long > temp(size+1,0);//to store frequency of every nums[i]
        vector<long long > ans;// ans vector
        priority_queue<pair<long long ,long long > >pq;

        for(int i=0;i<nums.size();i++){
            temp[nums[i]] += freq[i];

            pq.push({temp[nums[i]],nums[i]});

//this step is to remove outdated frequency elements of queue which are no use to us.
            while(pq.top().first != temp[pq.top().second]){
                pq.pop();
            }

            ans.push_back(pq.top().first);

        }
        return ans;
    }
};

class Solution {
public:
    int minimumValueSum(vector<int>& nums, vector<int>& andValues) {
        const int INF = INT_MAX / 2;
        int n = nums.size();
        vector<int> f(n + 1, INF);
        vector<int> new_f(n + 1);

        f[0] = 0;
        for (int target : andValues) {
            auto a = nums;
            int left = 0, right = 0;
            deque<int> q; // 单调队列，保存 f 的下标
            int qi = 0; // 单调队列目前处理到 f[qi]

            new_f[0] = INF;
            for (int i = 0; i < n; i++) {
                int x = nums[i];
                for (int j = i - 1; j >= 0 && (a[j] & x) != a[j]; j--) {
                    a[j] &= x;
                }
                while (left <= i && a[left] < target) {
                    left++;
                }
                while (right <= i && a[right] <= target) {
                    right++;
                }

                // 上面这段的目的是求出子数组右端点为 i 时，子数组左端点的最小值和最大值+1
                // 下面是单调队列的滑窗过程

                if (left < right) {
                    // 单调队列：右边入
                    for (; qi < right; qi++) {
                        while (!q.empty() && f[qi] <= f[q.back()]) {
                            q.pop_back();
                        }
                        q.push_back(qi);
                    }

                    // 单调队列：左边出
                    while (q.front() < left) {
                        q.pop_front();
                    }

                    // 单调队列：计算答案
                    new_f[i + 1] = f[q.front()] + x; // 队首就是最小值
                } else {
                    new_f[i + 1] = INF;
                }
            }
            swap(f, new_f);
        }
        return f[n] < INF ? f[n] : -1;
    }
};

class Solution {
    int encrypt(int num){
        int maxi=INT_MIN;
        int size=0;
        while(num!=0){
            int d=num%10;
            size++;
            maxi=max(maxi,d);
            num/=10;

        }
        int sum=0;
        while(size!=0){
            sum=sum*10+maxi;
            size--;
        }
        return sum;


    }
public:
    int sumOfEncryptedInt(vector<int>& nums) {
        int sum=0;
        for(int i=0;i<nums.size();i++){
            sum+=encrypt(nums[i]);

        }
        return sum;

    }
};

class Solution {
public:
    int sumOfTheDigitsOfHarshadNumber(int x) {
        int num=x;
        int sum=0;
        while(num){
            sum+=num%10;
            num/=10;
        }
        if(x%sum==0){
            return sum;
        }
        return -1;
    }
};

class Solution {
public:
    int longestMonotonicSubarray(vector<int>& nums) {
        int increasingCount = 1;
        int decreasingCount = 1;
        int ans = 1;
        for (int i=0; i<nums.size()-1; i++){
            if (nums[i] > nums[i+1]){
                ans = max(ans, increasingCount);
                increasingCount = 1;
                decreasingCount++;

            }
            else if(nums[i] < nums[i+1]){
                ans = max(ans, decreasingCount);
                decreasingCount = 1;
                increasingCount++;
            }
            else{
                ans = max(max(increasingCount, decreasingCount), ans);
                decreasingCount = 1;
                increasingCount = 1;
            }
        }
        ans = max(max(increasingCount, decreasingCount), ans);
        return ans;
    }
};

class Solution {
public:
    int maximumPrimeDifference(vector<int>& nums) {
        ios_base :: sync_with_stdio( false );

        vector< int >primes(101 , 1);
        primes[ 0 ] = 0;
        primes[ 1 ] = 0;
        for(int i=2 ; i<=51 ; i++){
            for(int j=2 ; i*j<=100 ; j++){
                primes[ i*j ] = 0;
            }
        }
        int first = -1 , last = -1;
        for(int i=0 ; i<nums.size() ; i++){
            if(primes[ nums[i] ] == 1){
                if(first == -1) first = i;
                else last = i;
            }
        }
        return ( last == -1 || first == -1 )? 0 : last - first;

    }
};

class Solution {
public:
    long long countAlternatingSubarrays(vector<int>& nums) {
        ios_base::sync_with_stdio(0);
        cin.tie(NULL);cout.tie(NULL);
        long long ans = 0, l = 0, r = 0, n = nums.size();
        while(r < n)
        {
            int len = r-l+1;
            if (len%2==0 && nums[r] != nums[l]) ans += r-l+1;
            else if (len&1 && nums[r] == nums[l]) ans += r-l+1;
            else
            {
                l = r;
                continue;
            }
            ++r;
        }
        return ans;
    }
};

class Solution {
    vector<long> _processOut(vector<int>& coins) {
        ranges::sort(coins);
        int n = coins.size();
        if (coins[0] == 1) return {1};
        vector<long> longCoins;
        for (int coin: coins) {
            for (int lcoin: longCoins) {
                if (coin % lcoin == 0) goto next;
            }
            longCoins.push_back(coin);
            next:;
        }
        return longCoins;
    }
    bool _next(vector<int>& indexes, int n) {
        int i = n - 1;
        while (i >= 0 && indexes[i] == indexes[i + 1] - 1) --i;
        if (i < 0) return false;
        indexes[i]++;
        for (++i; i < n; ++i) indexes[i] = indexes[i - 1] + 1;
        return true;
    }
    void _appendWithCombinations(vector<long>& coins, long upper) {
        int sign{-1};
        const int n = coins.size();
        vector<int> indexes(n + 1);
        for (int i{2}; i <= n; ++i, sign = -sign) {
            for (int j{}; j < i; ++j) indexes[j] = j;
            indexes[i] = n;
            do {
                long prod = 1;
                for (int j{}; j < i; ++j) prod = lcm(prod, coins[indexes[j]]);
                if (prod <= upper) coins.push_back(sign*prod);
            } while (_next(indexes, i));
        }
    }
public:
    long findKthSmallest(vector<int>& poorCoins, int k) {
        ios::sync_with_stdio(false);cin.tie(NULL);cout.tie(NULL);
        vector<long> coins = _processOut(poorCoins);
        const int n = coins.size();
        if (n == 1) return k*coins[0];
        double divider{};
        for (auto coin: coins) divider += 1./coin;
        long upper{coins[0]*k + 1};
        long lower = k/divider;
        _appendWithCombinations(coins, upper);
        while (lower < upper) {
            long mid = (lower + upper)/2;
            long term{};
            long minReminder{numeric_limits<long>::max()};
            for (long coin: coins) {
                auto [q, r] = div(mid, coin);
                term += q;
                minReminder = min(minReminder, r);
            }
            if (term == k) return mid - minReminder;
            if (term < k) lower = mid;
            else upper = mid - minReminder;
            while (upper < abs(coins.back())) coins.pop_back();
        }
        return -1;
    }
};

#define X first
#define Y second

using Pii = pair<int, int>;

constexpr int MAX = 500010;
constexpr int INF = 0x3F3F3F3F;

struct Trie {
  struct Node {
    Pii v = std::make_pair(INF, INF);
    int nxt[26];

    Node() { std::memset(nxt, -1, sizeof(nxt)); }
  } q[MAX];

  int cnt = 1;

  void Clear() {
    std::fill(q, q + cnt, Node());
    cnt = 1;
  }

  void Insert(const char* s, int n, int idx) {
    int x = 0;
    Pii cur = std::make_pair(n, idx);
    for (int i = 0; i < n; ++i) {
      q[x].v = std::min(q[x].v, cur);
      int d = s[i] - 'a';
      if (q[x].nxt[d] == -1) {
        q[x].nxt[d] = cnt++;
      }
      x = q[x].nxt[d];
    }
    q[x].v = std::min(q[x].v, cur);
  }

  int Query(const char* s, int n) const {
    int x = 0;
    for (int i = 0; i < n; ++i) {
      int d = s[i] - 'a';
      if (q[x].nxt[d] == -1) {
        break;
      }
      x = q[x].nxt[d];
    }
    return q[x].v.Y;
  }
} trie;

class Solution {
public:
    vector<int> stringIndices(vector<string>& wordsContainer, vector<string>& wordsQuery) {
      const auto& a = wordsContainer;
      const auto& q = wordsQuery;
      int n = a.size(), m = q.size();
      trie.Clear();
      for (int i = 0; i < n; ++i) {
        std::string s = a[i];
        std::reverse(s.begin(), s.end());
        trie.Insert(s.c_str(), s.length(), i);
      }
      std::vector<int> ret(m);
      for (int i = 0; i < m; ++i) {
        std::string s = q[i];
        std::reverse(s.begin(), s.end());
        ret[i] = trie.Query(s.c_str(), s.length());
      }
      return ret;
    }
};

class Solution {
public:
    int scoreOfString(string s) {
        int score = 0;
        for (size_t i = 0; i < s.length() - 1; i++) {
            score += abs(s[i] - s[i + 1]);
        }
        return score;
    }
};

#pragma GCC optimize("O3", "unroll-loops")
class Solution {
public:
    bitset<30> B;
    int k;
    void update(unsigned* freq, unsigned x, bool add=1){
        bitset<30> b(x);
        for(int i=0; i<30; i++)
            freq[i]+=(add)?b[i]:-b[i];
    }

    bool check(unsigned* freq){
        int b=0;
        for(int i=0; i<30; i++)
            if (freq[i]>0) b|=(1<<i);
        return b>=k;
    }

    void print(auto& f){
        for(int i=0; i<30; i++) cout<<f[i]<<",";
        cout<<endl;
    }

    int minimumSubarrayLength(vector<int>& nums, int k) {
        if (k==0) return 1;
        this->k=k;
        B=bitset<30>(k);
    //    print(B);
        unsigned freq[30]={0};
        int n=nums.size(), ans=INT_MAX;
        for(int l=0, r=0; r<n; r++){
            int x=nums[r];
            if (x>=k) return 1;
            update(freq, nums[r], 1);
        //    cout<<"r="<<r<<",x="<<nums[r]<<", freq:"; print(freq);
            while(l<n && check(freq)){
            //    cout<<"\tl="<<l<<",x="<<nums[l]<<", freq:";print(freq);
                ans=min(ans, r-l+1);
                update(freq, nums[l++], 0);
            }
        }
        return (ans==INT_MAX)?-1:ans;
    }
};

