class Solution {
public:
    int minimumSubarrayLength(vector<int>& nums, int k) {
        int n=nums.size();
        int mini=INT_MAX;
        for(int i=0;i<n;i++){
            int orr=0;
            for(int j=i;j<n;j++){
                orr|=nums[j];
                if(k<=orr){
                 mini=min(mini,j-i+1);
                 break;
                }
            }
        }
        return mini==INT_MAX?-1:mini;
    }
};

