class Solution {
public:
    long long numberOfSubarrays(vector<int>& nums) {
        long ans = 0;
        std::stack<std::pair<int, int>> t;
        for(int const &num: nums) {
            while(not t.empty() and t.top().first < num) { t.pop(); }
            if(t.empty() or t.top().first != num) { t.push({num, 0}); }
            t.top().second += 1;
            ans += t.top().second;
        }
        return ans;
    }
};

