class Solution {
public:
    int minimumOperationsToMakeKPeriodic(string word, int k) {
        unordered_map<string, int>mp;
        int n = word.size();
        for(int i=0;i<n;i+=k){
            string str = word.substr(i, k);
            mp[str]++;
        }
        int ans = 0;
        for(auto it:mp){
            ans = max(ans, it.second);
        }
        return (n/k)-ans;
    }
};
