class Solution {
public:
    long long minOperationsToMakeMedianK(vector<int>& nums, int k) {
        ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
        sort(nums.begin(), nums.end());
        long long ans = 0;
        int middle = nums.size() / 2;
        for (int i = 0; i <= middle; i++) {
            if (nums[i] > k) {
                ans += nums[i] - k;
                nums[i] = k;
            }
        }

        if (nums[middle] == k) return ans;
        while (middle < nums.size() && nums[middle] < k) {
            ans += k - nums[middle];
            nums[middle++] = k;
        }

        return ans;
    }
};

class Solution {
public:
    long long numberOfRightTriangles(vector<vector<int>>& grid) {
        int row = grid.size(), column = grid[0].size();
        long long ans = 0;
        vector<int> sum_c(column, 0), sum_r(row, 0);
        for(int i = 0; i < row; i++){
            for(int j = 0; j < column; j++){
                sum_c[j] += grid[i][j];
                sum_r[i] += grid[i][j];
            }
        }
        for(int i = 0; i < row; i++)
            for(int j = 0; j < column; j++)
                if(grid[i][j])
                    ans += (sum_c[j] - 1) * (sum_r[i] - 1);
        return ans;
    }
};
