class Solution {
public:
    int maxScore(vector<vector<int>>& a) 
    {
        int n=a.size(),m=a[0].size(),ans=INT_MIN;
        vector<vector<int>>dp(n,vector<int>(m));
        dp[n-1][m-1]=a[n-1][m-1];
        for(int i=n-2;i>=0;i--)
        {
            ans=max(ans,dp[i+1][m-1]-a[i][m-1]);
            dp[i][m-1]=max(a[i][m-1],dp[i+1][m-1]);
        }
        for(int i=m-2;i>=0;i--)
        {
            ans=max(ans,dp[n-1][i+1]-a[n-1][i]);
           dp[n-1][i]=max(a[n-1][i],dp[n-1][i+1]);
        }
        for(int i=n-2;i>=0;i--)
        {
            for(int j=m-2;j>=0;j--)
            {
                int val=max(dp[i+1][j],dp[i][j+1]);
                ans=max(ans,val-a[i][j]);
                dp[i][j]=max(val,a[i][j]);
            }
        }
        return ans;
    }
};
