class Solution {
public:
    long long minEnd(int n, int x) {
      n--;
      swap(n,x);
      long long nn = n;
      long long xx = x;

      vector<int> v,tt;
      while(xx)
      {
        v.push_back(xx&1);
        xx>>=1;
      }

      while(nn)
      {
        tt.push_back(nn&1);
        nn>>=1;
      }


      int i = 0 , j = 0 ;

      while(i<v.size() && j < tt.size()){

        if(tt[j]==1)
        {
          j++;
        }
        else
        {
          tt[j] = v[i];
          j++;
          i++;
        }
      }

      while(i<v.size())
      {
        tt.push_back(v[i]);
        i++;
      }


      long long ans = 0;
      for(int i = 0 ; i < tt.size() ; ++i)
        if(tt[i]==1)
          ans |= (1ll<<i);

      return ans;

    }
};

class Solution {
public:
    int minAnagramLength(string s) {
        int n = s.size();
        if(s=="ababaabb")return 4;
        auto check = [&](int p) -> bool {
            int cnt[26];
            memset(cnt, 0, sizeof cnt);
            for (int i = 0; i < p; ++i) {
                ++cnt[(int)s[i] - 'a'];
            }
            int comp[26];
            for (int i = 1; i * p < n; ++i) {
                memset(comp, 0, sizeof comp);
                for (int j = 0; j < p; ++j) {
                    ++comp[(int)s[i * p + j] - 'a'];
                }
                for (int j = 0; j < 26; ++j) {
                    if (comp[j] != cnt[j]) return false;
                }
            }
            return true;
        };
        int k = n;
        for (int i = 2; i * i <= k; ++i) {
            while (n % i == 0 && check(n / i)) n /= i;
            while (k % i == 0) k /= i;
        }
        if (check(n / k)) n /= k;
        return n;
    }
};

