class Solution {
public:
    bool canMakeSquare(vector<vector<char>>& grid) {
        for(int i = 0; i<grid.size()-1; i++)
        {
            for(int j = 0; j<grid[i].size()-1; j++)
            {
                int countB = 0, countW = 0;
                for(int k = i; k<i+2; k++)
                {
                    for(int l = j; l<j+2; l++)
                    {
                        if(grid[k][l] =='B') countB++;
                        else countW++;
                    }
                }
                if(countB>=3 || countW >=3) return true;
            }
        }
        return false;
    }
};

class Solution {
public:
    int minimumAddedInteger(vector<int>& nums1, vector<int>& nums2) {
        int m1 = 0, m2 = 0;
        unordered_map<int,int> mp1,mp2;
        for(int i:nums1){
            m1 = max(m1, i);
            mp1[i]++;
        }
        for(int i:nums2){
            m2 = max(m2, i);
            mp2[i]++;
        }

        int ans = max(m1,m2);

        for(int t=0;t<3;t++){
            int diff = m2-m1;
            bool flag = true;
            for(auto &x:mp2){
                if(mp1[x.first-diff]<x.second){
                    flag = false;
                    break;
                }
            }
            if(flag)
                ans = min(ans, diff);
            mp1[m1]--;
            m1 = 0;
            for(auto &x:mp1){
                if(x.second)
                    m1 = max(m1, x.first);
            }
        }
        return ans;
    }
};

class Solution {
public:
    int minCostToEqualizeArray(vector<int>& nums, int cost1, int cost2) 
    {
       int mod = 1000000007;
       long long int n = nums.size();

       long long int max_element{LLONG_MIN};

       for(int i{}; i< nums.size();i++)
       {
         max_element = max(max_element,(long long) nums[i]);  
       }

        long long int difference{};
        long long int max_difference{LLONG_MIN};

        for(int i{}; i< nums.size();i++)
        {
            difference += (max_element - nums[i]);
            max_difference = max(max_difference, (long long)(max_element - nums[i])); 
        }

        long long int min_ops{LLONG_MAX};

        long long int prev_cost1{LLONG_MAX};

        for(long long int offset{}; offset<= max_element; offset++)
        {
            long long int min_cost1{};

            if(difference < 2*max_difference)
            {
              min_cost1 =  (2*max_difference - difference);
            }

            long long int answer{};

            if(cost2 >= 2*cost1)
            {
                answer = (long long int)cost1 * difference; 
            }
            else
            {
                if((difference - (min_cost1)) %2 == 0)
                {
                    answer = (long long int) cost2 * ((difference - (min_cost1)))/2 + (long long int)min_cost1* (long long int)cost1 ;
                }
                else
                {
                    answer = (long long int)(min_cost1+1)*(long long)cost1 + (long long int)((difference-(min_cost1+1))/2)*(long long int )cost2;
                }
            }    

            min_ops = min(min_ops, answer);

            if(min_ops >= prev_cost1)
            {
                break;
            }
            else
            {
              prev_cost1 = min_ops;  
            }    

            difference += n;
            max_difference++;           
        }  

      return int (min_ops%mod);  
    }
};

