    std::cin.tie(0);
    int ans = 0;
    vector<int> lower(26, -1), upper(26,-1);
    for(int i = 0; i < word.size(); i++){
      if(word[i] >= 97) lower[word[i]-97] = i;
      if(word[i] < 97 && upper[word[i]-65] == -1) upper[word[i]-65] = i;
    }
    for(int i = 0; i < 26; i++){
      if(lower[i] == -1 || upper[i] == -1) continue;
      if(lower[i] < upper[i]) ans++;
    }
    return ans;
  }
};

class Solution {
public:
    int numberOfStableArrays(int zero, int one, int limit) {
        const int mod = 1e9 + 7;
        using ll = long long;
        ll f[zero + 1][one + 1][2];
        memset(f, 0, sizeof(f));
        for (int i = 1; i <= min(zero, limit); ++i) {
            f[i][0][0] = 1;
        }
        for (int j = 1; j <= min(one, limit); ++j) {
            f[0][j][1] = 1;
        }
        for (int i = 1; i <= zero; ++i) {
            for (int j = 1; j <= one; ++j) {
                ll x = i - limit - 1 < 0 ? 0 : f[i - limit - 1][j][1];
                ll y = j - limit - 1 < 0 ? 0 : f[i][j - limit - 1][0];
                f[i][j][0] = (f[i - 1][j][0] + f[i - 1][j][1] - x + mod) % mod;
                f[i][j][1] = (f[i][j - 1][0] + f[i][j - 1][1] - y + mod) % mod;
            }
        }
        return (f[zero][one][0] + f[zero][one][1]) % mod;
    }
};

#define MOD 1000000007
class Solution {
public:
    int numberOfStableArrays(int zero, int one, int limit) {
        vector<long long> dp(max(zero, one)+1); dp[0] = 1;
        long long ans = 0;
        for(int x=1;x<=min(zero, one)+1;x++){
            long long su = 0;
            vector<long long> ndp(max(zero, one)+1);
            for(int j=x;j<=max(zero, one);j++){
                su += dp[j-1];
                if(j >= limit + 1) su -= dp[j-limit-1];
                su += MOD, su %= MOD;
                ndp[j] = su;
            }
            ans += ndp[zero] * dp[one] + ndp[zero] * ndp[one]; // start with 0
            ans += ndp[one] * dp[zero] + ndp[one] * ndp[zero]; // start with 1
            ans %= MOD;
            dp = move(ndp);
        }
        return ans;
    }
};

