class Solution {
public:
    int numberOfSpecialChars(string word) {

        vector<int> vis1(26,0);
        vector<int> vis2(26,0);

        int ans=0;
        for(auto w: word)
        {
            if(w<'a') vis2[tolower(w)-'a']++;
            else vis1[w-'a']++;
        }
        for(int i=0; i<26; i++) if(vis1[i]>0 && vis2[i]>0) ans++;
        return ans;

    }
};

