inline int modExp(long long x, long long e, long long mod) {
    long long res = 1 % mod;
    while (e) {
        if (e & 1) res = res * x % mod;
        x = x * x % mod;
        e >>= 1;
    }
    return res;
}

inline long long sum_e(long long k) {
    long long res = 0ll, n = 0ll, cnt1 = 0ll, sum_i = 0ll;
    for (long long i = __lg(k + 1); i >= 0; --i) {
        long long c = (cnt1 << i) + (i << i >> 1);
        if (c <= k) {
            k -= c;
            res += (sum_i << i) + ((i * (i - 1) / 2) << i >> 1);
            sum_i += i;
            ++cnt1;
            n |= 1LL << i;
        }
    }
    while (k--) {
        res += __builtin_ctzll(n);
        n &= n - 1;
    }
    return res;
}

class Solution {
public:
    vector<int> findProductsOfElements(vector<vector<long long>>& queries) {
        vector<int> res; res.reserve(queries.size());
        for (auto& q : queries) {
            auto er = sum_e(q[1] + 1);
            auto el = sum_e(q[0]);
            res.push_back(modExp(2, er - el, q[2]));
        }
        return res;
    }
};

class Solution {
public:
    int findPermutationDifference(string s, string t) {

        int s1 = s.size();
        int s2 = t.size();
        int count =0;

        for(int i=0; i<s1; i++){

            for(int j=0; j<s2; j++){

                if(s[i]==t[j]){
                    count += abs(i-j);
                    break;
                }
            }
        }

        return count;

    }
