    int waysToReachStair(int k) {
        k--;
        int ans = 0,num1,i,j,x,a,b,target;
        target = 0;
        int jumps = 0;
        while(target < INT_MAX){
            if(target - k > jumps + 1){
                break;
            }
            if(target >= k){
                a = jumps + 1;
                b = target - k;
                printf("target: %i, jumps: %i, a: %i b: %i\n",target,jumps,a,b);
                long long int mul = 1;
                for(j = 1; j <= b; j++){
                    mul *= a - j + 1;
                    mul /= j;
                }
                ans += mul;
                printf("adding: %i\n",mul);
            }
            target = target * 2 + 1;
            jumps++;
        }
        return ans;
    }
};

