class Solution {
public:
    int countDays(int days, vector<vector<int>>& meetings) {
        fastio();
        int n = meetings.size();
        vector<pair<int, int>> vp;
        for (int i = 0; i < n; i++) {
            vp.push_back({meetings[i][0], meetings[i][1]});
        }
        sort(vp.begin(), vp.end());
        // for (auto& ii : vp) {
        //     cout << ii.first << " " << ii.second << endl;
        // }
        int sum = vp[0].first - 1;
        int LastDayMeeting = vp[0].second;
        for (int i = 1; i < n; i++) {
            if (vp[i].first > LastDayMeeting) {
                sum += (vp[i].first - LastDayMeeting) - 1;
            }
            LastDayMeeting = max(LastDayMeeting, vp[i].second);
        }
        sum += days - LastDayMeeting;
        return sum;
    }
};

