class Solution {
public:
    typedef uint_fast16_t u16;

    struct DSU {
        vector<int> e;

        DSU(int n) : e(n, -1) {};

        int get(int v) { return e[v] < 0 ? v : e[v] = get(e[v]); }

        bool same_set(int v, int w) { return get(v) == get(w); } 

        int size(int v) { return -e[get(v)]; }

        bool unite(int v, int w) {
            v = get(v), w = get(w);
            if (v == w) return false;
            if (e[v] > e[w]) swap(v, w);
            e[v] += e[w];
            e[w] = v;
            return true;
        }
    };

    vector<int> findPermutation(vector<int>& nums) {
        const int n = nums.size();
        vector<int> ans(n, -1), h(n), res(n);
        for (int i = 0; i < n; ++i) h[nums[i]] = i;
        DSU dsu(n);
        u16 vis = 0;
        for (int i = 0; i < n; ++i) {
            if (vis & (1 << i)) continue;
            for (int j = i; !(vis & (1 << j)); j = nums[j]) {
                vis |= (1 << j);
                dsu.unite(j, i);
            }
        }
        auto check = [&](){
            DSU g = dsu;
            u16 need = 0;
            for (int i = 0; i < n; ++i) {
                if (ans[i] != -1) {
                    int x = nums[ans[i]];
                    if (x < i) for (int j = x; j < i; ++j) need |= (1 << j);
                    else for (int j = i; j < x; ++j) need |= (1 << j);
                }
            }
            for (int i = 0; i < n - 1; ++i)
                if ((need & (1 << i)) && !g.unite(i, i + 1)) return false;
            vector<int> dir(n - 2, -1);
            u16 cant = 0;
            auto work = [&](int x, int d) {
                dir[x] = (dir[x] >= 0 && dir[x] != d) ? 0 : d;
            };
            for (int i = 0; i < n; ++i) {
                if (ans[i] != -1) {
                    int x = nums[ans[i]];
                    if (x < i) {
                        for (int j = x; j + 1 < i; ++j) work(j, 1);
                        if (x > 0) work(x - 1, 2);
                        if (i + 1 < n) work(i - 1, 2);
                    } else if (x > i) {
                        for (int j = x - 1; j > i; --j) work(j - 1, 2);
                        if (x + 1 < n) work(x - 1, 1);
                        if (i > 0) work(i - 1, 1);
                    } else {
                        if (x + 1 < n) cant |= (1 << x);
                        if (x > 0) cant |= (1 << (x - 1));
                    }
                }
            }
            for (int i = 0; i + 2 < n; ++i)
                if (((need & (1 << i)) && (need & (1 << (i + 1))) && dir[i] == 0) ||
                    ((need & (1 << i)) && (cant & (1 << i)))) return false;
            if ((need & (1 << (n - 2))) && (cant & (1 << (n - 2)))) return false;
            for (int i = 0; i < n - 1; ++i) {
                if ((need & (1 << i)) || (cant & (1 << i)) ||
                    (dir[i - 1] == 0 && (i > 0 || i < n - 2))) continue;
                g.unite(i, i + 1);
            }
            for (int i = 0; i < n; ++i)
                if (!g.same_set(0, i)) return false;
            return true;
        };
        u16 cyc = 0;
        for (int i = 0, cnt = 0, j = 0; true; i = ans[i]) {
            res[j] = i;
            ++j;
            cyc |= (1 << i);
            ++cnt;
            ans[i] = 0;
            while ((cnt < n && (cyc & (1 << ans[i]))) || !check()) ++ans[i];
            if (!ans[i]) break;
        }
        return res;
    }
};

