class segTree {
private:
public:
	vector<int> seg;
	segTree(int n) {
		seg.resize(4 * n);
	}
	void build(int ind, int low, int high, vector<int>& arr) {
		if (low == high) {
			seg[ind] = arr[low];
			return;
		}
		int mid = (low + high) / 2;
		build(ind * 2 + 1, low, mid, arr);
		build(ind * 2 + 2, mid + 1, high, arr);
		seg[ind] = max(seg[ind * 2 + 1], seg[ind * 2 + 2]);
	}
	void update(int ind, int low, int high, int i, int val) {
		if (low == high) {
			seg[ind] = val;
			return;
		}
		int mid = (low + high) / 2;
		if (i <= mid) update(ind * 2 + 1, low, mid, i, val);
		else update(ind * 2 + 2, mid + 1, high, i, val);
		seg[ind] = max(seg[ind * 2 + 1], seg[ind * 2 + 2]);
	}
	int query(int ind, int low, int high, int l, int r) {
		if (high < l || r < low) return INT_MIN;
		if (low >= l && r >= high) return seg[ind];
		int mid = (low + high) / 2;
		int left = query(ind * 2 + 1, low, mid, l, r);
		int right = query(ind * 2 + 2, mid + 1, high, l, r);
		return max(left, right);
	}
};

class Solution {
public:
    vector<bool> getResults(vector<vector<int>>& queries) {
        int maxN = 5e4 + 10;
        vector<bool> res;
        set<int> st;
        st.insert(0);
        st.insert(maxN);

        segTree tree(maxN);

        for(auto q : queries){
            int x = q[1];
            if(q[0] == 1){
                auto it = st.upper_bound(x);
                int r = *it;
                int l = *(--it);
                st.insert(x);
                tree.update(0,0,maxN,x,x - l);
                tree.update(0,0,maxN,r,r - x);
            }
            else{
                int sz = q[2];
                bool isValid = tree.query(0,0,maxN,0,x) >= sz;

                if(!isValid){
                    auto it = st.lower_bound(x);
                    if(*it != x){
                        int l = *(--it);
                        isValid |= ((x -l) >= sz);
                    }
                }
                res.push_back(isValid);
            }
        }

        return res;
    }
};

class Solution {
public:
    int minimumDifference(std::vector<int>& array, int target) {
        int arrayLength = array.size();
        int startIndex = -1;
        int currentResult = std::abs(array[0] - target);
        int orAccumulator = 0;

        for (int endIndex = 0; endIndex < arrayLength; ++endIndex) {
            orAccumulator |= array[endIndex];

            if (orAccumulator > target) {
                orAccumulator = 0;
                startIndex = endIndex;
                while ((orAccumulator | array[startIndex]) <= target) {
                    orAccumulator |= array[startIndex--];
                }
            }

            if (startIndex != endIndex) {
                currentResult = std::min(currentResult, std::abs(orAccumulator - target));
            }

            if (startIndex >= 0) {
                currentResult = std::min(currentResult, std::abs(target - (orAccumulator | array[startIndex])));
            }
        }

        return currentResult;
    }
};
