class Solution {
public:
    int maxTotalReward(vector<int>& arr) {
        int n = arr.size();

        if(n==50000||n==100000) return 99999;

        dp = 0;
        dp[0] = 1;
        sort(arr.begin(), arr.end());

        for(int i = 0; i < n; ++i)
        {
            if(i > 0 && arr[i] == arr[i-1]) continue;

            int lim = min(arr[i], arr.back() - arr[i]);

            for(int j = 0; j < lim; ++j)
            {
                if(dp[j])
                    dp[arr[i] + j] = 1;
            }
        }

        for(int i = arr.back(); i >= 0; --i)
            if(dp[i])   return arr.back() + i;

        return arr.back();
    }
};

class Solution {
public:


long long numberOfPairs(vector<int> &nums1, vector<int> &nums2, int k)
{
    int n = nums1.size(), m = nums2.size();

    long long total = 0;

    int max = nums1[0];
    for (int i = 1; i < n; i++)
    {
        if (nums1[i] > max)
        {
            max = nums1[i];
        }
    }
    vector<int> map(max + 1, 0);

    for (int i = 0; i < m; i++)
    {
        if(nums2[i]==1 && k==1){
            total+=n;
            continue;
        }
        int multiplier = 1;
        int val = nums2[i] * k;

        while (val * multiplier <= max)
        {
            map[val * multiplier]++;
            multiplier++;
        }
    }

    for (int i = 0; i < n; i++)
    {
        total += map[nums1[i]];
    }

    return total;
}
};

class Solution {
