    string clearStars(string s) {
        vector<vector<int>>arr(26);
        vector<int> ind;
        for(int i = 0 ; i < s.size(); i++){
            if(s[i] != '*') arr[s[i]-'a'].push_back(i);
            else{
                for(int j = 0; j < 26; j++){
                    if(arr[j].size()) {
                        arr[j].pop_back();
                        break;
                    }
                }
            }
        }
        for(int j = 0; j < 26; j++){
            for(int k = 0; k < arr[j].size();  k++){
                ind.push_back(arr[j][k]);
            }
        }
        sort(ind.begin(), ind.end());
        string ans = "";
        for(auto it: ind) ans.push_back(s[it]);
        return ans;
    }
};

class Solution {
public:
    int numberOfPairs(vector<int>& nums1, vector<int>& nums2, int k) {
        vector<int> nums_1;

        std::sort(nums2.begin(), nums2.end());

        int l = nums2[0] * k;

        for (auto n : nums1)
        {
            if (n >= l && n % k == 0)
            {
                nums_1.push_back(n);
            }
        }

        int count = 0;

        for (auto n1 : nums_1)
        {
            for (auto n2 : nums2)
            {
                if (n1 % (n2 * k) == 0)
                {
                    count++;
                }
            }
        }

        return count;
    }
};

bool IsDigit(char a)
{
