class Solution {
public:
    string compressedString(string word) {
        int N = size(word), lst = word[0], p = 1;
        string res;
        for (int i = 1; i < N; ++i) {
            int c = word[i];
            if (c == lst) {
                if (++p == 10) { res += '9'; res += c; p = 1; }
            } else {
                res += ('0' + p); res += lst;
                p = 1; lst = c;
            }
        }
        res += ('0' + p);
        res += lst;
        return res;        
    }
};

class Solution {
public:
    int maximumLength(vector<int>& nums, int k) {
        int n=nums.size();
        //dp[i][k] represents the max length of the subsequence that ends with char i and has exactly k mismatch;
        int dp[n][k+2];
        unordered_map<int,int> prevIndex;
        memset(dp,0,sizeof(dp));



        int seqL[k+2];
        memset(seqL,0,sizeof(seqL));
        int ans=0;    


        for(int i=0;i<n;i++){


            //Get the previous index of element which is equal to nums[i];

            int prev=i;
            if(prevIndex.find(nums[i])!=prevIndex.end()){
                prev=prevIndex[nums[i]];                             
            }
            prevIndex[nums[i]]=i;         



            //for all max subsequence so far for a given k, try to add i in it; 
            for(int l=k;l>=0;l--){

               dp[i][l]=max( 1 + ( prev!=i?dp[prev][l]:0), 1+ (l>0?seqL[l-1]:0));
               seqL[l]=max(seqL[l],dp[i][l]); 
               ans=max(ans,seqL[l]);


            }

        }


        return ans;        
    }
};

class Solution {
public:

    void solve(int i,string &op, vector<string>&opp ,int n , bool lastzero){
        if(i==n){
            opp.push_back(op);
            return;   
        }    
        op.push_back('1');
        solve(i+1, op,opp,n, false);  
        op.pop_back();

        if(lastzero==false or op.empty()){  
            op.push_back('0');   
            solve(i+1, op,opp, n, true);  
            op.pop_back();
        }     
        return ;     
    }

    vector<string> validStrings(int n) {
        string op="";
        vector<string>opp={};
        solve(0,op,opp,n, false);


        return opp;
    }
};

