class Solution {
public:
    int maximumLength(vector<int>& nums, int k) {
        unordered_map<int, int> m;

        // remap
        int idx = 0;
        for(int i = 0; i < nums.size(); i++) {
            if(!m.contains(nums[i])) {
                m[nums[i]] = idx;
                idx++;
            }
            nums[i] = m[nums[i]];
        }

        int **dp = (int**) malloc(sizeof(int*) * m.size());
        for(int i = 0; i < m.size(); i++) {
            dp[i] = (int*) malloc(sizeof(int) * (k+1));
            memset(dp[i], 0, sizeof(int) * (k+1));
        }

        // vector<int> res(k + 1);
        int *res = (int*) malloc(sizeof(int) * (k+1));
        memset(res, 0, sizeof(int) * (k+1));

        for (int num : nums) {
            for (int i = k; i >= 0; --i) {
                dp[num][i]++;
                if(i > 0) {
                    dp[num][i] = max(dp[num][i], res[i-1] + 1);
                }
                res[i] = max(res[i], dp[num][i]);
            }
        }

        return res[k];
    }
};

class Solution {
public:
    int numberOfPermutations(int n, vector<vector<int>>& reqs) {
        sort(begin(reqs), end(reqs));
        int dp[2][401] = {1}, prev = 0, j = 0, mod = 1000000007;
        for (int N = 1; N <= n; ++N) {
            for (int K = prev; K <= reqs[j][1]; ++K) {
                dp[N % 2][K] =
                    (dp[(N - 1) % 2][K] + (K > 0 ? dp[N % 2][K - 1] : 0)) % mod;
                if (K >= N)
                    dp[N % 2][K] =
                        (mod + dp[N % 2][K] - dp[(N - 1) % 2][K - N]) % mod;
            }
            if (N - 1 == reqs[j][0]) {
                fill_n(begin(dp[0]) + prev, reqs[j][1] - prev, 0);
                fill_n(begin(dp[1]) + prev, reqs[j][1] - prev, 0);
                prev = reqs[j++][1];
            }
        }
        return dp[n % 2][reqs.back()[1]];
    }
};

