int parse_input_and_solve(const std::string& s) {
    const int S = s.size();
    int cols = 0;
    int rows = 0;
    int k = 2;

    int min_row = INT_MAX;
    int max_row = 0;
    int min_col = INT_MAX;
    int max_col = 0;

    int i = 0;
    int j = 0;
    while (k < S) {
        if (s[k] == '1') {
            min_row = std::min(min_row, i);
            max_row = std::max(max_row, i);
            min_col = std::min(min_col, j);
            max_col = std::max(max_col, j);
            ++j;
        } else if (s[k] == '0') {
            ++j;
        } else if (s[k] == ']') {
            cols = std::max(cols, j);
            j = 0;
            ++i;
        }
        ++k;
    }
    return (max_row - min_row + 1) * (max_col - min_col + 1);
}

