class Solution {
public:
    long long maximumTotalCost(vector<int>& nums) {
        // """
        // 1. f[i][0] : max total cost in nums[0:i] end with negative sign
        //    f[i][1] : max total cost in nums[0:i] end with positive sign
        // 2. f[i + 1][0] = max(max(f[i][0], f[i][1]) + nums[i], f[i][1] - nums[i])
        //    f[i + 1][1] = max(f[i][0], f[i][1]) + nums[i]
        // """

        int n = nums.size();
        array<long long, 2> f{0, INT_MIN};

        for (int i = 0; i < n; i++) {
            long long f0 = f[0], f1 = f[1];
            f[0] = max(max(f0, f1) + nums[i], f1 - nums[i]);
            f[1] = max(f0, f1) + nums[i];
        }
        return ranges::max(f);
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);
        long long res = 0;  // 用來存儲符合條件的子數組數量
        int n = nums.size();  // 獲取數組 nums 的大小
        int c = 0;  // 用來計算以當前元素結束且按位與結果等於 k 的子數組數量

        // 遍歷數組的每一個元素
        for (int i = 0; i < n; i++) {
            // 如果當前元素 nums[i] 等於 k，則以它為結束的子數組數量增加 1
            c += nums[i] == k;

            // 從當前元素的前一個元素開始向前遍歷，檢查以這些元素為結束的子數組
            for (int j = i - 1; j >= 0 && (nums[j] & nums[i]) != nums[j]; j--) {
                // 更新計數 c，若 nums[j] 等於 k，則減去 1，因為 nums[j] 的值會因為與 nums[i] 的按位與運算而改變
                c -= nums[j] == k;
                // 更新 nums[j] 的值為 nums[j] 與 nums[i] 的按位與結果
                nums[j] &= nums[i];
                // 若更新後的 nums[j] 等於 k，則計數 c 加 1
                c += nums[j] == k;
            }

            // 將以當前元素結束的所有符合條件的子數組數量加到結果 res 中
            res += c;
        }

        return res;  // 返回符合條件的子數組數量
    }
};

