class Solution {
public:
    int maxHeightOfTriangle(int red, int blue) {
        return max(solve(red, blue), solve(blue, red));
    }
    int solve(int a, int b) {
        int lvl = 0, i = 1, j = 2;
        while(a >= 0 && b >= 0) {
            if(a - i >= 0) {
                a -= i;
                i += 2;
                lvl++;
            } else break;
            if(b - j >= 0) {
                b -= j;
                j += 2;
                lvl++;
            } else break;
        }
        return lvl;
    }
};

class Solution {
public:
    long long maximumScore(vector<vector<int>>& grid) {
        // take the transpose to make easier for my smol brain
        int n = grid.size();
        for (int i=0; i<n; ++i) for (int j=0; j<n; ++j) {
            if (i < j) swap(grid[i][j], grid[j][i]);
        }

        vector<vector<array<long long, 2>>> dp(n, vector<array<long long, 2>>(n + 1));

        for (int i=1; i<n; ++i) {
            vector<long long> preprocess(n + 1);
            vector<long long> prefix(n + 1);
            for (int j=0; j<=n; ++j) {
                if (0 < j) prefix[j] = prefix[j - 1] + grid[i][j - 1];
                preprocess[j] = dp[i - 1][j][0] + prefix[j];
            }
            vector<long long> suffix = preprocess;
            for (int j=n-1; ~j; --j) suffix[j] = max(suffix[j], suffix[j + 1]);

            long long prefix_unusable = dp[i-1][0][1];
            for (int j=0; j<=n; ++j) {
                prefix_unusable = max(prefix_unusable, dp[i-1][j][1]);
                dp[i][j][0] = max(suffix[j] - prefix[j], prefix_unusable);
                if (j < n) prefix_unusable += grid[i-1][j];
            }
            prefix_unusable = dp[i-1][0][1];
            for (int j=0; j<=n; ++j) {
                prefix_unusable = max(prefix_unusable, dp[i-1][j][1]);
                dp[i][j][1] = max(dp[i-1][j][0] + prefix[j], prefix_unusable);
                if (j < n) prefix_unusable += grid[i - 1][j];
            }
        }
        long long ans = 0;
        for (int j=0; j<=n; ++j) ans = max(ans, dp[n - 1][j][0]);
        return ans;


    }
};

