class Solution {
public:
    int numberOfSubstrings(string s) {
        const int n = static_cast<int>(s.size());
        int total = 0, count = 0;
        std::vector<int> v, pre(n + 1);
        v.push_back(-1);
        for (int i = 0; i < n; ++i)
        {
            if (s[i] == '0')
                total += (count * (count + 1)) / 2,
                count = 0,
                v.push_back(i);
            else
                pre[i] = 1,
                ++count;
            if (i > 0) pre[i] += pre[i - 1];
        }
        pre[n] = pre[n - 1];
        v.push_back(n);
        total += (count * (count + 1)) / 2;
        for (int i = 1; i + 1 < (int)v.size(); ++i)
        {
            int r = v[i + 1], tlen = r + 1;
            for (int j = i - 1; j >= 0; --j)
            {
                int l = v[j], len = r - l - 1, z = i - j, o = len - z, to = tlen - z;
                if (z * z > to) break;
                if (z * z > o) continue;
                int left = pre[v[j + 1]] - ((l == -1)?0:pre[l]);
                int right = pre[r] - pre[v[i]];
                int mid = pre[v[i]] - pre[v[j + 1]];
                int need = z * z - mid;
                if (need)
                {
                    int sm = std::min(left, right), bi = std::max(left, right);
                    count = 0;
                    for (int k = std::max(0, need - bi); k <= sm; ++k)
                        count += std::min(bi + 1, (bi + k + 1 - need));
                    total+= count;
                }
                else total += (left + 1) * (right + 1);
            }
        }
        return total;
    }
};

