class Solution {
public:
    bool is_odd(char d) {
        // no need to convert char to int
        return d & 1;
    }

    bool same_parity(char d1, char d2) {
        return is_odd(d1) == is_odd(d2);
    }

    string getSmallestString(string s) {
        for (int i = 0; i < s.size()-1; i++) {
            if (same_parity(s[i], s[i+1]) && s[i] > s[i+1]) {
                swap(s[i], s[i+1]);
                break;
            }
        }
        return s;
    }
};

class Solution {
public:
    bool isPossible(vector<int>& start, int d, int minDiff) {
        long long prev = (long long)start[0];
        for (int i = 1; i < start.size(); ++i) {
            long long candidate = max((long long)start[i], prev + minDiff);

            if (candidate > (long long)start[i] + d) {
                return false;
            }

            prev = candidate;
        }
        return true;
    }

    int maxPossibleScore(vector<int>& start, int d) {
        sort(start.begin(), start.end());
        int left = 0, right = 2 * 1e9, ans = 0; 
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (isPossible(start, d, mid)) {
                ans = mid;
                left = mid + 1; 
            } else {
                right = mid - 1; 
            }
        }
        return ans;
    }
};

class Solution {
public:
  int maximumLength(vector<int>& nums) {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    std::cout.tie(nullptr);

    int len = nums.size(), odd = 1, even_odd = 0, last_odd = nums[0] % 2;
    for (int *ptr = nums.data(), i = 0; i < len; ++i, ++ptr) {
      int val = *ptr % 2;
      even_odd += val;
      odd += val ^ last_odd;
      last_odd = val;
    }
    if (len - even_odd > even_odd) even_odd = len - even_odd;
    return std::max(odd, even_odd);
  }
};

class Solution {
public:
    int maximumLength(vector<int>& nums, int k) {
        // Step 1: Collect positions of each number
        vector<vector<int>> positions(k);
        for (int i = 0; i < nums.size(); ++i)
            positions[nums[i] % k].push_back(i);

        sort(begin(positions), end(positions), [](const auto &a, const auto &b){ return a.size() > b.size(); });
        int maxLength = max(2, (int)positions[0].size());

        // Step 3: Find the longest interweaved subsequence for each pair of numbers
        for (int i = 0; i < positions.size(); ++i) {
            for (int j = i + 1; j < positions.size() && positions[i].size() + positions[j].size() > maxLength; ++j) {
                int length_ij = (positions[i][0] < positions[j][0]) + (positions[i].back() < positions[j].back());
                for (int k = 0, l = 0; k < positions[i].size() && l < positions[j].size(); ++k) {
                    if (positions[j][l] < positions[i][k])
                        length_ij += 2;
                    while (l < positions[j].size() && positions[j][l] < positions[i][k])
                        ++l;
                }
                maxLength = max(maxLength, length_ij);
            }
        }
        return maxLength;
    } 
};

