class Solution {
public:
    vector<int> resultsArray(vector<vector<int>>& queries, int k) {
    vector<int> ans;
    priority_queue<int> maxHeap;
    ios_base::sync_with_stdio(false);
cin.tie(nullptr);
    for(const auto& query : queries){
        int x = query[0];
        int y = query[1];
        int d = abs(x) + abs(y);
        maxHeap.push(d);

        if(maxHeap.size() < k){
            ans.push_back(-1);
        } else {
            if(maxHeap.size() > k) {
                maxHeap.pop();
            }
            ans.push_back(maxHeap.top());
        }
    }
    return ans;
}
};

class Solution {
public:
    using ll = long long;
    long long minNumberOfSeconds(int mountainHeight, vector<int>& workerTimes) {
        ll l = 1, r = 10000000000000000, m = 0, n = workerTimes.size();
        while(l < r){
            int sum = 0;
            m = l + ((r - l) >> 1);
            for(auto &ele:workerTimes){
                sum += solve(m / ele);
                // need to add this line to prvent from overflow
                if(sum >= mountainHeight)break;
            }
            if(sum < mountainHeight){
                l = m + 1;
            }
            else{
                r = m;
            }
        }
        return l;
    }
    ll solve(ll k){
        // area formula
        //(1 + x) * x / 2 = k
        // x^2 + x - 2k = 0
        // x = (-b +- sqrt(b^2 - 4ac))/2a
        // x = (-1 +- sqrt(1 + 8k))/2
        return (ll)((-1.0 + sqrt(1LL + 8 * (double)k)) / 2);
    }
};
