class Solution {
public:
    int minChanges(vector<int>& nums, int k) {
        int n = nums.size(), ans = n / 2, freq[k + 1], v[k + 1];
        for(int i = 0; i <= k; i++) freq[i] = v[i] = 0;
        for(int i = 0; i < n / 2; i++){
            int diff = abs(nums[i] - nums[n-i-1]); 
            freq[diff]++;
            int threshold = max(max(nums[i], nums[n-i-1]), k - min(nums[i], nums[n-i-1]));
            v[threshold]++;
        }
        for(int i = 1; i <= k; i++) v[i] += v[i-1]; 
        for(int i = 0; i <= k; i++){ 
            int total_one_change = (n/2) - freq[i];
            int additional_change = (i > 0) ? v[i - 1] : 0;
            ans = min(ans, total_one_change + additional_change);
        }
        return ans;
    }
};

