/*
special number is square of prime number.
-- calculate prime nos till r. (vector prime)
-- calculate prefix sum of primes (no of primes till i)

no of non special = (r-l+1) - (prefix[sqrt(r)] - prefix[l-1])
*/

int maxLimit = sqrt(1000000000);
vector<int> prime(maxLimit+1, 1);
vector<int> prefix(maxLimit+1, 0);

class Solution {
public:
    int nonSpecialCount(int l, int r) {
        //calculate prefix only once and use it for all test cases.
        if(prefix[2] == 0){
            for(int i = 2; i <= maxLimit; i++)
                if(prime[i])
                    for(int j = i*i; j <= maxLimit; j += i)
                        prime[j] = 0;

            for(int i = 2; i <= maxLimit; i++)
                prefix[i] = prefix[i-1] + prime[i];
        }

        int res = (r-l+1) - (prefix[sqrt(r)] -  prefix[sqrt(l-1)]);
        return res;
    }
};

class Solution {
public:
    string itob(int n){
        string ans;
        while(n>0){
            int last=n%2;
            ans.push_back(last+'0');
            n/=2;
        }
        return ans;
    }

    int minChanges(int n, int k) {
        if(n==k){
            return 0;
        }
        string n1=itob(n);
        string n2=itob(k);

        while(n1.size()>n2.size()){
            n2.push_back('0');
        }
        while(n2.size()>n1.size()){
            n1.push_back('0');
        }

        cout<<n1<<endl<<n2<<endl;

        int i=0;
        int count=0;
        int possible=true;

        while(i<n1.size()){
            if(n1[i]=='1' and n2[i]=='0'){
                count++;
            }
            else if(n1[i]=='0' and n2[i]=='1'){
                possible=false;
                break;
            }
            i++;
        }

        if(possible==false){
            return -1;
        }

        return count;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    int cnt[11];
    int dfs(TreeNode* root) {
        if (!root) return 0;
        int lh = dfs(root->left);
        int rh = dfs(root->right);
        if (lh == -1 || lh != rh) {
            return -1;
        }
        cnt[lh+1]++;
        return lh + 1;
    }
    int kthLargestPerfectSubtree(TreeNode* root, int k) {
        dfs(root);
        for (int i = 10; i >= 0; i--) {
            int a = cnt[i];
            if (a >= k) {
                return (1 << i) - 1;
            }
            k -= a;
        }
        return -1;
    }
};

