class Solution {
public:
    vector<int> shortestDistanceAfterQueries(int numCities, vector<vector<int>>& queries) {
        for (int i = 0; i < numCities; ++i) {
            nextCity[i] = i + 1;
        }

        vector<int> shortestDistances; 
        shortestDistances.reserve(queries.size());
        int currentDistance = numCities - 1;

        for (const auto &query : queries) {
            int startCity = query[0], qCity = query[1], originalNextCity = nextCity[startCity];
            if (originalNextCity && qCity > originalNextCity) {
                while (originalNextCity != qCity) {
                    int tempNextCity = nextCity[originalNextCity]; 
                    nextCity[originalNextCity] = 0;
                    originalNextCity = tempNextCity; 
                    --currentDistance;
                }
                nextCity[startCity] = qCity;
            }
            shortestDistances.push_back(currentDistance);
        }

        return shortestDistances;        
    }
};

