class neighborSum {
public:
    vector<vector<int>> grida;
    neighborSum(vector<vector<int>>& grid):grida(grid) {

    }

    int adjacentSum(int value) {
        int sum = 0;
        for(int i = 0;i<grida.size();i++){
            for(int j = 0;j<grida[i].size();j++){
                if(value==grida[i][j]){
                    if(i-1>=0)
                    sum+=grida[i-1][j];
                    if((i+1<grida.size()))
                    sum+=grida[i+1][j];
                    if(j+1<grida[i].size())
                    sum+=grida[i][j+1];
                    if(j-1>=0)
                    sum+=grida[i][j-1];
                    break;
                }
            }
            if(sum!=0) break;
        }
        return sum;

    }

    int diagonalSum(int value) {
        int sum = 0;
        for(int i = 0;i<grida.size();i++){
            for(int j = 0;j<grida[i].size();j++){
                if(value==grida[i][j]){
                    if(i-1>=0&&j-1>=0)
                    sum+=grida[i-1][j-1];
                    if((i+1<grida.size()&&j+1<grida[i].size()))
                    sum+=grida[i+1][j+1];
                    if(i-1>=0&&j+1<grida[i].size())
                    sum+=grida[i-1][j+1];

                    if(i+1<grida.size()&&j-1>=0)
                    sum+=grida[i+1][j-1];

                    break;
                }
            }
            if(sum!=0) break;
        }
        return sum;

    }
};

