class Solution {
public:
    vector<int> shortestDistanceAfterQueries(int n, vector<vector<int>>& q) {
        vector<int> dp(n);
        vector<int> ans;
        vector<vector<int>> roads(n);
        for(int i = 1 ; i < n ; i++){
            dp[i] = dp[i-1] + 1;
        }
        int qn = q.size();
        for(int i = 0 ; i < qn ; i++){
            roads[q[i][1]].push_back(q[i][0]);
            for(int j = q[i][1] ; j < n ; j++){
                dp[j] = min(dp[j], dp[j-1] + 1);
                for(int l : roads[j])
                    dp[j] = min(dp[j], dp[l] + 1);
            }
            ans.push_back(dp[n-1]);
        }
        return ans;
    }
};

