class Solution {
public:
    int minFlips(vector<vector<int>>& grid) {
        int n = grid.size();
        int m = grid[0].size();
        int ans = 0;

        // Calculate flips for the four quadrants
        for (int i = 0; i < n / 2; ++i) {
            for (int j = 0; j < m / 2; ++j) {
                int c = 0;
                if (grid[i][j] == 1) c++;
                if (grid[n - i - 1][j] == 1) c++;
                if (grid[i][m - j - 1] == 1) c++;
                if (grid[n - i - 1][m - j - 1] == 1) c++;
                ans += min(c, 4 - c);
            }
        }
         // Handle the middle column if m is odd
        int cnt=0,dnt=0;

        // Handle the middle row if n is odd
        if (n % 2 == 1) {
            int mid = n / 2;
            for (int j = 0; j < m / 2; ++j) {
                if (grid[mid][j] != grid[mid][m - j - 1]) {
                    ans++;
                    cnt++;
                }
                else if(grid[mid][j] == grid[mid][m - j - 1] && grid[mid][j]==1){
                    dnt++;
                }
            }
        }


        if (m % 2 == 1) {
            int mid = m / 2;
            for (int i = 0; i < n / 2; ++i) {
                if (grid[i][mid] != grid[n - i - 1][mid]) {
                    ans++;
                    cnt++;
                }
                else if(grid[i][mid] == grid[n - i - 1][mid] && grid[i][mid] ==1 ){
                    dnt++;
                }
            }
        }

        if(dnt%2==1 && cnt<=0){
            ans+=2;
        }

        // Handle the center cell if both n and m are odd
        if (n % 2 == 1 && m % 2 == 1 && grid[n / 2][m / 2] == 1) {
            ans++;
        }

        return ans;
    }
};

