int speedup = []{ios::sync_with_stdio(0); cin.tie(0); return 0;}();
int st[1 << 17], fwd[50000], cnts[50000], sums[50000], B, N, C;

void fillbt(int *b) {
    for (int i = 0, n = N; i < n; ++i) {
        int j = i | (i+1);
        if (j < n) b[j] += b[i];
    }
}

void init(const vector<int>& colors) {
    int n = N = size(colors); B = 1;
    while (B < n) B *= 2;
    st[B] = colors[0] == colors[n-1] ? 0 : -1;
    for (int i = 1; i < n; ++i) st[B+i] = colors[i] == colors[i-1] ? i : -1;
    for (int i = n; i < B; ++i) st[B+i] = -1;
    for (int i = B-1; i; --i) st[i] = max(st[2*i], st[2*i + 1]);
    fill(cnts, cnts+N, 0);
    fill(sums, sums+N, 0);
    C = 0;

    int first = 0;
    while (first < n && st[B+first] == -1) ++first;
    if (first < n) {
        int prev = first;
        for (int i = prev + 1; i < n; ++i) if (st[B+i] != -1) {
            int sz = i - prev;
            fwd[prev] = i; prev = i;
            ++cnts[sz]; sums[sz] += sz; ++C;
        }
        fwd[prev] = first;
        int sz = n - (prev - first);
        ++cnts[sz]; sums[sz] += sz; ++C;
    } else {
        ++cnts[1]; ++cnts[n-1];
        ++sums[1]; sums[n-1] += n-1;
        C = 2;
    }
    fillbt(cnts);
    fillbt(sums);
}

void set_st(int i, int v) {
    st[i] = v;
    int j;
    while ((j = i/2) && st[j] != (v = max(v, st[i^1]))) st[i = j] = v;
}

void switch_st(int i) {
    int u = i+B;
    set_st(u, st[u] == -1 ? i : -1);
}

int get_st(int i) {
    int res = -1, l = B, r = B+i;
    while (l < r) {
        if (!(r&1)) res = max(res, st[r--]);
        l /= 2; r /= 2;
    }
    return max(res, st[l]);
}

int bt_eval(int i) {
    int cnt = 0, sum = 0;
    for (int x = --i; x >= 0; x = (x & (x+1))-1) cnt += cnts[x], sum += sums[x];
    //cout << i << " " << cnt << " " << sum << endl;
    return N - sum - (C - cnt) * i;
}

void bt_inc(int s) { for (int i = s; i < N; i |= i+1) ++cnts[i], sums[i] += s; }
void bt_dec(int s) { for (int i = s; i < N; i |= i+1) --cnts[i], sums[i] -= s; }

inline int csz(int i, int j) { return i < j ? j-i : N - (i-j); }

void do_update(int i, int j) {
    // Circular => (N-1, 1)
    if (st[1] == -1) { fwd[i] = j; fwd[j] = i; return; }

    // Split block (i,j)
    if (st[B+i] == -1 && st[B+j] == -1) {
        int l = i ? get_st(i-1) : -1; if (l == -1) l = st[1];
        int r = fwd[l];
        fwd[l] = i; fwd[i] = j; fwd[j] = r;
        bt_dec(csz(l, r)); bt_inc(csz(l, i)); bt_inc(1); bt_inc(csz(j, r));
        C += 2;
        return;
    }

    // Merge block (i,j)
    if (st[B+i] != -1 && st[B+j] != -1) {
        int r = fwd[j];
        if (r == i) return; // => Circular
        int l = i ? get_st(i-1) : -1; if (l == -1) l = st[1];
        fwd[l] = r;
        bt_inc(csz(l, r)); bt_dec(csz(l, i)); bt_dec(1); bt_dec(csz(j, r));
        C -= 2;
        return;
    }

    // Either i or j, rename so we move from i to j
    if (st[B+i] == -1) swap(i, j);

    // Move i => j
    int r = fwd[i];
    if (r == i) { fwd[j] = j; return; } // single block, just moved.
    int l = i ? get_st(i-1) : -1; if (l == -1) l = st[1];
    fwd[l] = j; fwd[j] = r;
    bt_dec(csz(l, i)); bt_dec(csz(i, r)); bt_inc(csz(l, j)); bt_inc(csz(j, r));
}

void update(int i) {
    int j = i+1 < N ? i+1 : 0;
    do_update(i, j);
    switch_st(i);
    switch_st(j);
}

class Solution {
public:
    vector<int> numberOfAlternatingGroups(vector<int>& colors, vector<vector<int>>& queries) {
        init(colors);

        vector<int> res;
        for (const auto &q: queries) {
            if (q[0] == 1) {
                res.push_back(st[1] != -1 ? bt_eval(q[1]) : N);
            } else {
                int i = q[1], c = q[2];
                if (colors[i] == c) continue;
                colors[i] = c;
                update(i);
            }
        }
        return res;        
    }
};

