int nbs[100001], edg[200000], tm[100000][2];
vector<int> res;

int dfs(int n, int p) {
    int b0 = 0, b1 = 0;
    for (int i = nbs[n], j = nbs[n+1]; i != j; ++i) if (int nb = edg[i]; nb != p) {
        int x = dfs(nb, n) + 2 - (nb & 1);
        if (x > b0) b1 = b0, b0 = x;
        else if (x > b1) b1 = x;
    }
    tm[n][0] = b0; tm[n][1] = b1;
    return b0;
}

void fill(int n, int p, int pc) {
    int b = tm[n][0], m = max(b, pc);
    res[n] = m;
    int d = 2 - (n & 1), p0 = m + d, p1 = max(tm[n][1], pc) + d;    
    for (int i = nbs[n], j = nbs[n+1]; i != j; ++i) if (int nb = edg[i]; nb != p) {
        int x = tm[nb][0] + 2 - (nb & 1);
        fill(nb, n, x != b ? p0 : p1);
    }
}

class Solution {
public:
    vector<int> timeTaken(vector<vector<int>>& edges) {
        int n = size(edges) + 1;
        fill(nbs, nbs+n, 0);
        for (const auto &e : edges) ++nbs[e[0]], ++nbs[e[1]];
        for (int i = 1; i < n; ++i) nbs[i] += nbs[i-1];    nbs[n] = nbs[n-1];
        for (const auto &e : edges) {
            edg[--nbs[e[0]]] = e[1];
            edg[--nbs[e[1]]] = e[0];
        }
        dfs(0, -1);

        res = vector<int>(n);
        fill(0, -1, 0);
        return move(res);
    }
};

class Solution {
