    int finalPositionOfSnake(int n, vector<string>& commands) {
        int x=0,y=0;
        for(auto it: commands){
            if(it=="UP"){
                x-=1;
            }
            if(it=="DOWN"){
                x+=1;
            }
            if(it=="LEFT"){
                y-=1;
            }
            if(it=="RIGHT"){
                y+=1;
            }
        }
    return x*n+y;
    }
};

class Solution {
public:
    int countPairs(vector<int>& nums) {
        int n = nums.size(), ans = 0;
        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {
                int ta = nums[i];
                int tb = nums[j];
                int c = 0, wa, wb;
                while ((ta != 0) || (tb != 0)) {
                    int ma = ta % 10, mb = tb % 10;
                    ;
                    if (ma != mb) {
                        if (c == 0) {
                            c = 1;
                            wa = ma;
                            wb = mb;
                        } else if (c == 1) {
                            if ((wa == mb) && (wb == ma))
                                c++;
                            else {
                                c = 3;
                                break;
                            }
                        } else {
                            c++;
                            break;
                        }
                    }
                    ta /= 10;
                    tb /= 10;
                }
                if (c == 0 || c == 2)
                    ans++;
            }
        }
        return ans;
    }
};

class Solution {
public:
    int countOfPairs(vector<int>& nums) {
        typedef long long LL;
        static const int maxv = (int)1e3 + 1, mod = (int)1e9 + 7;
        static int f[2][maxv], cur = 0, pre = 1;
        int n = nums.size();
        for(int i = 0; i <= nums[0]; ++i)
            f[cur][i] = 1;
        for(int i = 1; i < n; ++i) {
            swap(cur, pre);
            // j <- k: k <= j && k <= nums[i-1] - nums[i] + j
            int dt = min(nums[i - 1] - nums[i], 0);
            for(int j = 0, k = 0, s = 0; j <= nums[i]; ++j) {
                for( ; k <= j + dt; (s += f[pre][k++]) >= mod && (s -= mod));
                f[cur][j] = s;
            }
        }
        int ans = 0;
        for(int i = 0; i <= nums[n - 1]; ++i)
            (ans += f[cur][i]) >= mod && (ans -= mod);
        return ans;
    }
};

const int MOD = 1'000'000'007;
const int MX = 3001;

long long F[MX];
long long INV_F[MX];

long long pow(long long x, int n) {
    long long res = 1;
    for (; n; n /= 2) {
        if (n % 2) {
            res = res * x % MOD;
        }
        x = x * x % MOD;
    }
    return res;
}

