        F[i] = F[i - 1] * i % MOD;
    }

    INV_F[MX - 1] = pow(F[MX - 1], MOD - 2);
    for (int i = MX - 1; i; i--) {
        INV_F[i - 1] = INV_F[i] * i % MOD;
    }
    return 0;
}();

long long comb(int n, int m) {
    return F[n] * INV_F[m] % MOD * INV_F[n - m] % MOD;
}

class Solution {
public:
    int countOfPairs(vector<int>& nums) {
        int n = nums.size(), m = nums.back();
        for (int i = 1; i < n; i++) {
            m -= max(nums[i] - nums[i - 1], 0);
            if (m < 0) {
                return 0;
            }
        }
        return comb(m + n, n);
    }
};

class Solution {
public:
    char getVal(const string& s){
        int val = 0;
        for(int i =0; i < s.size();++i){
            val = val + s[i]-'a';
        }
        return val%26 + 'a';
    }
    string stringHash(string s, int k) {
        string res;
        int index = 0;
        while(index +k <= s.size()){
            char ch = getVal(s.substr(index, k));
            res.push_back(ch);
            index += k;
        }
        return res;
    }
};

class Solution {
    const int W = 59;
    unsigned int hash(const string &s) {
        unsigned int r = 0;
        for (char c : s) {
            r = r * W + c;
        }
        return r;
    }
public:
    bool reportSpam(vector<string>& message, vector<string>& bannedWords) {
        unordered_set<unsigned int> banned;
        for (const auto& s : bannedWords) {
           banned.insert(hash(s));
        }
        int r = 0;
        for (const auto& s : message) {
            if ((r += banned.count(hash(s))) == 2) return true;
        }
        return false;
    }
};

