class Solution {
    #define ll long long int
    ll dp[501][502][4];
    ll find_answer(vector<vector<pair<ll, ll>>>&grid, int idx, int row, int col, int prev1, int prev2, int count)
    {
        if(idx >= row)
        {
           if(count == 0)
           return 0;

           return -1e13;
        }

        if(dp[idx][prev2 + 1][count] != -1)
        return dp[idx][prev2 + 1][count];


        ll a = 0;

        a = find_answer(grid, idx+1, row, col, prev1, prev2, count);

        if(prev2 == -1)
        {
            for(int k=0; k<col; k++)
            {
                if(grid[idx][k].second == prev1)
                continue;

                a = max(a, grid[idx][k].first + find_answer(grid, idx+1,row, col, prev1, grid[idx][k].second, count - 1));
            }
        }
        else if(count > 0)
        {
            for(int k=0; k<col; k++)
            {
                if((grid[idx][k].second == prev1) || (grid[idx][k].second == prev2))
                continue;

                a = max(a, grid[idx][k].first);
            }
        }
        return dp[idx][prev2 + 1][count] = a;
    }
public:
    long long maximumValueSum(vector<vector<int>>& board) {
        int row = board.size();
        int col = board[0].size();
        vector<vector<pair<ll, ll>>>grid(row, vector<pair<ll, ll>>(col, {0, 0}));

        for(int i=0; i<row; i++)
        {
            for(int j=0; j<col; j++)
            {
                grid[i][j] = {board[i][j], j};
            }
        }

        for(int i=0; i<row; i++)
        {
            sort(grid[i].rbegin(), grid[i].rend());
        }

        sort(grid.rbegin(), grid.rend());

        for(int i=0; i<row; i++)
        {
            for(int j=0; j<col; j++)
            {
                cout<<grid[i][j].first<<" ";
            }
            cout<<"\n";
        }

        ll answer = -1e18;

        for(int i=0; i<3; i++)
        {
            memset(dp, -1, sizeof(dp));
            answer = max(answer, grid[0][i].first + find_answer(grid, 1, row, col, grid[0][i].second, -1, 2));
        }
        return answer;
    }
};

class Solution {
public:
    int countKConstraintSubstrings(string s, int k) {
                int i=0;
        int j=0;
        int zcnt=0;
        int ocnt=0;
        int ans=0;
        while(j<s.length()){
            char x=s[j];
            if(x=='0'){
                zcnt++;
            }
            else{
                ocnt++;
            }
            while(zcnt>k && ocnt>k){
                if(s[i]=='0'){
                    zcnt--;
                }
                else{
                    ocnt--;
                }
                i++;
            }
            ans+=j-i+1;
            j++;
        }
        return ans;
    }
};

