class Solution {
public:
    long long maximumValueSum(vector<vector<int>>& board) {
        int R = size(board), C = size(board[0]);
        int mr1, mc1, m1 = INT_MIN;
        for (int r = 0; r < R; ++r)
        for (int c = 0; c < C; ++c) {
            if (board[r][c] > m1) m1 = board[r][c], mr1 = r, mc1 = c;
        }

        int mr2, mc2, m2 = INT_MIN;
        for (int r = 0; r < R; ++r) if (r != mr1)
        for (int c = 0; c < C; ++c) if (c != mc1) {
            if (board[r][c] > m2) m2 = board[r][c], mr2 = r, mc2 = c;
        }

        int r1 = 0, c1 = 0;
        while (r1 == mr1 || r1 == mr2) ++r1;
        while (c1 == mc1 || c1 == mc2) ++c1;
        for (int r = r1+1; r < R; ++r) if (r != mr1 && r != mr2 && board[r][mc1] > board[r1][mc1]) r1 = r;
        for (int c = c1+1; c < C; ++c) if (c != mc1 && c != mc2 && board[mr1][c] > board[mr1][c1]) c1 = c;
        int r0 = r1, c0 = c1;
        if (board[mr2][mc1] > board[r1][mc1]) r0 = mr2;
        if (board[mr1][mc2] > board[mr1][c1]) c0 = mc2;

        int mv, mh, m3 = INT_MIN, mr3, mc3;
        {
            for (int r = 0; r < R; ++r) if (r != mr1 && r != mr2 && r != r0)
            for (int c = 0; c < C; ++c) if (c != mc1 && c != mc2 && c != c0)
                if (board[r][c] > m3) m3 = board[r][c], mr3 = r, mc3 = c;

            int vm1 = INT_MIN, vm2 = INT_MIN, vr;
            for (int r = 0; r < R; ++r) if (r != mr1 && r != mr2 && r != r0) {
                if (board[r][c0] > vm1) vm1 = board[r][c0], vr = r;
                if (board[r][mc2] > vm2) vm2 = board[r][mc2];
            }

            int hm1 = INT_MIN, hm2 = INT_MIN, hc;
            for (int c = 0; c < C; ++c) if (c != mc1 && c != mc2 && c != c0) {
                if (board[r0][c] > hm1) hm1 = board[r0][c], hc = c;
                if (board[mr2][c] > hm2) hm2 = board[mr2][c];
            }

            mv = mh = m3;
            if (r0 != mr2) mv = max(mv, hm1), mh = max(mh, hm2);
            if (c0 != mc2) mv = max(mv, vm2), mh = max(mh, vm1);
            if (r0 != mr2 && c0 != mc2) mv = max(mv, board[r0][mc2]), mh = max(mh, board[mr2][c0]);

            if (r0 != mr2 && hm1 > m3) m3 = hm1, mr3 = r0, mc3 = hc;
            if (c0 != mc2 && vm1 > m3) m3 = vm1, mr3 = vr, mc3 = c0;
            if (r0 != mr2 && c0 != mc2 && board[r0][c0] > m3) m3 = board[r0][c0], mr3 = r0, mc3 = c0;
        }

        long long s = (long long)m1 + m2 + m3;
        s = max(s, (long long)board[mr1][mc2] + board[mr2][mc1] + m3);

        // M1 (BL):
        {
            int mr = INT_MIN, mc = INT_MIN;
            for (int r = 0; r < R; ++r) if (r != mr2 && r != mr1) mr = max(mr, board[r][mc2]);
            for (int c = 0; c < C; ++c) if (c != mc2 && c != mc1) mc = max(mc, board[mr2][c]);
            s = max(s, (long long)m1 + mr + mc);
        }

        // M2 (TR):
        s = max(s, (long long)m2 + board[r1][mc1] + board[mr1][c1]);

        // TL:
        {
            int m = m3, mc = mc3;
            for (int r = 0; r < R; ++r) if (r != mr1 && r != mr2 && board[r][mc2] > m)
                m = board[r][mc2], mc = mc2;
            long long u;
            if (mc != c0) u = (long long)m + board[mr1][c0];
            else {
                u = (long long)mv + board[mr1][c0];
                int mx = INT_MIN;
                for (int c = 0; c < C; ++c) if (c != mc1 && c != c0) mx = max(mx, board[mr1][c]);
                u = max(u, (long long)m + mx);
            }
            s = max(s, u + board[mr2][mc1]);
        }

        // BR:
        {
            int m = m3, mr = mr3;
            for (int c = 0; c < C; ++c) if (c != mc1 && c != mc2 && board[mr2][c] > m)
                m = board[mr2][c], mr = mr2;
            long long u;
            if (mr != r0) u = (long long)m + board[r0][mc1];
            else {
                u = (long long)mh + board[r0][mc1];
                int mx = INT_MIN;
                for (int r = 0; r < R; ++r) if (r != mr1 && r != r0) mx = max(mx, board[r][mc1]);
                u = max(u, (long long)m + mx);
            }
            s = max(s, u + board[mr1][mc2]);
        }

        return s;
    }
};

