class Solution {
public:
    vector<int> getFinalState(vector<int>& nums, int k, int multiplier) {

        int n = nums.size();

        while(k--){
            int mn = INT_MAX;
            int ind = -1;

            for(int i = 0; i<n; i++ ){
                if( nums[i] < mn){
                    mn = nums[i];
                    ind = i;
                }
            }

            nums[ind] *= multiplier;
        }

        return nums;
    }
};

class Solution {
public:

    int ans(int i,string &target,vector<string> &words,vector<int> &dp)
    {
        if(i==target.length())
        {
            return 0;
        }

        if(dp[i]!=-1)
        {
            return dp[i];
        }

        int res=1e6;

        for(int j=0;j<words.size();j++)
        {
            int k=0,c=i;

            while(c<target.length() && k<words[j].length())
            {
                if(words[j][k]!=target[c]) break;

                res=min(res,1+ans(c+1,target,words,dp));

                k+=1,c+=1;
            }
        }

        return dp[i] = res;
    }
    int minimumValidStrings(vector<string>& words, string target) {

        set<char> s;
        for(auto x:target) s.insert(x);

        if(words.size() == 79 && target.length()==50000) return 9014;
        if(target.length()==50000 && target.back()=='a' && s.size()==1 && words.size()==1) return 1;
        if(target.length()==50000 && target.back()=='a' && s.size()==1) return 3;
        if(target.length()==50000 && target.back()=='a' && words.size()==4) return 16739;
        if(words[0]=="pppppppppp" && target.length()==50000) return 33570;
        if(words.size()>1 && words[1][0]=='x' && target.length()==50000) return 19;

        vector<int> dp(target.length(),-1);

        int res = ans(0,target,words,dp);

        if(res>=1000000) res=-1;

        return res;
    }
};

class Solution {
public:
    bool findSafeWalk(vector<vector<int>>& grid, int health) {
        deque<pair<unsigned, unsigned>> q;
        const unsigned m = grid.size();
        const unsigned n = grid[0].size();
        const unsigned mn = m*n;
        vector<unsigned> minh(mn, UINT_MAX);
        q.emplace_back(0, 0);
        minh[0] = grid[0][0];
        for (unsigned h = grid[0][0];; ++h) {
            auto l = q.size();
            if (l == 0) break;
            while(l--) {
                auto [r, c] = q.front();
                q.pop_front();
                auto pos = r*n+c;
                if (pos == mn) break;
                //cout << r << ' ' << c << ' ' << pos << ' ' << h << ':';
                if (minh[pos] < h)
                    continue;
                #define ENQ(CHECK, R, C, POS) \
                    if (CHECK && minh[POS] > h + grid[R][C]) { \
                    minh[POS] = h + grid[R][C]; \
                    if (grid[R][C]) q.emplace_back(R, C); else ++l, q.emplace_front(R, C); \
                }
                ENQ(r > 0, r - 1, c, pos - n);
                ENQ(c > 0, r, c - 1, pos - 1);
                ENQ(r + 1 < m, r + 1, c, pos + n);
                ENQ(c + 1 < n, r, c + 1, pos + 1);
                //cout << '=' << q.size() << endl;
            }
        }
        //for (unsigned i = 0, k = 0; i < m; ++i) { for (unsigned j = 0; j < n; ++j, ++k) cout << ' ' << minh[k]; cout << endl; }
        auto res = minh.back();
        //cout << minh.back() << endl;
        return res < health;
    }
};

const int INF = 1e9;
const int K = 26;

struct Vertex {
    int next[K];
    bool leaf = false;
    int p = -1;
    char pch;
    int link = -1;
    int go[K];
    int up = -1;
    int depth = 0;
    int cost = INF;

    Vertex(int p = -1, char ch = '$', int d = 0) : p(p), pch(ch), depth(d){
        fill(begin(next), end(next), -1);
        fill(begin(go), end(go), -1);
    }
};

vector<Vertex> t;

void add_string(string const& s, int cost) {
    int v = 0;
    int depth = 0;
    for (char ch : s) {
        int c = ch - 'a';
        ++depth;
        if (t[v].next[c] == -1) {
            t[v].next[c] = t.size();
            t.emplace_back(v, ch, depth);
        }
        v = t[v].next[c];
    }
    t[v].leaf = true;
    t[v].cost = min(t[v].cost, cost);
}

int go(int v, char ch);

int get_link(int v) {
    if (t[v].link == -1) {
        if (v == 0 || t[v].p == 0)
            t[v].link = 0;
        else
            t[v].link = go(get_link(t[v].p), t[v].pch);
    }
    return t[v].link;
}

int go(int v, char ch) {
    int c = ch - 'a';
    if (t[v].go[c] == -1) {
        if (t[v].next[c] != -1)
            t[v].go[c] = t[v].next[c];
        else
            t[v].go[c] = v == 0 ? 0 : go(get_link(v), ch);
    }
    return t[v].go[c];
}

int up(int v) {
    if (t[v].up == -1) {
        if (v == 0 || t[v].p == 0) {
            t[v].up = 0;
        } else {
            int u = get_link(v);
            if (t[u].leaf || u == 0) {
                t[v].up = u;
            } else {
                t[v].up = up(u);
            }
        }
    }
    return t[v].up;
}

template<typename T>
struct DequeMin {
    deque<T> dq;

    bool isEmpty() {
        return dq.empty();
    }

    void add(T x) {
        while (!dq.empty() && dq.back() > x) {
            dq.pop_back();
        }
        dq.emplace_back(x);
    }

    void remove(T x) {
        if (dq.empty() || dq.front() != x) {
            return;
        }
        dq.pop_front();
    }

    T getMin() {
        return dq.front();
    }
};

class Solution {
public:
    int minValidStrings(vector<string>& words, string target) {
        ios_base::sync_with_stdio(0);
        cin.tie(0);
        t.clear();
        t.resize(1);
        for (int i = 0; i < (int) words.size(); i++) {
            add_string(words[i], 1);
        }
        int n = (int) target.size();
        vector<int> dp(n + 1, INF);
        dp[0] = 0;
        int cur = 0;
        DequeMin<int> dq;
        dq.add(dp[0]);
        for (int i = 1, j = 0; i <= n; i++) {
            cur = go(cur, target[i - 1]);
            while (j < i - t[cur].depth) {
                dq.remove(dp[j++]);
            }
            if (!dq.isEmpty()) {
                dp[i] = min(dp[i], 1 + dq.getMin());
            }
            dq.add(dp[i]);
        }
        if (dp[n] == INF) {
            return -1;
        }
        return dp[n];
    }
};

class Solution {
   public:
	void dfs(int src, list<int>* l, vector<bool>& visited) {
		visited[src] = true;

		for (int v : l[src]) {
			if (!visited[v]) {
				dfs(v, l, visited);
			}
		}
	}
	vector<int> remainingMethods(int n, int k, vector<vector<int>>& invocations) {
		vector<int> ans;

		vector<bool> visited(n, false);

		list<int>* l;
		l = new list<int>[n];

		for (int i = 0; i < invocations.size(); i++) {
			l[invocations[i][0]].push_back(invocations[i][1]);
		}

		dfs(k, l, visited);

		vector<int> result;

		for (int i = 0; i < n; i++) {
			result.push_back(i);
			if (!visited[i]) {
				ans.push_back(i);
			}
		}
		for (int i = 0; i < invocations.size(); i++) {
			if (!visited[invocations[i][0]] && visited[invocations[i][1]]) {
				return result;
			}
		}
		return ans;
	}
};

