class Solution {
private:
    bool isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

public:
    long countOfSubstrings(string word, int k) {
        long numValidSubstrings = 0;
        int start = 0;
        int end = 0;
        unordered_map<char, int> vowelCount;
        int consonantCount = 0;

        vector<int> nextConsonant(word.size());
        int nextConsonantIndex = word.size();
        for (int i = word.size() - 1; i >= 0; i--) {
            nextConsonant[i] = nextConsonantIndex;
            if (!isVowel(word[i])) {
                nextConsonantIndex = i;
            }
        }

        while (end < word.size()) {
            char newLetter = word[end];

            if (isVowel(newLetter)) {
                vowelCount[newLetter]++;
            } else {
                consonantCount++;
            }

            while (consonantCount > k) {
                char startLetter = word[start];
                if (isVowel(startLetter)) {
                    vowelCount[startLetter]--;
                    if (vowelCount[startLetter] == 0) {
                        vowelCount.erase(startLetter);
                    }
                } else {
                    consonantCount--;
                }
                start++;
            }

            while (start < word.size() && vowelCount.size() == 5 &&
                   consonantCount == k) {
                numValidSubstrings += nextConsonant[end] - end;
                char startLetter = word[start];
                if (isVowel(startLetter)) {
                    vowelCount[startLetter]--;
                    if (vowelCount[startLetter] == 0) {
                        vowelCount.erase(startLetter);
                    }
                } else {
                    consonantCount--;
                }

                start++;
            }
            end++;
        }

        return numValidSubstrings;
    }
};

class Solution {
public:
    bool check(char a){
        if(a=='a' || a=='e' || a=='u' || a=='i' || a=='o'){
           return true;
        }
        return false;
    }
    int solve(string word, int k){
       unordered_map<char,int> m;
        int count=0,n=word.size(),j=0,ans=0;
        for(int i=0;i<n;i++){
            if(check(word[i])){
                m[word[i]]++;
            }
            else{
                count++;
            }

            while(m.size()==5 && count>=k){
                  ans=ans+(n-i);
                  if(!check(word[j])){
                    count--;
                  }
                  else{
                     m[word[j]]--;
                     if(m[word[j]]==0){
                        m.erase(word[j]);
                     }
                  }
                  j++;
            }
        }

        return ans;
    }
    int countOfSubstrings(string word, int k) {
        return solve(word,k) - solve(word,k+1);
    }
};

