typedef pair<int, int> pr;
class Solution {
public:
    int maxPathLength(vector<vector<int>>& co, int k) {
        ios::sync_with_stdio(false);
        cin.tie(0);
        cout.tie(0);

        int n = co.size(), res;

        vector<pr> c1, c2;

        for(auto &v : co) {
            if(v[0] < co[k][0] && v[1] < co[k][1])
                c1.push_back({v[0], v[1]});
            else if(v[0] > co[k][0] && v[1] > co[k][1])
                c2.push_back({v[0], v[1]});
        }
        c2.push_back({co[k][0], co[k][1]});

        // Sort them by x’s, in the case of equal, the y values should be decreasing.
        sort(c1.begin(), c1.end(), [&](pr &p1, pr &p2) {
            if(p1.first == p2.first)
                return p1.second > p2.second;
            return p1.first < p2.first;
        });
        sort(c2.begin(), c2.end(), [&](pr &p1, pr &p2) {
            if(p1.first == p2.first)
                return p1.second > p2.second;
            return p1.first < p2.first;
        });

        // longest strictly increasing subsequence
        int *v = new int[n];
        int cur_length = 0, idx;

        fill(v, v + n, INT_MAX);
        for(auto &[_, y] : c1) {
            idx = lower_bound(v, v + cur_length, y) - v;
            v[idx] = y;
            cur_length = max(cur_length, idx + 1);
        }

        res = cur_length, cur_length = 1;

        fill(v, v + n, INT_MAX);
        for(auto &[_, y] : c2) {
            idx = lower_bound(v, v + cur_length, y) - v;
            v[idx] = y;
            cur_length = max(cur_length, idx + 1);
        }

        // cout << res << ", " << cur_length << "\n";

        return res + cur_length;
    }
};
