class Solution {
public:
    long long validSubstringCount(string word1, string word2) {
        vector<int> v(26);
        int m = 0;
        for (char c : word2) {
            if (++v[c - 'a'] == 1) {
                ++m;
            }
        }
        long long r = 0;
        const int n = word1.length();
        for (int i = 0, j = 0; i < n; ++i) {
            for (; j < n && m; ++j) {
                 if (--v[word1[j] - 'a'] == 0) {
                     --m;
                 }
            }
            if (m) break;
            r += n - j + 1;
            if (++v[word1[i] - 'a'] == 1) {
                ++m;
            }
        }
        return r;
    }
};

// TC: O(n)
// SC: O(n)
// 203ms, Beats 99.25%
class Solution {
  void dfs(const vector<vector<int>>& children, int parent, int root, const string& s,
           vector<int>& chToNode, vector<int>& out) {
    int index = s[root] - 'a';
    auto newParent = chToNode[index];
    chToNode[index] = root;
    for (auto const& child: children[root]) {
      dfs(children, root, child, s, chToNode, out);
    }

    if (newParent >= 0) {
      out[newParent] += out[root];
    } else if (parent >= 0) {
      out[parent] += out[root];
    }

    chToNode[index] = newParent;
  }

public:
  vector<int> findSubtreeSizes(vector<int>& parent, string s) {
    int n = parent.size();
    vector<vector<int>> children(n);
    for (int i = 1; i < n; i++) {
      children[parent[i]].push_back(i);
    }

    vector<int> out(n, 1), chToNode(26, -1);
    dfs(children, -1, 0, s, chToNode, out);
    return out;
  }
};

class Solution {
