        int res = 0;
        sort(begin(nums), end(nums));
        do {
            int n = 0;
            for(unsigned x : nums) {
                n <<= bit_width(x);
                n |= x;
            }
            res = max(res, n);
        } while(next_permutation(begin(nums), end(nums)));

        return res;
    }
};

