class Solution {
public:
    #define ll long long int
    ll mod=10000000000013,d=100011;
    int minStartingIndex(string s, string pattern) 
    {
        int n=pattern.size(),m=s.size();
        unordered_map<ll,int>hashes;
        vector<ll>mul(n,1);
        for(int i=1;i<n;i++)
           mul[i]=(mul[i-1]*d)%mod;

        ll sh=0,h=0;
        for(int i=0;i<m;i++)
        {
            if(i>=n)
                sh=(sh-((s[i-n]-'a')*mul[n-1])%mod +mod)%mod;
            sh=((sh*d)%mod+(s[i]-'a'))%mod;    
            if(i>=n-1)
            {
                if(hashes.find(sh)==hashes.end())
                   hashes[sh]=i-n+1;
            }
        }


        for(int i=0;i<n;i++)
            h=((h*d)%mod+(pattern[i]-'a'))%mod;
        int res=m;    
        for(int i=0;i<n;i++)
        {
            ll currh=(h-((pattern[i]-'a')*mul[n-i-1])%mod+mod)%mod;
            for(int c=0;c<26;c++)
            {
                ll hash=(currh+(c*mul[n-i-1])%mod)%mod;
                if(hashes.find(hash)!=hashes.end())
                    res=min(res, hashes[hash]);
            }
        }  
        return res==m?-1:res;  
    }
};

