class Solution {
 public:
  vector<int> gcdValues(vector<int>& nums, vector<long long>& queries) {
    int mx = *max_element(nums.begin(), nums.end());
    vector<int> f(mx + 1);
    vector<long long> gcd(mx + 1);  // Use long long to avoid overflow

    // Count frequency
    for (int x : nums) f[x]++;

    // Count number of pairs with GCD == i
    for (int i = mx; i > 0; --i) {
      long long cnt = 0, rep = 0;
      for (int j = i; j <= mx; j += i) {
        cnt += f[j];
        rep += gcd[j];
      }
      gcd[i] = (cnt * (cnt - 1) / 2) - rep;
    }

    // Prefix sum
    for (int i = 1; i <= mx; ++i) gcd[i] += gcd[i - 1];

    // Binary search for each query
    vector<int> res;
    for (long long q : queries) {
      int l = 1, r = mx + 1;
      while (l < r) {
        int m = (l + r) >> 1;
        if (gcd[m] <= q) l = m + 1;
        else r = m;
      }
      res.push_back(l);
    }

    return res;
  }
};

class Solution {
public:
    std::vector<int> validSequence(std::string word1, std::string word2) {
        int n = word1.size(), m = word2.size();
        std::vector<int> ans(m, -1);
        std::vector<int> last(m, -1);

        // Preprocessing: find last occurrence of each character in word2
        for (int i = n - 1, j = m - 1; i >= 0 && j >= 0; --i) {
            if (word1[i] == word2[j]) {
                last[j--] = i;
            }
        }

        bool canSkip = true;
        int j = 0;
        for (int i = 0; i < n && j < m; ++i) {
            if (word1[i] == word2[j]) {
                ans[j++] = i;
            } else if (canSkip && (j == m - 1 || i < last[j + 1])) {
                canSkip = false;
                ans[j++] = i;
            }
        }

        if (j == m) {
            return ans;
        } else {
            return {};
        }
    }
};

