class Solution {
public:
    int countWinningSequences(string s) {
        int n = s.size();
        int mod = 1e9 + 7;
        unordered_map<char , vector<int>>mp;
        mp['F'] = {0 , 1 , -1};
        mp['W'] = {-1 , 0 , 1};
        mp['E'] = {1 , -1 ,0};
        vector<vector<vector<long long>>>dp(n , vector<vector<long long>>(2*n + 1 , vector<long long>(3 , 0)));
        for(int i = 0 ; i< 3 ; i++){
            dp[0][n + mp[s[0]][i]][i] = 1;
        }
        for(int i = 1 ; i < n ; i++){
            for(int prev = 0 ; prev < 3 ; prev++){
                for(int curr = 0 ; curr < 3 ; curr++){
                    if(prev == curr)continue;
                    for(int j = 0 ; j <= 2*n ; j++){
                        if(dp[i-1][j][prev] == 0) continue;
                        dp[i][j + mp[s[i]][curr]][curr] += dp[i-1][j][prev];
                        dp[i][j+mp[s[i]][curr]][curr] %= mod;
                    }
                }
            }
        }
        long long ans = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = n + 1; j <= 2 * n; j++) {
                ans = (ans + dp[n - 1][j][i]) % mod;
            }
        }
        return (int)ans;
    }
};

class Solution {
public:
    long long shiftDistance(string s, string t, vector<int>& nextCost, vector<int>& previousCost) {
        long long n = s.length();
        //vector<long long> next(26);
        //vector<long long> prev(26);
        long long next[26], prev[26];
        long long cost = 0;

        for(int i=0;i<26;i++){
            next[i] = nextCost[i];
            prev[i] = previousCost[i];
        }
        for(int i=1;i<26;i++){
            next[i] += next[i-1];
        }


        for(int i=24;i>=0;i--){
            prev[i] += prev[i+1];
        }

        for(int i=0;i<n;i++){
            if(s[i] != t[i]){
                int b=s[i]-'a', e=t[i]-'a';

                if(b<e){
                    long long forward = next[e-1]-(b>0?next[b-1]:0);
                    long long backward = prev[0]-(b+1>=26?0:prev[b+1]) +(e+1>25?0:prev[e+1]);
                    cost += min(forward, backward);
                }
                else{
                    long long forward= (e==0?0:next[e-1]) + next[25]-next[b-1]; 
                    long long backward = prev[e+1]-(b>=25?0:prev[b+1]);
                    cost += min(forward, backward);
                }
            }
        }
        return cost;
    }
};

class Solution {
public:
    long long maxScore(vector<int>& nums) {
        int n = nums.size();
        if(n==1)return 1ll*nums[0]*nums[0];
        vector<int>pre_g(n),suff_g(n);
        vector<long long>pre_l(n),suff_l(n);
        for(int i=0;i<n;i++){
            pre_g[i]=gcd(nums[i],i?pre_g[i-1]:0);
            pre_l[i]=lcm(nums[i],i?pre_l[i-1]:1);
        }
        for(int i=n-1;~i;i--){
            suff_g[i]=gcd(nums[i],i+1<n?suff_g[i+1]:0);
            suff_l[i]=lcm(nums[i],i+1<n?suff_l[i+1]:1);
        }
        long long ans=1ll*pre_g.back()*pre_l.back();
        auto gg=[&](int i)->int{
            int before=(i?pre_g[i-1]:0);
            int after=(i+1<n?suff_g[i+1]:0);
            return gcd(before,after);
        };
        auto ll=[&](int i)->long long{
            int before=(i?pre_l[i-1]:1);
            int after=(i+1<n?suff_l[i+1]:1);
            return lcm(before,after);
        };
        for(int i=0;i<n;i++){
            ans=max(ans,1ll*gg(i)*ll(i));
        }
        return ans;
    }
};

class Solution {
public:
    int getLargestOutlier(vector<int>& nums) {
        int total = 0, minm = INT_MAX, maxm = INT_MIN, res = INT_MIN;
        for(int num : nums) {
            total += num;
            if(num > maxm) maxm = num;
            if(num < minm) minm = num;
        }
        // cout<<"minm: "<<minm<<" and maxm :"<<maxm<<endl;
        vector<int>occur(maxm - minm + 1, 0);
        for(int num : nums) occur[num - minm]++;

        for(int i = maxm;i >= minm;i--) {// outlier
            if(occur[i - minm] == 0) continue ;
            occur[i - minm]--;
            // cout<<"total: "<<total<<" outlier: "<<i<<" and sum: "<<((total - i)/2)<<endl;
            int rem = ((total - i)/2);
            if((total - i) %2 == 0 && 
                rem >= minm &&
                rem <= maxm &&
                occur[rem - minm] > 0) return i;
            occur[i - minm]++;
        }
        return res;
    }
};


