class Solution {
public:


    bool isPossibleToRearrange(string s, string t, int k) {
        ios_base::sync_with_stdio(false);
        cin.tie(nullptr);
        cout.tie(nullptr);

        int n=s.size(),l=n/k;
        unordered_map<long long,int> m;
        m.reserve(k*2);
        for (int i=0;i<n;){
            long long h=0;
            for (int j=0;j<l;j++) h=(h*26+s[i+j]-'a'+1)%1000000007;
            m[h]++;
            i+=l;
        }

        for (int i=0;i<n;){
            long long h=0;
            for (int j=0;j<l;j++) h=(h*26+t[i+j]-'a'+1)%1000000007;
            if (!m[h]) return false;
            m[h]--;
            i+=l;
        }

        return true;
    }
};

class Solution {
public:

    string nextchar (string s){
        for(int i = 0; i < s.size(); i++){
            if(s[i] == 'z'){
                s[i] = 'a';
            }
            else{
                s[i] = s[i] + 1;
            }
        }
        return s;
    }

    char kthCharacter(int k) {

        string st = "ab";
        string n  = "b";

        while(st.size() < k){
            n = n + nextchar(n);
            st = st + n;
            //cout<<st<<"\n";
        }

        return st[k-1];

    }
};

class Solution {
public:
    #define ll long long
    char kthCharacter(long long k, vector<int>& a) {
        if(k==1){
            return 'a';
        }
        ll opType = -1;
        ll newK= -1;
        ll len=1;
        for(int i=0;i<a.size();i++){
            len = 2*len;
            if(len>=k){
                opType = a[i];
                newK = k-(len/2);
                break;
            }
        }

        char ch = kthCharacter(newK, a);
        if(opType == 0){
            return ch;
        }
        return ch=='z' ? 'a':ch+1;

    }
};

