class Solution {
 public:
  int numberOfWays(int n, int x, int y) {
    long long res = 0, pow = 1, perm = 1;
    for (int i = 1; i <= min(n, x); ++i) {
      perm = perm * (x - i + 1) % mod;
      pow = pow * y % mod;
      res = (res + (perm * pow % mod) * s[n][i]) % mod;
    }
    return res;
  }
};

