vector<int> linear_sieve_of_eratosthenes(int n) {
    vector<int> spf(n + 1, -1);
    vector<int> primes;
    for (int i = 2; i <= n; ++i) {
        if (spf[i] == -1) {
            spf[i] = i;
            primes.emplace_back(i);
        }
        for (const auto& p : primes) {
            if (i * p > n || p > spf[i]) {
                break;
            }
            spf[i * p] = p;
        }
    }
    return spf;
}
const int MAX_N = 1e6;
const auto& SPF = linear_sieve_of_eratosthenes(MAX_N);
class Solution {
public:
    int minOperations(vector<int>& nums) {
        int result = 0;
        for (int i = size(nums) - 2; i >= 0; --i) {
            if (nums[i] <= nums[i + 1]) {
                continue;
            }
            if (SPF[nums[i]] > nums[i + 1]) {
                return -1;
            }
            nums[i] = SPF[nums[i]];
            ++result;
        }
        return result;
    }
};

class Solution
{
public:
    vector<int> findXSum(vector<int>& nums, int k, int x)
    {
        vector<pair<int,int>> freqVal;
        vector<int> result;

        for(int i = 0, end = nums.size() - k;
            i <= end;
            ++i)
        {
            for(int j = i, endj = i + k;
                j < endj;
                ++j)
            {
                for(int k = 0, endk = freqVal.size();
                    true;
                    ++k)
                {
                    if(k == endk)
                    {
                        freqVal.push_back({1, nums[j]});
                        break;
                    }
                    if(nums[j] == freqVal[k].second)
                    {
                        ++freqVal[k].first;
                        break;
                    }
                }
            }

            sort(freqVal.begin(), freqVal.end(),
            [](const pair<int,int>& a, const pair<int,int>& b)
            {
                return a.first > b.first;
            }
            );

            for(int j = 0, endj = freqVal.size(), k;
                j < endj;
                ++j)
            {
                k = j+1;
                while(k < endj && freqVal[k].first == freqVal[j].first)
                {
                    ++k;
                }
                if(k != j+1)
                {
                    sort(freqVal.begin() + j, freqVal.begin() + k,
                    [](const pair<int,int>& a, const pair<int,int>& b)
                    {
                        return a.second > b.second;
                    }
                    );
                    j = k-1;
                }
            }

            int temp = 0;

            for(int j = 0, end = freqVal.size();
                j < x && j < end;
                ++j)
            {
                temp += freqVal[j].first * freqVal[j].second;
            }

            result.push_back(temp);
            freqVal.clear();
        }

        return result;
    }
};

 class Solution {
public:
    vector<int> minBitwiseArray(vector<int>& nums) {
        vector<int> ans(nums.size());

        for (int i = 0; i < nums.size(); i++) {
            int num = nums[i];

            if (num == 2) {
                ans[i] = -1;
                continue;
            }

            int numCopy = num;
            int count = 0;

            // Count consecutive 1s from the right
            while ((num & 1) == 1) {
                count++;
                num >>= 1;
            }

            // [count]th bit is the position of the last 1, like 100111 (count = 3)
            // Subtract the bit                                     ^
            ans[i] = numCopy - (1 << (count - 1));
        }

        return ans;
    }
};

class Solution {
public:bool isStrictlyIncreasing(const vector<int>& nums, int start, int k) {
        for (int i = start + 1; i < start + k; ++i) {
            if (nums[i] <= nums[i - 1]) {
                return false;
            }
        }
        return true;
    }



    bool hasIncreasingSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        for (int i = 0; i + 2 * k <= n; ++i) {
            if (isStrictlyIncreasing(nums, i, k) &&
                isStrictlyIncreasing(nums, i + k, k)) {
                return true;
            }
        }
        return false;
    }
};

