class Solution {
public:
    int countValidSelections(vector<int>& nums) {
        int total = accumulate(nums.begin(),nums.end(),0LL);
        int half = total/2, current_total = 0, cnt = 0;
        bool isEven = total % 2 == 0;

        for(int i = 0; i < nums.size(); i++){
            if( (current_total == half || current_total == half+1) && nums[i] == 0) cnt++;
                current_total += nums[i];
                if( (isEven && current_total > half) || (!isEven && current_total > half+1) ) break;
        }

        return isEven? 2*cnt: cnt;
    }
};

