class Solution {
 public:
  int maxDistinctElements(vector<int>& nums, int k) {
    sort(nums.begin(), nums.end());
    int n = nums.size();
    int prev = nums[0] - k + 1;
    int res = 1;
    for (int i = 1; i < n; ++i) {
      if (nums[i] + k < prev) continue;
      if (nums[i] - k > prev) prev = nums[i] - k;
      res++;
      prev = max(prev + 1, nums[i] - k);
    }
    return res;
  }
};

