class Solution {
public:
    int maxFrequency(vector<int>& nums, int k, int numOperations) {
        map<int,int>mp;
        unordered_map<int,int>hash;
        set<int>points;
        for(auto &it:nums){
            hash[it]++;
            mp[it-k]++;
            mp[it+k+1]--;
            points.insert(it);
            points.insert(it-k);
            points.insert(it+k+1);
        }
        int ans=1;
        int sum=0;
        for(auto &it:points){
            sum+=mp[it];
            ans=max(ans,hash[it]+min(sum-hash[it],numOperations));
        }
        return ans;
    }
};

class Solution {
public:
    bool canAliceWin(int n) {
        constexpr int k_N = 10, k_Total = (k_N+1)*k_N/2;
        int l = 0, h = k_N, numRemTurns = k_N;
        while (l <= h) {
            if (const int m = midpoint(l, h); (k_Total - ((m+1)*m/2)) <= n)
                numRemTurns = m, h = m-1;
            else
                l = m+1;
        }
        const int numTurns = k_N - numRemTurns;
        return (numTurns & 1) != 0;
    }
};

class Solution {
public:
    int smallestNumber(int n, int t) {
        auto productOfDigits = [](int x) {
            int product = 1;
            while (x > 0) {
                product *= (x % 10);
                x /= 10;}
            return product;
        };

        for (int i = n; i < n + 10; ++i) {
            if (productOfDigits(i) % t == 0) {
                return i;}
        }

        return -1; }
};

