class Solution {
public:
    int minTimeToReach(vector<vector<int>>& moveTime) {
        int rows = moveTime.size();
        int columns = moveTime[0].size();
        std::priority_queue<std::tuple<int, int, int>, vector<tuple<int, int, int>>, greater<std::tuple<int, int, int>>> minHeap;
        std::vector<std::vector<int>> time(rows, std::vector<int>(columns, std::numeric_limits<int>::max()));

        minHeap.emplace(0,0,0);
        time[0][0] = 0;

        std::vector<std::pair<int, int>> directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!minHeap.empty())
        {
            auto [currentTime, x, y] = minHeap.top();
            minHeap.pop();

            if (x == rows-1 && y == columns-1)
                return currentTime;

            for (const auto & [dx, dy] : directions)
            {
                int newX = dx + x, newY = dy + y;
                if (newX >= 0 && newX < rows && newY >= 0 && newY < columns)
                {
                    int waitime = std::max(moveTime[newX][newY] - currentTime, 0);
                    int newTime = currentTime + 1 + waitime;

                    if (newTime < time[newX][newY])
                    {
                        time[newX][newY] = newTime;
                        minHeap.emplace(newTime, newX, newY);
                    }
                }
            }
        }
        return -1;

    }
};

class Solution {
public:
    int lengthAfterTransformations(string s, int t) {
        // a -> 26, ab
        // b -> 26, bc
        // ...
        // y -> 26, yz

        // z -> 1, ab
        // ab -> 24, yz
        // yz -> 1, zab
        // z -> 26, zab

        constexpr int MOD = 1e9 + 7;
        long cnts[26] = {};
        for (char c : s) ++cnts[c - 'a'];
        while (t >= 26) {
            long tmp[26] = {};
            for (int i = 0; i < 25; ++i) tmp[i + 1] += cnts[i];
            tmp[0] += cnts[25];
            tmp[1] += cnts[25];
            for (int i = 0; i < 26; ++i) {
                cnts[i] += tmp[i];
                cnts[i] %= MOD;
            }
            t -= 26;
        }

        long ans = 0;
        for (int i = 0; i < 26; ++i) {
            ans += cnts[i];
            if (i + t >= 26) ans += cnts[i];
            ans %= MOD;
        }
        return ans % MOD;
    }
};

constexpr unsigned MOD = 1000000007;

const auto add = [] (unsigned lhs, unsigned rhs) {
    const unsigned ans = lhs + rhs;
    return ans < MOD ? ans: ans - MOD;
};

const auto sub = [] (unsigned lhs, unsigned rhs) {
    const unsigned ans = lhs - rhs;
    return ans < MOD ? ans: ans + MOD;
};

const auto mul = [] (unsigned lhs, unsigned rhs) {
    return unsigned(1ull * lhs * rhs % MOD);
};

unsigned qpow(unsigned a, unsigned n) {
    unsigned ans = 1;
    for (;n > 0;n >>= 1) {
        if (n & 1) ans = mul(ans, a);
        a = mul(a, a);
    }
    return ans;
}

class Solution {
public:
    int lengthAfterTransformations(string s, int t, const vector<int>& nums) {
        unsigned buf[52];
        auto cur_cnt = buf;
        auto pre_cnt = buf + 26;
        fill_n(pre_cnt, 26, 0);
        for (char c : s)
            ++pre_cnt[c - 'a'];
        unsigned arr[52];
        arr[0] = s.size();
        vector<unsigned> pre, cur = {0};
        unsigned pre_d = arr[0];
        unsigned cnt = 1;
        for (unsigned i = 1;i < min(52, t + 1);++i) {
            // 差分优化 dp
            fill_n(cur_cnt, 26, 0);
            for (unsigned j = 0;j < 26;++j) {
                const unsigned l = (j + 1) % 26, r = l + nums[j];
                cur_cnt[l] = add(cur_cnt[l], pre_cnt[j]);
                if (r < 26)
                    cur_cnt[r] = sub(cur_cnt[r], pre_cnt[j]);
                else if (r > 26) {
                    cur_cnt[0] = add(cur_cnt[0], pre_cnt[j]);
                    cur_cnt[r - 26] = sub(cur_cnt[r - 26], pre_cnt[j]);
                }
            }
            for (unsigned j = 1;j < 26;++j)
                cur_cnt[j] = add(cur_cnt[j], cur_cnt[j - 1]);
            arr[i] = reduce(cur_cnt, cur_cnt + 26, 0ull) % MOD;
            swap(cur_cnt, pre_cnt);
            // Berlekamp–Massey 算法
            unsigned cur_d = arr[i];
            const unsigned l = cur.size();
            for (unsigned j = 0;j < l;++j)
                cur_d = sub(cur_d, mul(cur[j], arr[i - j - 1]));
            if (cur_d == 0) {
                ++cnt;
                continue;
            }
            const unsigned k = mul(cur_d, qpow(pre_d, MOD - 2));
            if (2 * l > i) {
                cur[cnt - 1] = add(cur[cnt - 1], k);
                for (unsigned j = 0;j < pre.size();++j)
                    cur[j + cnt] = sub(cur[j + cnt], mul(k, pre[j]));
                ++cnt;
            } else {
                auto tmp = cur;
                cur.resize(i + 1 - l, 0);
                cur[cnt - 1] = add(cur[cnt - 1], k);
                for (unsigned j = 0;j < pre.size();++j)
                    cur[j + cnt] = sub(cur[j + cnt], mul(k, pre[j]));
                pre = move(tmp);
                pre_d = cur_d;
                cnt = 1;
            }
        }
        const auto coff = cur.data();
        const unsigned l = cur.size();
        if (t < 52)
            return arr[t];
        else if (l == 0)
            return 0;
        else if (l == 1)
            return mul(arr[0], qpow(coff[0], t));
        else {
            // 常系数线性递推
            const auto polymul = [coff, l, &buf] (const unsigned* lhs, const unsigned* rhs, unsigned* ans) {
                fill_n(buf, 2 * l - 1, 0);
                for (unsigned i = 0;i < l;++i)
                    if (lhs[i] != 0)
                        for (unsigned j = 0;j < l;++j)
                            buf[i + j] = add(buf[i + j], mul(lhs[i], rhs[j]));
                for (unsigned i = 2 * l - 2;i >= l;--i)
                    if (buf[i] != 0)
                        for (unsigned j = 0;j < l;++j)
                            buf[i - j - 1] = add(buf[i - j - 1], mul(buf[i], coff[j]));
                copy_n(buf, l, ans);
            };
            unsigned base[26] = {};
            unsigned prod[26] = {};
            base[1] = prod[0] = 1;
            for (;t > 0;t >>= 1) {
                if (t & 1) polymul(base, prod, prod);
                polymul(base, base, base);
            }
            return inner_product(prod, prod + l, arr, 0ull, plus<uint64_t>{}, mul) % MOD;
        }
    }
};

using LL = long long;
constexpr int NN = 1e3;
constexpr int MOD = 1e9+7;

int dp_v[NN]={0, 0};
int dp_sel[NN][NN] = {0};
// int dp_n[NN];
bool inited = false;

void init(){
    if(!inited){
        inited = true;
        for(int v=2; v<NN; ++v){
            int s = 0, x = v;
            while(x>0){
                s += x&1;
                x >>= 1;
            }
            dp_v[v] = dp_v[s]+1;
        }
        for(int i=0; i<NN; ++i){
            dp_sel[i][0] = dp_sel[i][i] = 1;
            for(int j=1; j<i; ++j){
                dp_sel[i][j] = (dp_sel[i-1][j]+dp_sel[i-1][j-1])%MOD;
            }
        }
    }
}

class Solution {
public:
    int countKReducibleNumbers(string s, int k) {
        int n = s.size();
        LL ans = 0;
        init();
        // memset(dp_n, 0, sizeof(dp_n));
        for(int v=1; v<n; ++v){
            if(dp_v[v]<k){
                //
                printf("try v=%d, dp_v=%d\n", v, dp_v[v]);
                for(int i=1, t=0; t<=v and i<=n; ++i){
                    if(s[i-1]=='1' and v-t<=n-i){
                        ans += dp_sel[n-i][v-t];
                    }
                    t += s[i-1]-'0';
                }
            }
        }
        return ans % MOD;
    }
};

class Solution {
public:
    int buttonWithLongestTime(vector<vector<int>>& events) {

        int max_id = events[0][0];
        int max_press_time = events[0][1];

        for (int i = 1; i < events.size(); i++) {
            if (events[i][1] - events[i - 1][1] > max_press_time) {
                max_id = events[i][0];
                max_press_time = events[i][1] - events[i - 1][1];
            }
            else if (events[i][1] - events[i - 1][1] == max_press_time) {
                if (events[i][0] < max_id) { max_id = events[i][0]; }
            }
        }   
        return max_id;

    }
};

class Solution{
    public:
int dfs(int i, int p, vector<vector<int>> &al, int k) {
    if (k <= 0)
        return k == 0;
    int res = 1;
    for (int j : al[i])
        if (j != p)
            res += dfs(j, i, al, k - 1);
    return res;
}
vector<vector<int>> adjacencyList(vector<vector<int>>& edges) {
    vector<vector<int>> al(edges.size() + 1);
    for (auto &e: edges) {
        al[e[0]].push_back(e[1]);
        al[e[1]].push_back(e[0]);            
    }        
    return al;
}
vector<int> maxTargetNodes(vector<vector<int>>& e1, vector<vector<int>>& e2, int k) {
    int m = e1.size() + 1, n = e2.size() + 1, max2 = 0;
    auto al1 = adjacencyList(e1), al2 = adjacencyList(e2);
    vector<int> res(m);
    for (int i = 0; i < n; ++i)
        max2 = max(max2, dfs(i, -1, al2, k - 1));
    for (int i = 0; i < m; ++i)
        res[i] = max2 + dfs(i, -1, al1, k);        
    return res;
}
};

class Solution {
public:
    long long calculateScore(string s) {
        vector<vector<int>> prev_chars(26);
        long long score = 0;
        int inv_index;
        for(int i = 0; i < s.size(); i++) {
            inv_index = 25 - (s[i] - 'a');
            if (prev_chars[inv_index].empty()) {
                prev_chars[25 - inv_index].push_back(i);
            } else {
                score += (i - prev_chars[inv_index].back());
                prev_chars[inv_index].pop_back();
            }
        }
        return score;
    }
};

class Solution {
public:
    bool isBalanced(string num) {
        int n=num.size();
        int s1=0;
        int s2=0;
        for(int i=0;i<n;i++){
            if(i%2==0){
                s1+=num[i]-'0';

            }
            else{
                s2+=num[i]-'0';
            }
        }
        if(s1==s2) return true;
        else return false;
    }
};

