class Solution {
public:
    const long long mod = 1e9 + 7;
    vector<long long> freq, fact, ifact;
    long long n, sum;
    vector<vector<vector<long long>>> dp;

    long long binpow(long long a, long long b, long long m) {
        a %= m;
        long long res = 1;
        while (b > 0) {
            if (b & 1)
                res = res * a % m;
            a = a * a % m;
            b >>= 1;
        }
        return res;
    }

    long long count(long long id, long long take, long long cs) {
        if (id == 10) {
            if (take == n / 2 && 2 * cs == sum) {
                return (1LL * fact[n / 2] % mod * fact[(n + 1) / 2] % mod) % mod;
            } else {
                return 0;
            }
        }
        if (dp[id][take][cs] != -1) {
            return dp[id][take][cs];
        }
        long long ways = 0;
        for (long long i = 0; i <= min(freq[id], n / 2 - take); i++) {
            ways = (ways%mod + (1LL * ifact[i] % mod * ifact[freq[id] - i] % mod) % mod * count(id + 1, take + i, cs + i * id) % mod) % mod;
        }
        return dp[id][take][cs] = ways;
    }

    int countBalancedPermutations(string num) {
        n = num.size();
        sum = 0;
        freq.resize(10, 0);
        fact.resize(n + 1, 1);
        ifact.resize(n + 1);

        for (long long i = 0; i < n; i++) {
            freq[num[i] - '0']++;
            sum += (num[i] - '0');
        }

        if (sum % 2) {
            return 0;
        }

        for (long long i = 1; i <= n; i++) {
            fact[i] = (1LL * fact[i - 1] * i) % mod;
        }

        for (long long i = 0; i <= n; i++) {
            ifact[i] = binpow(fact[i], mod - 2, mod) % mod;
        }

        dp.resize(10, vector<vector<long long>>(n + 1, vector<long long>(sum + 1, -1)));
        return count(0, 0, 0) % mod;
    }
};

class Solution {
public:
    bool isZeroArray(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<int> v(n+1);

        for(int i=0;i<queries.size();i++){
            v[queries[i][0]]++;
            v[queries[i][1]+1]--;
        }
        int p = 0;
        for(int i=0;i<v.size();i++){
            p += v[i];
            v[i] = p;
        }

        for(int i=0;i<n;i++){
            if(nums[i]-v[i]>0)return false;
        }

        return true;
    }
};

class Solution {
    int maxFrequencyToNum(vector<int>& nums, int k, int numOperations) {
        int n = nums.size(), ans = 0, curr_num_freq = 0;
        for(int i = 0, l = 0, r = 0; i < n; i++) {
            if (i > 0 && nums[i] != nums[i - 1]) curr_num_freq = 1;
            else curr_num_freq++;

            while(r < n && nums[r] - nums[i] <= k) {
                r++;
            }
            while (l < i && nums[i] - nums[l] > k) {
                l++;
            }
            // l is within bounds, r is out of bounds
            int left_ops = i - l + 1 - curr_num_freq, right_ops = r - i - 1;
            ans = max(ans, min(numOperations, left_ops + right_ops) + curr_num_freq);
        }
        return ans;
    }
    int maxFrequencyNotNum(vector<int>& nums, int k, int numOperations) {
        int n = nums.size(), ans = 0;
        for(int r = 0, l = 0; r < n; r++) {
            while (l < r && nums[r] - nums[l] > 2 * k) {
                l++;
            }
            ans = max(ans, min(numOperations, r - l + 1));
        }
        return ans;
    }
public:
    int maxFrequency(vector<int>& nums, int k, int numOperations) {
        sort(nums.begin(), nums.end());
        return max(maxFrequencyToNum(nums, k, numOperations), maxFrequencyNotNum(nums, k, numOperations));
    }
};

class Solution {
public:
// https://www.youtube.com/watch?v=Ap8NIgIqM2A
    int minZeroArray(vector<int>& nums, vector<vector<int>>& queries) {
        int n=nums.size();
        vector<int> diff(n+1,0);
        int sum=0;
        int pos=0;
        for(int i=0;i<n;++i){
            while(sum + diff[i] < nums[i]){
                if(pos==queries.size())//All Queries done?
                    return -1;

                int start = queries[pos][0];
                int end = queries[pos][1];
                int val = queries[pos][2];
                pos++;

                if(end < i) continue; //Skip past update

                //Range update in O(1)
                diff[max(start,i)]+=val;
                diff[end+1]-=val;
            }
            sum += diff[i];
        }
        return pos;
    }
};

class Solution {
public:
    int minimumSumSubarray(vector<int>& nums, int l, int r) {
        int n=nums.size();
        int minSum=INT_MAX;
        bool flag=false;
        for(int i=0;i<n;i++){
            int sum=0;
            for(int j=i;j<n;j++){
                sum+=nums[j];
                int len=j-i+1;
                if(len>=l && len<=r && sum>0){
                    minSum=min(minSum,sum);
                    flag=true;
                }
            }
        }
        return flag? minSum : -1;
    }
};

