class Solution {
public:
    // main idea is to calculate the count of good subseq ending at value(val) at index i from [0...i-1]
    // whyvalue not index -> since to calculate dp[3] (val =3) = 1+dp[2]  and also dp[4]
    // we dont need index (since before morethan one index might havve value 2)
    // we will use value

    int mod = 1e9+7;
    int sumOfGoodSubsequences(vector<int>& nums) {
        int maxValue = 100001;
        vector<long> dp(maxValue,0); // to count the number of good sebseq ending at value = val
        vector<long> sum(maxValue,0); // to get the sum of good sebseq ending at value = val

        for(auto &it: nums){
            dp[it] = (dp[it] + 1) % mod; // adding a single count;
            sum[it] = (sum[it] + it) % mod; // adding one time;

            // checking for oneless value
            if(it-1 >= 0 && dp[it-1] > 0){
                dp[it] = (dp[it] + dp[it-1])%mod;
                sum[it] = (sum[it] + (sum[it-1] + (it * dp[it-1]) % mod) % mod )%mod;
            }
            // checking for oneGreater value
            if(it+1 < maxValue && dp[it+1] > 0){
                dp[it] = (dp[it] + dp[it+1])%mod;
                sum[it] = (sum[it] + (sum[it+1] + (it * dp[it+1]) % mod) % mod)%mod;
            }
        }

        long long ans = 0;
        for(int i=0;i<maxValue;i++){
            ans = (ans+sum[i])%mod;
        }
        return (int)ans;

    }
};

class Solution {
public:
    int maxRemoval(vector<int>& nums, vector<vector<int>>& queries) {
        int n=nums.size();
        vector<vector<int>> qTonum(n);
        for(auto &it : queries){
            qTonum[it[0]].push_back(it[1]);
        }
        // cout << (1<-2) << endl;
        priority_queue<int> q;
        vector<int> removed(n+2);
        int cur = 0;
        int res = 0;
        for(int i=0; i<n; i++){
            for(auto &it : qTonum[i]){
                q.push(it);
            }
            cur+=removed[i];
            // cout << cur << nums[i] << q.size() << endl;
            // cout << q.size() << (nums[i]-cur) << (q.size() < (nums[i]-cur)) << endl;
            int cnt = max(0, nums[i]-cur);
    //         cout << "Index: " << i << ", Need: " << nums[i] << ", Adjusted: " << (nums[i]-cur)
    //  << ", Available ops: " << q.size() << endl;
            while(!q.empty() && cnt > 0){
                int j = q.top();
                q.pop();
                if(j < i) {
                    res++;
                    break;
                }
                cur++;
                // cout << j << " ";
                removed[j+1]--;
                cnt--;
            }
            if(cnt > 0) return -1;
        }
        return q.size()+res;
    }
};

class Solution {
public:
    int maxCollectedFruits(vector<vector<int>>& fruits) {
        int const n = fruits.size();
        int top = fruits[0][n-1];

        int dp[n][n];

        for (int r = 0; r<n; r++){
            for (int c = 0; c<n; c++){
                dp[r][c] = 0;
            }
        }

        dp[0][n-1] = fruits[0][n-1];
        dp[n-1][0] = fruits[n-1][0];
        dp[0][0] = fruits[0][0];


        for (int r = 1; r<n-1; r++){
            for (int c = max(n- 1 - r,r+1); c<n; c++){
                dp[r][c] = dp[r-1][c];
                if (c + 1 < n){
                    dp[r][c] = max(dp[r][c],dp[r-1][c+1]);
                }

                if (c-1>=r){
                    dp[r][c] = max(dp[r][c],dp[r-1][c-1]);
                }

                dp[r][c] += fruits[r][c];
            }
        }

        for (int c = 1; c<n-1; c++){
            for (int r = max(n- 1 - c,c+1); r<n; r++){
                dp[r][c] = dp[r][c-1];
                if (r + 1 < n){
                    dp[r][c] = max(dp[r][c],dp[r+1][c-1]);
                }

                if (r-1>=c){
                    dp[r][c] = max(dp[r][c],dp[r-1][c-1]);
                }

                dp[r][c] += fruits[r][c];
            }
        }

        for (int i = 1; i<n; i++){
            dp[i][i] = dp[i-1][i-1] + fruits[i][i];
        }



        return dp[n-2][n-1] + dp[n-1][n-2] + dp[n-1][n-1];

    }
};

class Solution {
    int dp[256][100];
public:
    int recursion(int locks, int x, int k, const vector<int>& strength)
    {
        if(locks == (1<<(strength.size()))-1)
        return 0;
        if(dp[locks][x]!=-1)
        return dp[locks][x];
        int cost=INT_MAX;
        for(int i=0;i<strength.size();i++)
        {
            if(locks & (1<<i))
            continue;//alreeady broken
            //break this locak
            // cout<<i;

            cost = min((double)cost,ceil(strength[i]/(double)x) + recursion(locks | (1<<i), x+k,k,strength) );
        }
        return dp[locks][x] = cost;
    }
    int findMinimumTime(vector<int>& strength, int k) {
        //state is  x, int  - state of locks
        // 80 * 2^8
        //at every step we chose one of remainng locks in 8 time steps
        //then we can easily find time to break this lock and move on
        memset(dp,-1,sizeof(dp));
        return recursion(0,1,k,strength);
    }
};

class Solution {
public:
    vector<int> constructTransformedArray(vector<int>& nums) {
        int n = nums.size();
        vector<int> result(n);
        for (int i = 0; i < n; i++) {
            result[i] = nums[(i + (nums[i] % n) + n) % n];
        }
        return result;
    }
};

class Solution {
public:
    long long maxSubarraySum(vector<int>& nums, int k) {
        long long ans = LLONG_MIN;
        int m = nums.size();
        vector<long long> minPSum(k); // be noted prefix sum can go negative
        // Important, for prefixSum[k-1], prefixSum[2k-1], ..., prefixSum[nk - 1]
        // to calculate all possible minimum prefix sum, it will need minPSum[-1] = 0
        // minPSum[-1] = 0 implies no element and it will be saved in minPSum[-1 + k]
        long long prefixSum = 0;
        for (int i = 0; i < m; i++) {
            prefixSum += nums[i];
            if (i < k - 1) { // first time prefix sum, minPSum[k-1] needs to compare with '0'
                minPSum[i] = prefixSum;
                continue;
            }
            int j = i % k; // circular array index
            ans = max(ans, prefixSum - minPSum[j]);
            // update minimum prefix sum
            minPSum[j] = min(minPSum[j], prefixSum);
        }
        return ans;
    }
};

