class Solution {
 public:
  bool checkValidCuts(int n, vector<vector<int>>& rectangles) {
    int m = rectangles.size();
    vector<pair<int, int>> row, col;
    for (auto& r : rectangles) {
      row.emplace_back(r[0], r[2]);
      col.emplace_back(r[1], r[3]);
    }
    return check(row) || check(col);
  }

 private:
  bool check(vector<pair<int, int>>& arr) {
    sort(arr.begin(), arr.end());
    int cnt = 0, R = -1;
    for (auto [l, r] : arr) l >= R ? ++cnt, R = r : R = max(R, r);
    return cnt >= 3;
  }
};

