class Solution {
 public:
  int countPathsWithXorValue(vector<vector<int>>& grid, int k) {
    int n = grid.size(), m = grid[0].size();
    vector dp(n, vector(m, vector<long long>(16)));
    dp[0][0][grid[0][0]] = 1;

    for (int i = 0; i < n; ++i)
      for (int j = 0; j < m; ++j)
        for (int l = 0; l < 16; ++l)
          if (dp[i][j][l]) {
            if (i + 1 < n)
              (dp[i + 1][j][l ^ grid[i + 1][j]] += dp[i][j][l]) %= 1000000007;
            if (j + 1 < m)
              (dp[i][j + 1][l ^ grid[i][j + 1]] += dp[i][j][l]) %= 1000000007;
          }
    return dp[n - 1][m - 1][k];
  }
};

const int N = 1e5+10 ;
vector<array<int,2>> e[N] ;
bool vis[N] ;
class Solution {
public:
    long long maximizeSumOfWeights(vector<vector<int>>& edges, int k) {
        int n = edges.size() ;
        for(int i=0; i<=n; i++) 
            e[i].clear(), vis[i]=0 ;
        for(auto &it:edges){
            e[it[0]].push_back({it[1], it[2]}) ;
            e[it[1]].push_back({it[0], it[2]}) ;
        }
        long long ret=0 ;
        for(int i=0; i<=n; i++)
            if(!vis[i])
                ret += dfs(0, k).second ;
        return ret ;
    }
    pair<long long, long long> dfs(int u, int lim){
        vis[u]=1 ;
        auto ret = make_pair(0ll,0ll) ;
        vector<long long> alls ;
        for(auto [v, c]:e[u]){
            if(vis[v]) continue ;
            auto it = dfs(v, lim) ;
            ret.first+=it.second ;
            ret.second+=it.second ;
            alls.push_back({c+it.first-it.second}) ; 
        }
        sort(alls.begin(), alls.end()) ;
        reverse(alls.begin(), alls.end()) ;
        for(long long x:alls){
            if(x<=0) break ;
            ret.second += x ;
            if(--lim==0) break ; // 513703314
            ret.first += x ;     // 799038587
        }
        return ret ;
    }
};

