class Solution {
public:
    int maximumAmount(vector<vector<int>>& coins) {
        int m = coins.size(), n = coins[0].size();
        // dp[i][j][k]：走到(i,j)，用了k次技能的最大收益
        vector<vector<vector<int>>> dp(m, vector<vector<int>>(n, vector<int>(3, INT_MIN)));

        // 初始化起点
        for (int k = 0; k <= 2; ++k) {
            if (coins[0][0] >= 0)
                dp[0][0][k] = coins[0][0];
            else if (k > 0)
                dp[0][0][k] = 0;
            else
                dp[0][0][k] = coins[0][0];
        }

        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                for (int k = 0; k <= 2; ++k) {
                    if (i == 0 && j == 0) continue;

                    int val = coins[i][j];
                    int noShield = val;          // 不用技能
                    int useShield = max(0,val); // 用技能，负数变0，正数不变

                    // 从上或左来
                    if (i > 0) {
                        if (dp[i - 1][j][k] != INT_MIN)
                            dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k] + noShield);
                        if (val < 0 && k > 0 && dp[i - 1][j][k - 1] != INT_MIN)
                            dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k - 1] + useShield);
                    }
                    if (j > 0) {
                        if (dp[i][j - 1][k] != INT_MIN)
                            dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k] + noShield);
                        if (val < 0 && k > 0 && dp[i][j - 1][k - 1] != INT_MIN)
                            dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k - 1] + useShield);
                    }
                }
            }
        }

        return max({dp[m - 1][n - 1][0], dp[m - 1][n - 1][1], dp[m - 1][n - 1][2]});
    }
};

class Solution {
public:
    vector<int> parent;

    int getp(int x){
        if(parent[x]==x) return x;
        return parent[x]=getp(parent[x]);
    }

    void unon(int a,int b){
        a=getp(a);
        b=getp(b);
        if(a==b) return;
        parent[b]=a;
    }

    int countComponents(vector<int>& nums, int th) {
        sort(nums.begin(),nums.end());

        int n=nums.size();
        parent=vector<int> (nums.size(),0);
        for(int i=0;i<n;i++) parent[i]=i;
        vector<int> v(th+1,-1);
        for(int i=0;i<n;i++){
            for(int j=nums[i];j<=th;j+=nums[i]){
                if(v[j]==-1){
                    v[j]=i;
                }
                else{
                    unon(i,v[j]);
                    if(nums[i]==j) break;
                }
            }
        }
        int ans=0;
        for(int i=0;i<n;i++){
            if(parent[i]==i) ans++;
        }
        return ans;

    }
};

class Solution {
public:
    int maxRectangleArea(vector<vector<int>>& points) {

        set<pair<int, int> >input_points;
        int max_area = INT_MIN;

        for(auto &point: points)
        {
            input_points.insert({point[0], point[1]});
        }
        for(int i=0;i<points.size()-1;i++)
        {
            int point1_x = points[i][0];
            int point1_y = points[i][1];

            for(int j=i+1;j<points.size();j++)
            {
                int point2_x = points[j][0];
                int point2_y = points[j][1];

                if(point1_x==point2_x || point1_y==point2_y) continue;

                pair<int,int>new_point1 = {point1_x, point2_y};
                pair<int,int>new_point2 = {point2_x, point1_y};

                if(input_points.find(new_point1)!=input_points.end() && input_points.find(new_point2)!=input_points.end())
                {
                    int min_x = min(point1_x, point2_x);
                    int max_x = max(point1_x, point2_x);
                    int min_y = min(point1_y, point2_y);
                    int max_y = max(point1_y, point2_y);
                    bool valid = false;
                    for(auto &point: points)
                    {
                        int curr_x = point[0];
                        int curr_y = point[1];

                        if((curr_x==point1_x && curr_y==point1_y) || (curr_x==point2_x && curr_y==point2_y) || (curr_x==point1_x && curr_y==point2_y) || (curr_x==point2_x && curr_y==point1_y))
                        {
                            continue;
                        }

                        if(curr_x>=min_x && curr_x<=max_x && curr_y>=min_y && curr_y<=max_y)
                        {
                            valid = true;
                            break;
                        }
                    }
                    if(!valid)
                    {
                        max_area = max(max_area, (abs(point2_x-point1_x)*abs(point2_y-point1_y)));
                    }
                }
            }
        }
        if(max_area==INT_MIN) return -1;
        return max_area;
    }
};

