class Solution {
public:
    bool possible(string& s, int ops, int limit) {
        char currChar = s[0];
        int len = 1;
        for (int i=1; i<s.size(); i++) {
            if (s[i] == currChar) {len++;}
            else {
                int currOps = len / (limit+1);
                if (currOps>ops) {return false;}
                ops -= currOps;
                currChar = s[i];
                len = 1;
            }
        }
        int currOps = len / (limit+1);
        if (currOps>ops) {return false;}
        return true;
    }
    int minLength(string s, int numOps) {
        int op1 = 0; // How many flips are needed for 10101010101..;
        for (int i=0; i<s.size(); i+=2) {
            if (s[i] == '0') op1++;
        }
        for (int i=1; i<s.size(); i+=2) {
            if (s[i] == '1') op1++;
        }
        if (op1<=numOps || s.size()-op1<=numOps) return 1;
        int l = 1, r = s.size()+1;
        int m = (l+r)/2;
        while (m>l) {
            if (possible(s, numOps, m)) {r = m;}
            else {l = m;}
            m = (l+r)/2;
        }
        return m+1;
    }
};

class Solution {
public:
    int minimumOperations(vector<vector<int>>& grid) {
       const auto n{int(size(grid))};
        const auto m{int(size(grid.front()))};
        int res{};
        for(int j{};j<m;++j){
            for(int i{1};i<n;++i){
                auto d=grid[i][j]-grid[i-1][j];
                if(d<=0){
                    res+=-d+1;
                    grid[i][j]-=(d-1);
                }
            }
        }
        return res;
    }
};

