class Solution {
public:
    long long minCost(vector<int>& arr, vector<int>& brr, long long k) {
// Calculate original difference (without sorting)
        long long ans1 = 0LL;
        int n = arr.size();
        for(int i = 0; i < n; i++) {
            ans1 += abs(arr[i] - brr[i]);
        }

        // Sort both arrays
        sort(arr.begin(), arr.end());
        sort(brr.begin(), brr.end());

        // Calculate difference after sorting + cost k
        long long ans2 = k;
        for(int i = 0; i < n; i++) {
            ans2 += abs(arr[i] - brr[i]);
        }

        // Return the minimum cost
        return min(ans1, ans2);
    }
};

