class Solution {
  public:
    static vector<int> countMentions(int numberOfUsers, vector<vector<string>>& events) {
        std::ranges::sort(events, [](const auto& lhs, const auto& rhs) {
            auto t1 = std::stoi(lhs[1]);
            auto t2 = std::stoi(rhs[1]);
            if (t1 == t2) {
                return lhs[0] > rhs[0];
            }

            return t1 < t2;
        });
        std::vector<int> wake(numberOfUsers);
        std::vector<int> ret(numberOfUsers);
        auto processOffLine = [&](const std::string& time, const std::string& id) {
            auto t = std::stoi(time);
            auto i = std::stoi(id);
            wake[i] = t + 60;
        };

        auto processMention = [&](const std::string& time, const std::string& member) {
            if (member == "ALL") {
                for (auto& r : ret) {
                    r++;
                }
                return;
            }
            auto t = std::stoi(time);
            if (member == "HERE") {
                for (int i = 0; i < numberOfUsers; ++i) {
                    ret[i] += wake[i] <= t;
                }
                return;
            }
            std::stringstream ss{member};
            std::string buf;
            while (ss >> buf) {
                auto id = std::stoi(buf.substr(2));
                ret[id]++;
            }
        };

        for (auto& event : events) {
            if (event[0] == "OFFLINE") {
                processOffLine(event[1], event[2]);
            } else {
                processMention(event[1], event[2]);
            }
        }
        return ret;
    }
};

class Solution {
public:
    int sumOfGoodNumbers(vector<int>& nums, int k) {
        int total = 0;
        int n = nums.size();

        for (int i = 0; i < n; ++i) {
            bool leftMissing = (i - k < 0);
            bool rightMissing = (i + k >= n);

            if (leftMissing && rightMissing) {
                // Neither index exists → always good
                total += nums[i];
            }
            else if (leftMissing) {
                if (nums[i] > nums[i + k])
                    total += nums[i];
            }
            else if (rightMissing) {
                if (nums[i] > nums[i - k])
                    total += nums[i];
            }
            else {
                if (nums[i] > nums[i - k] && nums[i] > nums[i + k])
                    total += nums[i];
            }
        }

        return total;
    }
};

class Solution {
public:
    int subarraySum(vector<int>& nums) {
        int n = nums.size();
        vector<int>prefix_sum(n,0);
        prefix_sum[0] = nums[0];
        int res = 0;
        for(int i = 1;i<n;i++)
          {
             prefix_sum[i] = prefix_sum[i-1] + nums[i];
          }
        for(int i = 0;i<n;i++)
          {
              int start = max(0,i-nums[i]);
              int temp;
              if(start  == 0)
               {
                 temp = prefix_sum[i] ;
               }
               else
               {
                temp = prefix_sum[i] - prefix_sum[start-1];
               }
            res += temp;
          }
          return res;
    }
};

