class Solution {
public:
    vector<vector<int>>grid;
    vector<vector<int>>dirs = {{-1,1},{1,1},{1,-1},{-1,-1}};
    int n;
    int m;
    int lenOfVDiagonal(vector<vector<int>>& grid) {
        m = grid.size();
        n = grid[0].size();
        this->grid = grid;
        int ans = 0;
        for(int i = 0;i < m;i++){
            for(int j = 0;j < n;j++){
                if(grid[i][j]==1){
                    ans = max(ans,1);
                    ans = max({ans,dfs(i,j,0,false,2)
                                  ,dfs(i,j,1,false,2)
                                  ,dfs(i,j,2,false,2)
                                  ,dfs(i,j,3,false,2)});
                }
            }
        }
        return ans;
    }
    int dfs(int i,int j,int dir,bool turned,int target){
        int x=i+dirs[dir][0];
        int y=j+dirs[dir][1];
        if(x<0||x>=m||y<0||y>=n||grid[x][y]!=target)return 1;
        //Either :STRAIGHT.
        int straight = 1+dfs(x,y,dir,turned,target==2?0:2);
        int turn = 1;
        //Or: TURNED.
        if(!turned){
            turn = 1+dfs(x,y,(dir+1)%4,true,target==2?0:2);
        }
        return max(straight,turn);
    }
};

class Solution {
public:
    string findValidPair(string s) {
        int freq[10] = {0};
        for (char ch : s)
            freq[ch - '0']++;
        string answer = "";
        for (int i = 0; i < s.size() - 1; i++) {
            if (s[i] != s[i + 1]) {
                if (freq[s[i] - '0'] == s[i] - '0' &&
                    freq[s[i + 1] - '0'] == s[i + 1] - '0') {
                    answer = {s[i], s[i + 1]};
                    break;
                }

            }
        }
        return answer;
    }
};

class Solution {
public:
        long long minCost(int n, vector<vector<int>>& cost) {
        long dp1[6] = {}, dp2[6];
        for (int i = n / 2; i < n; i++) {
            dp2[0] = cost[i][0] + cost[n-i-1][1] + min(dp1[2], min(dp1[3], dp1[4]));
            dp2[1] = cost[i][0] + cost[n-i-1][2] + min(dp1[3], min(dp1[4], dp1[5]));
            dp2[2] = cost[i][1] + cost[n-i-1][2] + min(dp1[0], min(dp1[4], dp1[5]));
            dp2[3] = cost[i][1] + cost[n-i-1][0] + min(dp1[0], min(dp1[1], dp1[5]));
            dp2[4] = cost[i][2] + cost[n-i-1][0] + min(dp1[0], min(dp1[1], dp1[2]));
            dp2[5] = cost[i][2] + cost[n-i-1][1] + min(dp1[1], min(dp1[2], dp1[3]));
            swap(dp1, dp2);
        }
        return *min_element(dp1, dp1 + 6);
    }
};

class Solution {
public:
    int distanceSum(int m, int n, int k) {
        return C_n_k(static_cast<long long>(m) * n - 2, k - 2) *
            (solve_one_dim_one_pair(m, n) + solve_one_dim_one_pair(n, m)) % kMod;
    }

private:
    static constexpr long long kMod = 1e9 + 7;
    static constexpr long long kMaxMN = 1e5;

    struct CnkCalculator {
        vector<long long> fac;
        vector<long long> rac;

        CnkCalculator(int max_n = 1e5) : fac(1, 1), rac(1, 1) {
            ensure_fac(max_n);
        }

        long long operator()(int N, int k) {
            ensure_fac(N);
            return (fac[N] * rac[k] % kMod) * rac[N - k] % kMod;
        }

        void ensure_fac(size_t n) {
            while (fac.size() <= n) {
                fac.push_back(fac.back() * fac.size() % kMod);
                rac.push_back(rev(fac.back()));
            }
        }

        long long rev(long long v) {
            return qpow(v, kMod - 2);
        }

        long long qpow(long long b, long long p) {
            long long res = 1;
            for (; p; p >>= 1, b = b * b % kMod)
                if (p & 1)
                    res = res * b % kMod;
            return res;
        }
    };

    static CnkCalculator C_n_k;

    long long solve_one_dim_one_pair(long long m, long long n) {
/*
        long long res = 0;
        for (long long i = 1; i < n; ++i)
            res += i * (i + 1) / 2;
        return m * m * res % kMod;
*/
        long long res = (n - 1) * n / 2;       // sum of first n-1 integers
        res = res * (n + 1) / 3;               // turns it into sum of triangular numbers
        return m * m % kMod * res % kMod;
    }
};

