class Solution {
public:
    int maxFreeTime(int eventTime, vector<int>& startTime, vector<int>& endTime) {
        int ans=startTime[0];
        if(startTime.size()>1) ans=max(ans,startTime[1]-(endTime[0]-startTime[0]));
        else ans=max(ans,eventTime-(endTime[0]-startTime[0]));
        int premax=startTime[0];
        for(int i=1;i<startTime.size()-1;i++){
            int sz=endTime[i]-startTime[i];
            int gap=startTime[i+1]-endTime[i-1];
            if(sz<=premax) ans=max(ans,gap);
            else ans=max(ans,gap-sz);
            premax=max(premax,startTime[i]-endTime[i-1]);
        }
        if(startTime.size()>1 && endTime.back()-startTime.back()<=premax) ans=max(ans,eventTime-endTime[endTime.size()-2]);
        ans=max(ans,eventTime-endTime.back());
        cout<<ans<<endl;
        if(startTime.size()>1) ans=max(ans, eventTime-endTime[endTime.size()-2]-(endTime.back()-startTime.back()));
        premax=eventTime-endTime.back();
        for(int i=startTime.size()-2;i>0;i--){
            int sz=endTime[i]-startTime[i];
            int gap=startTime[i+1]-endTime[i-1];
            if(sz<=premax) ans=max(ans,gap);
            else ans=max(ans,gap-sz);
            premax=max(premax,startTime[i+1]-endTime[i]);
        }
        if(startTime.size()>1 && endTime[0]-startTime[0]<=premax) ans=max(ans,startTime[1]);

        return ans;
    }
};

class Solution {
public:
    int maxFreeTime(int eventTime, int k, vector<int>& startTime, vector<int>& endTime) {
        int n = startTime.size();
        vector<int> v(n+1,0);
        v[0] = startTime[0]-0;
        v[n] = eventTime-endTime[n-1];
        for(int i=1;i<n;i++){
            v[i] = startTime[i]-endTime[i-1];
        }
        int ans=0;
        int temp = 0;
        for(int i=0;i<(k+1);i++){
            temp +=v[i];
        }
        ans = max(ans,temp);
        for(int i = 1; i<=(n-k);i++){
            temp += (v[i+k] - v[i-1]);
            ans = max(ans,temp);
        }
        return ans;
    }
};

