class Solution {
public:
    vector<vector<int>> sortMatrix(vector<vector<int>>& grid) {
        int n=grid.size();
        for(int i=n-1;i>=0;i--){
            vector<int>s(n-i);
            for(int j=i,k=0;j<n;k++,j++){
                s[k]=grid[j][k];
            }
            sort(s.begin(),s.end(),greater<int>());
            for(int j=i,k=0;j<n;k++,j++){
                grid[j][k]=s[k];
            }
        }
         for(int i=1;i<n;i++){
            vector<int>s(n-i);
            for(int j=i,k=0;j<n;k++,j++){
                s[k]=grid[k][j];
            }
            sort(s.begin(),s.end());
            for(int j=i,k=0;j<n;k++,j++){
                grid[k][j]=s[k];
            }
        }
        return grid;
    }
};

class Solution {
public:
    int maxDifference(string s) {
        vector<char> freq(26,0);
        for(int i=0;i<s.size();i++)
            freq[s[i]-'a']++;
        sort(freq.begin(),freq.end());
        int oddFreq = 1,evenFreq = 1;
        for(int i=25;i>=0;i--)
            if(freq[i]!=0 && freq[i]%2==0)
                evenFreq = freq[i];
        for(int i=0;i<26;i++)
            if(freq[i]%2==1)
                oddFreq = freq[i];
        return oddFreq - evenFreq;
    }
};

class Solution {
public:
    vector<int> assignElements(vector<int>& groups, vector<int>& elements) {
        int n = groups.size(), defaultIdx = -1;
        int maxSize = *max_element(groups.begin(), groups.end());

        vector<int> sieve(maxSize+1, defaultIdx);

        for (int i = 0; i < elements.size(); ++i) {
            int element = elements[i];
            if (element == 1) {
                defaultIdx = i;
                break;
            }

            if (element > maxSize or sieve[element] != -1) {
                continue;
            }

            for (int val = element; val <= maxSize; val += element) {
                if (sieve[val] == -1) {
                    sieve[val] = i;
                }
            }
        }

        vector<int> result;
        for (int i = 0; i < n; ++i) {
            int groupSize = groups[i];
            result.push_back(sieve[groupSize] == -1 ? defaultIdx : sieve[groupSize]);
        }
        return result;
    }
};

