class Solution {
public:
    double squaresChecker(const double mid, vector<vector<int>>& squares)
    {
        double above = 0.0;
        double below = 0.0;
        for (const vector<int>& square : squares)
        {
            //int x = square[0];
            int y = square[1];
            int l = square[2];

            if (mid <= y)
            {
                above += (double)l * l;
            }
            else if (mid >= y + l)
            {
                below += (double)l * l;
            }
            else
            {
                above += l * ((double)l - (mid - y));
                below += l * (mid - y);
            }
        }
        return above - below;
    }
    double separateSquares(vector<vector<int>>& squares)
    {
        // fast linear way to find true weight middle point
        /*double middle = 0.0;
        double total_weight = 0.0;
        for (const vector<int>& square : squares)
        {
            //int x = square[0];
            int y = square[1];
            int l = square[2];
            double mid_point = y + l * 0.5;
            double weight = l;

            middle = (middle * total_weight + mid_point * weight) / (total_weight + weight);
            total_weight += weight;
        }*/

        // compute intense part to find the lowest possible value of y
        double top = 2*1e9;
        double low = 0.0;
        double mid = 0.0;
        const double prec = 1e-5 * 0.5;
        for (int i = 0; i < 60; i++)
        {
            mid = (low + top) * 0.5;
            double res = squaresChecker(mid, squares);
            if (res != 0.0 && abs(res) < prec * 0.5) // precission is reached
                break;
            if (res > 0)
                low = mid;
            else
                top = mid;
        }
        return mid;
    }
};

class Solution {
public:
    bool hasSameDigits(string s) {
        int n = s.length();

        // Calculate binomial coefficients modulo 10 using Pascal's triangle
        vector<int> coef(n, 0);
        coef[0] = 1;
        for (int i = 0; i < n-2; i++) {
            for (int j = i+1; j > 0; j--) {
                coef[j] = (coef[j] + coef[j-1]) % 10;
            }
        }

        // Calculate the final two digits
        int digit1 = 0;
        int digit2 = 0;
        for (int i = 0; i < n-1; i++) {
            digit1 = (digit1 + coef[i] * (s[i] - '0')) % 10;
            digit2 = (digit2 + coef[i] * (s[i+1] - '0')) % 10;
        }

        return digit1 == digit2;
    }
};

